window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_011"]={"n":"胡奎","dyn":"明","poems":[{"t":"梦游庐山歌","f":"古风","c":["我有紫霞想，梦游匡庐峰。","仙人凌绝顶，手掉金芙蓉。","芙蓉亭亭九天上，叠嶂腾腾涌波浪。","五色云中白鹿鸣，三更海底金鸡唱。","悬崖瀑布从天来，匹练倒界青天开。","高人似是陆脩静，邀我石磴行莓苔。","九江秀色可揽结，欲跨长鲸捉明月。","望断蓬莱青鸟书，琪花落尽无人折。","飞身上挹香炉烟，坐我九叠屏风前。","翻然拜手招五老，一笑彷佛三千年。","松风泠泠吹梦觉，鹤背高寒露花落。","早知此境隔尘凡，只合栖神向丘壑。","何人写此江上山，云山与我心俱閒。","明当会碾飙轮去，长谢时人竟不还。"]},{"t":"北上行","f":"五言古诗","c":["食蜜不知苦，衣葛不知寒。","今晨出门去，始知行路难。","惊飙吹断蓬，沙碛何漫漫。","羸马缩如猬，霜花大于钱。","夜涉黄河冻，舟行不得前。","君肠辘轳转，我肠车轮盘。","王事有严程，去去勿惮烦。","弯弧落旄头，飞箭定天山。","会赋《铙歌》曲，论功万里还。"]},{"t":"送徐千户之甘州","f":"七言律诗","c":["春寒初试越罗袍，不惜千金买宝刀。","马援橐中无薏苡，张骞槎上有蒲萄。","昆崙西去黄河远，函谷东来紫气高。","何事相逢又相别，陇云边月梦劳劳。"]},{"t":"江边柳","f":"五言绝句","c":["朝送木兰船，暮迎征马鞭。","非关离别苦，生长在江边。"]},{"t":"挽员外张士谔 其一","f":"七言绝句","c":["二仙坊里张员外，头白相逢只论诗。","今日过门君不见，小楼春雨燕归迟。"]},{"t":"题芦雁飞鸣宿食图","f":"七言绝句","c":["草草书空不作行，相呼相唤过衡阳。","芦花月冷应无梦，啄尽寒沙一夜霜。"]},{"t":"宿田家","f":"七言绝句","c":["村北村南社鼓声，閒寻父老说升平。","孤镫也识离人意，落尽寒花却再生。"]},{"t":"贞母阡","f":"七言律诗","c":["石门山前箭如雨，朝别良人暮为□。","石门山下百尺泉，一日身死哀千年。","至今石门山下路，人称烈妇禹家□。","墓前斜日一僧归，即是当年十岁儿。"]},{"t":"题瀛洲学士图 其二","f":"七言绝句","c":["铃索无声昼漏稀，宫袍一色换朝衣。","院门不锁松花落，知是銮坡进讲归。"]},{"t":"敬进宁王殿下仙人好楼居三章 其一","f":"五言古诗","c":["仙人好楼居，乃在青云中。","金窗洞然开，咫尺与天通。","上有太古音，被以龙门桐。","左招广成子，右揖浮丘公。","凭虚览八极，呼吸凌洪濛。","寿与天地并，逍遥乐无穷。"]},{"t":"敬进宁王殿下仙人好楼居三章 其二","f":"五言古诗","c":["仙人好楼居，乃在蔚蓝天。","东西九万里，日月相周旋。","上有飞霞佩，五凤何翩翩。","左招王子晋，右揖洪崖仙。","含和鍊金魄，至真洞玄玄。","无为以清净，寄傲羲皇前。"]},{"t":"敬进宁王殿下仙人好楼居三章 其三","f":"五言古诗","c":["仙人好楼居，下瞰凌虚台。","鸡鸣海色动，万里云霞开。","上有白玉虬，骑之上蓬莱。","左招梁园客，右引邹与枚。","吹笙弄明月，八鸾以裴回。","俯视一泓水，终古无纤埃。"]},{"t":"步虚词九首 其一","f":"五言律诗","c":["五气合大梵，三花凝素云。","冲妙混真朴，玄化荡无垠。","灵飙遵绛节，稽首虚皇君。","啸歌琼台上，飘飖鸾鹤群。"]},{"t":"步虚词九首 其二","f":"五言律诗","c":["寥寥蔚蓝天，曜灵开龙阳。","黄老维我神，玄精贯中央。","氤氲九天气，晃郎七星芒。","游燕玉京府，逍遥紫极房。"]},{"t":"步虚词九首 其三","f":"五言古诗","c":["九气合大梵，鸿濛启神霄。","上披三素云，灵宫郁岧峣。","群真翊羽盖，绛节凌回飙。","粲粲霏玉葩，琅琅歌洞谣。","凝神息万虑，遐龄比松乔。","稽首无为化，永言赞昌朝。"]},{"t":"步虚词九首 其四","f":"五言古诗","c":["玉虚运玄化，曜灵升大罗。","三景开天根，碧落浮空歌。","仰瞻弥罗馆，紫云覆峨峨。","缥缈金芙蓉，御以麒麟车。","九光分异采，万汇含冲和。","皈命希夷门，超然凌太霞。"]},{"t":"步虚词九首 其五","f":"五言古诗","c":["皇朝阐真教，慧风覃八埏。","琅函启灵篆，玉文简玄玄。","授以丹霞衣，回翔玉清天。","三精飞爽灵，五色凝非烟。","黄老维我神，专气长绵绵。","逍遥无极君，归真合自然。"]},{"t":"步虚词九首 其六","f":"五言律诗","c":["浩劫开隆运，鸿灵秉化机。","云章结丹篆，空洞启玄微。","九凤翼羽盖，八龙卫金扉。","授以赤玉文，丹霞为之衣。"]},{"t":"步虚词九首 其七","f":"五言古诗","c":["迢迢白玉京，上通蔚蓝天。","煌煌黍米珠，五色浮空悬。","包括无极际，虚明洞玄玄。","可望不可即，恍惚象帝先。","得此以为宝，逍遥以长年。"]},{"t":"步虚词九首 其八","f":"五言古诗","c":["万化同逆旅，百年等浮沤。","何不学神仙，汗漫与天游。","餐以旸谷霞，濯以星汉流。","左手招安期，右手揖浮丘。","傲睨八纮内，逍遥以忘忧。"]},{"t":"步虚词九首 其九","f":"五言古诗","c":["东窗绿玉树，锐叶何离离。","春秋八千岁，蟪蛄安得知。","至人有玄术，灵泉漱华池。","专气有真一，超然入无为。","会当保贞素，黄发以为期。"]},{"t":"登九天阁制步虚词 其一","f":"五言古诗","c":["龙汉还荡荡，琼宫郁峨峨。","九气结灵篆，千月印明河。","穆穆渝妙容，飘飘登大罗。","仙人绿云中，缥缈回空歌。","逍遥永无极，旸谷驻羲和。"]},{"t":"登九天阁制步虚词 其二","f":"五言古诗","c":["玉虚启真境，宝阁凌丹穹。","曜灵洞八窗，空响振回风。","绛节飘飖下，玄房曲密通。","中有古仙人，黄公与赤松。","飞霞为之佩，下上随云龙。"]},{"t":"九日登九天阁三首 其一","f":"五言古诗","c":["曜灵启旸谷，丹霞丽玄穹。","晨朝回绛节，群真集珠宫。","登高览八极，逸兴凌空濛。","中有古仙人，云是商山翁。","浩歌紫芝曲，此意无终穷。"]},{"t":"九日登九天阁三首 其二","f":"五言古诗","c":["九日良燕会，登高畅余怀。","凭虚发清啸，浩荡天风来。","金茎逼华盖，六符明泰阶。","排云叫阊阖，灵扉洞然开。","安得金衣鹄，乘之上蓬莱。"]},{"t":"九日登九天阁三首 其三","f":"五言古诗","c":["朝披碧瑶簪，夕登紫极房。","绮云纷郁郁，龙汉郁苍苍。","游神九霄外，恍忽觐虚皇。","相从赤松子，乃有韩张良。","安知千载后，跨鹤重来翔。"]},{"t":"登玉虚阁赋游仙词二首 其一","f":"五言古诗","c":["五山出东海，巨鳌十五头。","帝遣戴山足，勿使西南流。","至今云霞间，上有白玉楼。","琪树丽阳冈，瑶花被玄洲。","麻姑有书信，方平或未游。","寻真谅不远，怅望凌高秋。"]},{"t":"登玉虚阁赋游仙词二首 其二","f":"五言古诗","c":["琳宫倚虚碧，瑶海含清辉。","翩翩花鸟使，日暮云中归。","弱水隔玄圃，三山横翠微。","明月为我佩，丹霞为我衣。","天颜觐咫尺，晃朗朝金扉。"]},{"t":"游仙词","f":"五言古诗","c":["东海有麻姑，乃在三山岑。","去时海水浅，来时海水深。","翩翩三青鸟，结巢琪树林。","寄我锦字书，泠然空外音。","何由启玉齿，临风披素襟。"]},{"t":"所思四首 其一","f":"五言古诗","c":["郁郁我所思，所思在瀛洲。","黄金以为阙，白玉以为楼。","枯桑漂白日，弱水不容舟。","亭亭三珠树，别来已千秋。","仙人招我来，采药游丹丘。","饷我千岁桃，赠我五云裘。","长鲸鼓巨浪，欲往无安流。","因风寄寥廓，东望空悠悠。"]},{"t":"所思四首 其二","f":"五言古诗","c":["郁郁我所思，所思在泰山。","黄尘浩无际，碧海何漫漫。","金鸦夜中出，照耀青云端。","我欲乘飙轮，因之扣云关。","飞霞以为佩，明月以为环。","侧身望阊阖，天语咫尺间。","怀哉隔远道，铁锁何由攀。"]},{"t":"所思四首 其三","f":"五言古诗","c":["郁郁我所思，所思在华阳。","上有仙人掌，巉然倚穹苍。","玉井湛灵液，丹霞生洞房。","酒母呼子先，骑龙入云翔。","我欲往从之，凭虚览八荒。","黄河渺如带，一苇端可航。","麻姑傥相忆，寄我绿云章。"]},{"t":"所思四首 其四","f":"五言古诗","c":["郁郁我所思，所思在衡峰。","青云团紫盖，白日开芙蓉。","上有飞来泉，倒挂千尺虹。","思昔玉字书，允符神禹功。","九州既混一，百谷俱朝宗。","仙人骑白鹿，呦呦立云中。","何当鍊金液，日夕长相从。"]},{"t":"寄王鍊师","f":"五言古诗","c":["安期入东海，采药三蓬莱。","东窗绿玉树，岁岁见花开。","弭节昆丘圃，吹笙阆风台。","翱翔綵云里，挥手招我来。","安期双黄鹄，相从凌九垓。"]},{"t":"题雪舫馀清","f":"五言古诗","c":["回橹泊寒渚，雪月澹清晖。","岭云低欲度，沙禽静不飞。","悠悠江海心，尔独此忘机。"]},{"t":"题稼轩","f":"五言古诗","c":["交交桑扈鸣，时雨夜来至。","星言出东皋，田舍有生计。","天时与农功，黾勉焉敢弃。","春耕或少怠，何以遂秋刈。","古人皆食力，素餐良可愧。","伊人沮溺徒，遁迹澹忘世。","父菑子乃播，优游以卒岁。","余亦林野人，与尔颇同志。","怀哉惬素心，南山有真意。"]},{"t":"题庐山图","f":"五言古诗","c":["我昔梦五老，翱翔绿云中。","濯足银汉水，上与天门通。","仙人坐中峰，手持玉芙蓉。","邀我吹鸾笙，相期入空濛。","清猿夜啼月，梦回迥寥绝。","遥遥紫霞想，忽若千年别。","昔向梦中见，今从堂上看。","林峦如夙契，烟翠生高寒。","天风飒然来，颇觉衣裳单。","恍如陶弘景，置我长松间。","此境何时游，我梦难再续。","怅望九叠屏，白云满空谷。"]},{"t":"学古轩","f":"五言古诗","c":["张公志于学，古貌又古心。","尚友古之人，自言古犹今。","古人不复作，古道良可钦。","斋居古以朴，悠然澹冲襟。","手援绿绮琴，中有山水音。","愿扬太古调，一洗里耳音。"]},{"t":"题安分斋","f":"五言古诗","c":["鹏鹍运霄汉，鹪鴳栖蒿蓬。","小大各有适，动息无不同。","龙兴山出云，虎啸谷生风。","达人悟玄理，卜筑大岩中。","静阅天地心，超然万虑空。","斋居安所分，永言玉汝躬。"]},{"t":"喜友见访","f":"五言古诗","c":["快雨生夕凉，逍遥倚虚阁。","故人适我趣，觞至同一酌。","托兹忘年交，真率以为乐。","何当筋力健，杯酒共酬酢。","永言怀好音，东皋有鸣鹤。"]},{"t":"水亭燕集","f":"五言律诗","c":["微雨散方池，回飙进虚牖。","故人赏我趣，酌此尊中酒。","清谈惬素心，嘉会得良友。","日暮怅悠悠，云帆一回首。"]},{"t":"五里见一堠","f":"五言古诗","c":["五里见一堠，十里见一亭。","依依道傍树，相送复相迎。","相迎数劝酒，相送重回首。","富贵贫贱交，孰不念亲友。","送者日以远，迎者日以亲。","梦中不识路，何由见故人。","前者送卿去，系马长安树。","今日复来迎，不闻归马声。","别情何草草，泪满长安道。","昔如三春花，今为断根草。","草枯还再生，花落还再荣。","悲哉二三子，一去无音形。"]},{"t":"题谦上人听雪窝次韵","f":"五言古诗","c":["幻境依空立，初不在营构。","譬如空中花，过眼安得久。","上人清虚室，置之无何有。","心超三观妙，离净复离垢。","英英玉生辉，况值越之昼。","前身乃雪峰，后身应雪窦。","夜闻落叶声，滕六肆驰骤。","朔风号枯桑，猛若狮子吼。","炉头懒残芋，邀我速相就。","我本有发僧，俗缘嗟逗遛。","昔也求一玄，今焉白自守。","寥寥入无声，寂寂破诸漏。","兹聆阳春曲，一洗平生疚。","载歌白战诗，千军当却走。"]},{"t":"题观鱼图","f":"五言古诗","c":["子非池中鱼，安识鱼心乐。","池鱼非子心，此乐竟何托。","乃知鱼与我，所乐皆自然。","升沉各有适，动静同一天。","北海垂天云，西江斗升水。","宁知涸辙馀，中有扶摇起。","观水固有术，观鱼意何如。","我意傥相契，烦君寄素书。"]},{"t":"出塞","f":"五言古诗","c":["出塞复入塞，马鸣何萧萧。","穹庐坐名将，云是霍嫖姚。","冰河驰万骑，雪碛射双雕。"]},{"t":"出北郭有怀","f":"五言律诗","c":["晨出北郭门，微雨散晴野。","花寒莺尚迟，水绿冰初解。","折芳思寄远，幽兰未盈把。","日暮望归鸿，何由疾如马。"]},{"t":"出郭","f":"五言律诗","c":["城西值初夏，门巷绿阴交。","吴蚕始登箔，越燕已营巢。","来往索诗句，顿忘推与敲。","路逢林下笋，明旦具行庖。"]},{"t":"寄震上人","f":"五言律诗","c":["疏钟出古殿，月上青林静。","鹤去海云深，龙归泉石冷。","秋高万籁寂，此意竟谁领。","定起下岩扉，裴回碧萝影。"]},{"t":"秋怀寄友人","f":"五言古诗","c":["去年闻秋声，我友在天末。","今年秋复至，两地成契阔。","疏桐不知秋，当窗堕斜月。","寄我琼琚篇，藏之字不灭。","不信苦相思，来看镜中雪。"]},{"t":"题芭蕉双鹤图","f":"五言律诗","c":["雨鸣蕉叶凉，颇觉秋声早。","阶前有双鹤，迥立风尘表。","梦觉两无情，喧寂各有道。","持以寄山僧，观心一时了。"]},{"t":"度函谷关","f":"五言古诗","c":["车行何盘盘，青山碾为土。","英雄去已远，石色犹太古。","天低太行树，历历青可数。","落日照平原，黄沙渺烟雾。","鸡鸣曙星没，大梦谁先悟。","紫气不东来，悠悠白云度。"]},{"t":"夜泊采石","f":"五言古诗","c":["我思谪仙人，渴饮江上水。","神游八极间，随月忽飞起。","泠然宫锦袍，濯足天河里。"]},{"t":"思悲翁","f":"五言律诗","c":["客有思悲翁，老大悲明月。","昨日颜如丹，今朝鬓成雪。","雪色落明镜，所思胡不悲。","寄言东家子，行乐当及时。"]},{"t":"节妇吟","f":"五言古诗","c":["汲井井水清，弹琴琴弦直。","弦直节不移，水清心共白。","夫死舅姑老，妾身安所归。","灯前形共影，独留三岁儿。","愿儿日长大，他年应门户。","莫恋蜜脾甜，甘为蓼虫苦。"]},{"t":"题渊明抚松图","f":"五言古诗","c":["渊明与孔明，出处各有道。","乃知归来辞，即是出师表。","盘桓抚孤松，全身以为宝。"]},{"t":"纳云轩为海上人作","f":"五言古诗","c":["依依度檐隙，冉冉通帷幔。","初腾洗钵水，却绕翻经案。","去来固无心，既聚还复散。","龙嘘石气凉，月澹萝窗半。","室虚如有容，超然悟禅观。"]},{"t":"送给事服满之京","f":"五言古诗","c":["剖松见贞心，裂竹知直节。","所以君子交，不学儿女别。","我随贤王驾，聿来古洪都。","给事偶相见，长身美多须。","昂昂九皋鹤，清声振寥廓。","三载读檀弓，一朝登凤阁。","南浦水如天，开帆月正弦。","风恬鲸浪稳，人识孝廉船。","子乘驷马车，蹴蹋长安道。","倾盖各有时，何须论迟早。","笑呼麻姑酒，送别豫章城。","愿言崇令德，忠孝在兹行。"]},{"t":"送王山人之金华","f":"五言古诗","c":["昔有牧羊子，云是黄初平。","寄迹金华洞，栖真入杳冥。","山中多白石，叱作群羊行。","穿云寻紫术，蹑雪采黄精。","子去追仙隐，逍遥尘外情。","登临惬幽赏，吟啸有馀清。","欲往违夙愿，相思萝月明。"]},{"t":"送人之京","f":"五言律诗","c":["我本林下人，偶与故人别。","今旦出门去，山明鸟声悦。","江花已变春，野树犹含雪。","伫立送飞鸿，依依望丹阙。"]},{"t":"黄鹄行","f":"五言古诗","c":["东海有黄鹄，羽翼何翩翩。","十里复五里，裴回上青天。","青天高无极，下视周八埏。","朝依玄圃树，夕饮瑶池泉。","凤凰以为匹，啄食保长年。"]},{"t":"赠张鍊师","f":"五言古诗","c":["东海有仙人，云是谷神子。","饥餐旸谷日，渴饮玉池水。","太虚廓无际，洞然启玄门。","陶镕日月髓，灌溉玄牝根。","从事夏黄公，逍遥橘中隐。","三花如可攀，共上昆崙顶。"]},{"t":"舟过庐山 其一","f":"五言律诗","c":["青山在船头，正对香炉面。","如何五老人，一老不可见。","临流问四老，相遇何不早。","一老对我心，万古青不了。"]},{"t":"舟过庐山 其二","f":"五言律诗","c":["我昔过匡庐，白云在其下。","盘盘封谷口，如虎复如马。","望之安可招，揽之不盈把。","何人结茅屋，此意更潇洒。"]},{"t":"老至","f":"五言律诗","c":["今晨对明镜，始知吾老矣。","五年寓洪都，思家二千里。","江流直如弦，风帆疾如矢。","西山有白石，可以砺吾齿。"]},{"t":"题山居画","f":"五言律诗","c":["在山不识山，出山山在眼。","移之图画间，此意更萧散。","依依倦鸟还，悠悠白云晚。","一笑澹忘言，逍遥思无限。"]},{"t":"题寓庵","f":"五言古诗","c":["寓形大化内，道寓太极先。","厚者寓乎地，高者寓乎天。","晦明寓日月，流峙寓山川。","荣悴寓草木，飞跃寓鱼鸢。","吾身寓万事，理寓方寸田。","问子何所寓，寓以八九椽。","大雅寓古意，微言寓陈编。","至味寓玄酒，希声寓素弦。","行寓南山下，坐寓白云边。","息寓芳柳阴，饮寓佳菊前。","嗟余随所寓，寓洪今五年。","赋雪寓梁园，乌纱寓白颠。","历观寓世者，寓言无不然。","伊吕寓莘渭，巢由寓林泉。","静寓惟独善，动寓隘八埏。","吾亦聊寓耳，试歌寓庵篇。"]},{"t":"吴江月下汎舟","f":"五言古诗","c":["馀霞敛遥岑，微霭生近浦。","江行得凉夜，月出鸣柔橹。","茫茫天欲浮，历历星可数。","水萤乍明灭，沙禽或翔舞。","此意与谁同，三高渺千古。"]},{"t":"春夜怀友","f":"五言古诗","c":["恬澹何所营，稍欣人事简。","霏微禅榻雨，杳霭钟声晚。","独念华山人，聆君广陵散。"]},{"t":"分绿轩","f":"五言古诗","c":["凉翠入虚幌，纷披散回飙。","非烟还翳翳，不雨亦潇潇。","朝光凝竹简，晚色借山瓢。","试从明处见，复讶暗中消。","尚拟题名姓，因诗寄廓寥。"]},{"t":"送人还碧莲峰听琴诗卷","f":"五言古诗","c":["东海有别鹤，孤飞白云端。","五里一返顾，十里一盘桓。","盘桓向何所，乃在碧莲山。","上有千岁松，下有幽涧泉。","灵飙振逸响，宫商自相宣。","眷此冥栖士，抱琴松下弹。","一弹白雪操，再弹猗兰篇。","泠然太古调，不在指与弦。","别鹤眇千载，此意无人传。","安得跨黄鹄，相从凌紫烟。"]},{"t":"东园漫兴十二首 其一","f":"五言律诗","c":["池荷生夕凉，快雨飘然至。","窗虚延竹色，林暝散花气。","地偏人事简，遂我幽栖志。","缅怀心所亲，伫立凝远思。"]},{"t":"东园漫兴十二首 其二","f":"五言律诗","c":["林扉朝雨歇，旭日朗以清。","花上野禽语，竹间萱草生。","呼儿晚移席，觞至时一倾。","故人偶相慰，适此閒居情。"]},{"t":"东园漫兴十二首 其三","f":"五言古诗","c":["明月入东园，柳影在庭下。","烱然如水蘋，可玩不可把。","褰裳舞婆娑，谁识独乐者。","须臾清籁发，恍惚洞庭野。","轩皇奏钧天，此曲知者寡。","何当乘飙轮，大笑呼白也。"]},{"t":"东园漫兴十二首 其四","f":"五言律诗","c":["凿池以为海，叠石以为岛。","游鱼行其中，倏若万里道。","千里复万里，乃在咫尺间。","不有垂云翼，安知天地宽。"]},{"t":"东园漫兴十二首 其五","f":"五言律诗","c":["微风散晨雨，落花满前除。","振衣延旦气，读我斋中书。","沈潜周孔思，究竟羲皇初。","无言永终日，逍遥以自娱。"]},{"t":"东园漫兴十二首 其六","f":"五言律诗","c":["雨歇林气清，鸣蜩集高柳。","痴儿戏我侧，进此尊中酒。","御史不在前，执法不在后。","陶然玉山颓，竟入无何有。"]},{"t":"东园漫兴十二首 其七","f":"五言古诗","c":["尘不可以镂，影不可以吹。","至道与玄合，无言亦无思。","大钧播万物，总总复蚩蚩。","天命各有得，人事故不齐。","何当混真朴，弹指悟希微。"]},{"t":"东园漫兴十二首 其八","f":"五言律诗","c":["炙背坐东轩，思欲献天子。","由来山野人，所寓敬而已。","安知九重天，阳春被遐迩。","愿颂康衢谣，相从葛天氏。"]},{"t":"东园漫兴十二首 其九","f":"五言律诗","c":["幽兰生石上，楚楚含朝晖。","微飙度前楹，清芬袭我衣。","承彼雨露恩，采之当及时。","持以遗君子，勿随秋草萎。"]},{"t":"东园漫兴十二首 其十","f":"五言律诗","c":["东园有佳竹，云是青珊瑚。","当窗互宾主，相看以自娱。","如金复如玉，灵籁奏笙竽。","题诗留醉墨，不待倒薤书。"]},{"t":"东园漫兴十二首 其十一","f":"五言律诗","c":["避喧息万虑，习静喧乃忘。","宾退掩关卧，兀然就空床。","鸣禽欲变夏，风叶生夕凉。","頫仰超宇外，悠悠傲羲皇。"]},{"t":"东园漫兴十二首 其十二","f":"五言律诗","c":["洗砚临清池，爱此鸲眼明。","今晨无俗事，试墨写黄庭。","扫地树阴午，超然有馀清。","因之悟玄牝，可以保长生。"]},{"t":"东园漫兴寄友","f":"五言古诗","c":["斋居晨雨歇，褰裳涉东园。","蔷薇欲变夏，芍药尚馀寒。","好风从东来，灵鹊一何喧。","故人枉琼藻，海蛤侑山尊。","醲鲜适野性，颇觉古意存。","感激谢知己，何由同笑言。"]},{"t":"东园即事","f":"五言古诗","c":["积雪拥柴门，不知春社过。","萧条花事晚，谁共看花坐。","既醉还复醒，颓然掩关卧。"]},{"t":"漫兴八首 其一","f":"五言古诗","c":["皎皎天上月，回光照罗帏。","盈盈窗间女，手弄天孙机。","上有双凤皇，翱翔綵云飞。","愿秉古刀尺，裁为君子衣。","君子在远道，无由接容辉。","裴回不能寐，矫首望金扉。"]},{"t":"漫兴八首 其二","f":"五言古诗","c":["流云夜无声，月直南斗间。","明星烂华采，历历当高天。","侧身望八极，长夜何漫漫。","鹤鸣知露下，蛩响识天寒。","思欲凌霄汉，上接双飞翰。","黄鹄绝四海，一去何由攀。","中情不可写，掩抑坐长叹。"]},{"t":"漫兴八首 其三","f":"楚辞体","c":["皎皎天上月，照我白玉楼。","列星垂光采，河汉西南流。","不知谁氏女，哀歌楼上头。","歌声入云响，思挟凤凰游。","凤兮翔千仞，宛在昆崙丘。","岂无云间鸟，念之非我俦。","含情掩罗袂，恻怆令心忧。"]},{"t":"漫兴八首 其四","f":"五言律诗","c":["采采芙蓉花，涓涓弄秋水。","停君木兰棹，聆我歌声起。","采花欲寄远，思君隔千里。","红颜能几何，悲哉远游子。"]},{"t":"漫兴八首 其五","f":"五言律诗","c":["池中有天荷，亭亭照秋绿。","薄言折其茎，丝断不可续。","欲知别情苦，甚于莲子心。","弃置勿复念，裴回以沈吟。"]},{"t":"漫兴八首 其六","f":"五言古诗","c":["孟冬寒欲至，珠箔沾微霜。","冀马向北鸣，燕鸿亦南翔。","朗月悬中天，惊飙吹洞房。","客从南海来，遗我双明珰。","何以报区区，系在红罗裳。","珍藏箧笥中，三载生辉光。","努力保明哲，愿言勿相忘。"]},{"t":"漫兴八首 其七","f":"五言古诗","c":["黄鹄东南飞，乃在霄汉间。","五里一返顾，十里一回旋。","人生念俦侣，况乃隔河关。","我有绿绮琴，为君鼓猗兰。","商飙激流响，中曲何由宣。","合并固有时，踌躇不能言。"]},{"t":"漫兴八首 其八","f":"五言古诗","c":["昼卧北窗下，双蝶何蘧蘧。","悠然寻梦去，变化在须臾。","蓬莱易清浅，日月无根株。","鲁连东蹈海，李斯西上书。","人生各有适，万事徒区区。"]},{"t":"上冢","f":"五言律诗","c":["冷食江南节，田家改火时。","桑间鸣戴胜，冢上见棠梨。","冥冥昊天德，渺渺白云思。","持觞数行泪，重拟挽歌辞。"]},{"t":"黄鹤楼","f":"五言古诗","c":["湛湛江上水，不洗人间愁。","悠悠江上山，无心自浮浮。","一掬别时泪，不随水东流。","侧身望黄鹤，寂寞三千秋。","凡骨不可蜕，大丹还能求。","愿令远游人，慎勿生白头。"]},{"t":"登五岳楼 其一","f":"五言古诗","c":["五岳萃灵气，岿然见高标。","上凌三素云，仰见九层霄。","玉女启天关，参差紫宸朝。","群龙翊殿陛，双鸾夹笙箫。","倚阑待明月，清露下泬寥。","游神八表外，羽佩何飘飘。"]},{"t":"登五岳楼 其二","f":"五言古诗","c":["灵飙吹海雨，洗出江南山。","丹梯倚层汉，玉女启天关。","秋声撼双桧，白日波涛还。","龙驾倏来游，空中鸣佩环。","朝发榑桑涘，夕栖若木湾。","会当凌八表，晞发太霞间。"]},{"t":"寓言十首 其一","f":"五言古诗","c":["客从海上来，探彼明月珠。","下沈无底谷，不惜千金躯。","得之骊龙颔，行险何其愚。","君子保明哲，荣名安可趋。","求鱼不投饵，待兔当守株。"]},{"t":"寓言十首 其二","f":"五言古诗","c":["迢迢汉川上，有女丽且閒。","佩以双明珠，游戏清波间。","翩然若飞鸿，可望不可攀。","赠我以翠羽，报之以秋兰。","裴回碧云暮，引领空长叹。"]},{"t":"寓言十首 其三","f":"五言古诗","c":["仙人渡弱水，云是王方平。","海上见麻姑，为言三浅清。","天风吹榑桑，鱼龙不得宁。","海水相荡潏，五鳌欲颓倾。","世传如瓜枣，服之可长生。","安得谢人世，飘飘凌太清。"]},{"t":"寓言十首 其四","f":"五言古诗","c":["灼灼苑中桃，托根瑶池傍。","丹葩含淑气，艳彩炫青阳。","常恐玉阶树，秋风委朝霜。","弱水不可渡，蓬莱竟茫茫。","安得跨黄鹄，凌风以翱翔。"]},{"t":"寓言十首 其五","f":"五言古诗","c":["梦乘白玉麟，遨游洞庭野。","明月流高天，白云生其下。","轩皇张广乐，云是太古者。","灵妃鼓瑶瑟，玄音淡而雅。","此曲遗人间，但恐知音寡。","苟非遇伶伦，黄钟不如瓦。"]},{"t":"寓言十首 其六","f":"五言古诗","c":["世无钟子期，孰知悲与喜。","闻昔有韩娥，歌声绕梁起。","一歌令人悲，再歌令人喜。","同为齐中音，忧乐如转指。","我有太古弦，泠泠泻秋水。","所愿感人心，不愿感人耳。"]},{"t":"寓言十首 其七","f":"五言古诗","c":["羲和无停车，万物岂长久。","颜回一何天，盗蹠一何寿。","明镜蒙埃尘，安能别妍丑。","松柏遭剪伐，不如蒲与柳。","所以刘阮徒，沈酣托杯酒。"]},{"t":"寓言十首 其八","f":"五言古诗","c":["女娲鍊白石，上补青天青。","搏沙散人世，六合何冥冥。","二气更变化，三才立仪刑。","笃生圣与贤，出言为大经。","至道不可泯，炳然如日星。","叹息千载下，持蠡测沧溟。"]},{"t":"寓言十首 其九","f":"五言古诗","c":["青青百尺桐，乃在南山岑。","朝阳生其颠，上有五色禽。","昔闻有虞氏，斲为太古琴。","一弹南风操，可以涤烦襟。","如何千载下，筝笛贵哇淫。","引领望苍梧，悠悠白云深。"]},{"t":"寓言十首 其十","f":"五言律诗","c":["神龙启河图，清浊自兹判。","三才由中立，万化归一贯。","粤从形气生，遂有人文焕。","载诵康衢谣，令人发深叹。"]},{"t":"秋夜二首 其一","f":"五言律诗","c":["东园秋气清，露坐当夜半。","月高栖鸟寂，雨止流萤乱。","清影转疏桐，微凉入虚幔。","开户望明星，离离度河汉。"]},{"t":"秋夜二首 其二","f":"五言古诗","c":["重城罢鸣柝，朗月出东山。","河汉从西流，滉漾箕尾间。","高树息栖鸟，微露浥芳兰。","故人期不至，良夜何漫漫。","挥弦发清唱，同心谁与言。"]},{"t":"初秋东园夜坐有怀秫庄清友","f":"五言古诗","c":["秋至倏五日，微凉入东园。","河汉西南流，月直箕尾间。","鲜飙启夕秀，露彩汎崇兰。","神閒意自惬，思其故人言。","故人期不至，中情何由宣。"]},{"t":"秋夜怀友","f":"五言古诗","c":["沈沈秋夜静，蟋蟀鸣中堂。","出户望河汉，星辰低复昂。","念我平生友，远在天一方。","安能学明月，万里延辉光。","辉光有时阙，此情不可灭。","愿为双黄鹄，翱翔恣超越。"]},{"t":"秋夕","f":"五言律诗","c":["月出万井秋，商声在高树。","风条络纬鸣，露叶流萤度。","天河一杯水，流向西南去。","坐念素心人，佳期渺何处。"]},{"t":"寄赵子奇","f":"五言古诗","c":["金气稍侵阁，裴回月东上。","思君得良夜，何由遂真赏。","萤依露草深，蝉曳风条响。","西池烦暑退，神情亦超朗。","既消文园渴，奚恋铜仙掌。","上方钟磬馀，令人发遐想。"]},{"t":"紫薇花下看月寄友","f":"五言古诗","c":["娟娟海东月，照我紫薇花。","花月相裴回，玉露浮清华。","美人如明珠，流辉隔綵霞。","可望不可即，玩之令人嗟。","安得骑黄鹄，同游太清家。"]},{"t":"醉后蔷薇花下待月有怀","f":"五言律诗","c":["林扉待月出，醉影忽在地。","褰衣就花前，弄影学儿戏。","微飔吹我衣，清露散花气。","隔水报钟来，故人期不至。"]},{"t":"月下怀友","f":"五言律诗","c":["西亭文墨暇，方塘含夕清。","流萤竹间度，栖禽沙际鸣。","脉脉动遥思，念之感中情。","欲鼓猗兰操，流飙激商声。"]},{"t":"雨后待月有怀","f":"五言古诗","c":["雨过生夕凉，流萤度疏竹。","褰衣步明月，清露洒庭绿。","仰瞻天宇高，明汉手可掬。","城南有故人，丰姿美如玉。","跫然怀足音，何由慰空谷。"]},{"t":"题鞋山","f":"五言古诗","c":["朝行女儿港，夕步小姑山。","罗袜凌波面，金莲出地间。","惟应渡银汉，蹴蹋竟忘还。"]},{"t":"杂兴","f":"五言律诗","c":["春风尔何来，吹我门前柳。","呼儿唱吴歌，欸乃齐拍手。","御史不在前，执法不在后。","倒著乌纱巾，兀兀但饮酒。"]},{"t":"题燕集诗卷","f":"五言古诗","c":["城南夏五月，碧树始鸣蜩。","维时集群彦，觞咏共逍遥。","凭高望大海，俯见万里潮。","藻翰发奇思，华筵激流飙。","献酬各有礼，既醉复长谣。","岁月忽已迈，聚散若云飘。","佳期阻良觌，关河怅迢迢。","白鸥恋近渚，黄鹄慕层霄。","寄迹凌浩荡，游神思廓寥。","习池应不远，折简会相招。"]},{"t":"城南燕集次韵","f":"五言古诗","c":["我本丘壑人，幸陪金闺彦。","煌煌处士星，分辉照南甸。","驾言出城东，弭节蓬莱殿。","高云澄宇宙，江气白如练。","维时迫重九，楚楚集清燕。","罗袂微风散，文采明霞绚。","系马高阳池，华觞列丰膳。","谁为蜕骨仙，大药成九鍊。","手把黄金花，安得长会面。","沧波浩茫茫，坐见桑田变。","志士多苦心，甘许铁为砚。","张公人中英，倜傥吾所羡。","海内阅神交，目若岩下电。","良晤欣在兹，既醉复留恋。","偶凭青鸟使，书来疾如箭。","愿言附冥鸿，修翼排云健。"]},{"t":"顾况读书台二首 其一","f":"五言律诗","c":["朝登紫微寺，日出林扉开。","寻僧访古迹，始见读书台。","岁月不复考，古人安在哉。","空馀丹井石，寂寞生苍苔。"]},{"t":"顾况读书台二首 其二","f":"五言古诗","c":["东海有蟠桃，托根在蓬莱。","结实三千岁，谁能见花开。","此树寿命长，世传王母栽。","思昔通天观，灵驭排云来。","汉苑不可种，茂陵非仙才。","回视三山下，清浅飞黄埃。"]},{"t":"寄友人效韦体","f":"五言古诗","c":["圆穹倚高盖，厚地浮虚舟。","日月相循环，万古无时休。","人生大化中，何异海一沤。","嗟彼桃李花，岂识芙蓉秋。","愿言杯中物，化作长江流。","普令四海人，一洗胸中愁。"]},{"t":"送云季昭","f":"五言律诗","c":["西池生夕凉，虚阁流萤度。","援琴发清商，离情惨中素。","夫君瑚琏器，相见一何暮。","凤鸟及时鸣，还依上林树。"]},{"t":"寄何尹","f":"五言古诗","c":["翠羽生南海，结巢在三山。","青鸾与之匹，翱翔琪树间。","虞罗不相及，裴回竟忘还。","比翼从北飞，言度雁门关。","霜高百草短，长途凄以寒。","愿言同饮啄，慎彼五色翰。"]},{"t":"陪林叟池上晚酌","f":"五言古诗","c":["晚憩池上阁，凉飙散冲襟。","丹丘广文老，卧病力不任。","论文意自适，下榻情逾深。","诸孙列左右，觞至时一斟。","既醉月在道，出户天沈沈。","枯桐委爨下，感激谢知音。"]},{"t":"西池晚酌","f":"五言律诗","c":["方池散文漪，微飔坐来爽。","归禽各已息，华月从东上。","故人适我趣，携尊共延赏。","隔水闻疏钟，令人起遐想。"]},{"t":"月上","f":"五言律诗","c":["朗月上东园，照见梨花白。","裴回东阑下，花月同一色。","飘飘素霓裳，可望不可即。","思欲折琼芳，佳期綵云隔。"]},{"t":"春思","f":"五言古诗","c":["白日丽璇霄，下照六合间。","茫茫名利途，积尘如丘山。","朝轮登太行，夕辙度秦关。","大道平若砥，谁云有波澜。","安得挟飞仙，吹笙缑北山。","飘飖跨黄鹤，永接松乔班。"]},{"t":"古意八首 其一","f":"五言古诗","c":["煌煌明月珠，乃在碧海南。","下沈无底谷，百仞谁能探。","昔在轩辕世，象罔索龙潭。","少昊徵凤瑞，隋侯感蛇衔。","安知至珍物，翻为薏苡谗。","蛟人卖绡去，勿用泪潸潸。"]},{"t":"古意八首 其二","f":"五言古诗","c":["青青岩畔柏，冉冉淇上竹。","娟娟闺中女，粲粲丽春服。","翩翩若惊鸿，盈盈洛川曲。","昔如出壑冰，今如在山玉。","蹇修期不来，空帏成独宿。"]},{"t":"古意八首 其三","f":"五言律诗","c":["积雪生暮寒，幽禽在空谷。","夜来忽惊飞，翩翩度疏竹。","拥衣坐方床，呼儿秉明烛。","念彼远游人，何由慰衷曲。"]},{"t":"古意八首 其四","f":"五言律诗","c":["明月流中天，列宿相低昂。","盈盈河东女，寒机织流黄。","灵鹊期不来，欲度愁无梁。","睆彼牵牛星，东西两相望。"]},{"t":"古意八首 其五","f":"五言律诗","c":["陌头桑叶稀，桑间戴胜飞。","盈盈东家女，染丝上春机。","手把黄金剪，裁为游子衣。","可怜天上月，中夜照罗帏。"]},{"t":"古意八首 其六","f":"五言古诗","c":["幽兰在空谷，无人知其芳。","好风时过之，清芬袭我裳。","薄言掇其英，置之君子堂。","君子好修洁，佩之比珩璜。","葹薋妒其美，寂寞委秋霜。","托根苟得所，弃置庸何伤。"]},{"t":"古意八首 其七","f":"五言古诗","c":["客从南海来，遗我径寸珠。","夜光夺明月，明月恐不如。","珍藏三十载，思照魏王车。","王车不待照，鱼目空相笑。","持以照人心，千秋保贞曜。"]},{"t":"古意八首 其八","f":"五言律诗","c":["我有龙门桐，斲为绿绮琴。","一弹别鹤操，再理孤鸾音。","中含太古意，调高思弥深。","此曲知者寡，山空月沈沈。"]},{"t":"题巢云","f":"五言律诗","c":["在山巢白云，出山云在眼。","天地同一巢，舒卷任萧散。","依依双阙曙，渺渺太行晚。","何当呼谪仙，秀色同一览。"]},{"t":"题梅月图","f":"五言律诗","c":["娟娟古时月，粲粲江南春。","美人不可见，梦堕梨花云。","玉质恒自爱，素衣安可尘。","裴回岁云暮，索笑情相亲。"]},{"t":"祷雨有感","f":"五言古诗","c":["至真运玄牝，飞神游大罗。","云霞结丹篆，紫宫郁嵯峨。","灵符檄龙穴，甘雨随滂沱。","八表涤炎气，四郊苏槁禾。","凉飙起寥廓，为尔奏空歌。"]},{"t":"送友人之京","f":"五言古诗","c":["一雨午斋静，澹然忘世情。","故人别我去，迢迢之玉京。","玉京九天上，阊阖春云生。","曲黄变江柳，关关啼鸟莺。","愁怀郁离思，暮角起重城。"]},{"t":"挽知事陈仲信妻李氏","f":"五言古诗","c":["燕山有双凤，结巢在濠梁。","饥食玉山禾，渴饮瑶池浆。","一朝挟其雄，羽翼凌风翔。","㷀㷀遗众雏，遨游白云乡。","回首谢孤凤，愿言应时昌。"]},{"t":"送知县陈仲信之建昌","f":"五言古诗","c":["一日白一发，三年白几何。","自子业成均，我发白已多。","子今窣百里，武城试弦歌。","相见即言别，张帆溯江波。","西望香炉峰，秋云郁嵯峨。","丰城有双剑，龙泉与太阿。","会合各有时，精采长不䃺。","我无晨风翼，送子涉关河。","南云有来雁，裁书寄烟萝。"]},{"t":"患眼偶述","f":"五言古诗","c":["卧病北窗夕，澹然忘世情。","微雨竹间度，萧萧风叶鸣。","隐几不知夜，灯晕若流星。","兀坐学枯禅，习静心自清。","因之悟玄□，□□□□□。"]},{"t":"感兴","f":"五言古诗","c":["荆山生巨璞，安知中有玉。","卞和持献之，王乃刖其足。","天不生卞和，此玉无人知。","天不生此玉，和足宁刖之。","但求识者献，刖足复何悲。"]},{"t":"送奎上人","f":"五言律诗","c":["青云覆层巘，一径入幽林。","山中夜来雨，不知双涧深。","上人春讲罢，蹑履纵幽寻。","寄谢岩头月，还同永夜吟。"]},{"t":"拟古四首 其一","f":"五言古诗","c":["客从南海来，遗我明月珠。","感君绸缪意，繫在红罗襦。","罗襦不可解，中情不可改。","月以明妾心，珠以结君爱。","谁言道路长，咫尺隔光采。"]},{"t":"拟古四首 其二","f":"五言律诗","c":["幽兰生江皋，锐叶一何好。","临流掇其英，持以寄远道。","纫为君子佩，玩之慰中抱。","毋令比萧艾，寂寞委秋草。"]},{"t":"拟古四首 其三","f":"五言古诗","c":["晨出北郭门，遥见一抔土。","借问谁家田，云是前人墓。","青松夹道生，薤叶披朝露。","寂寂蒿莱下，但见狐与兔。","阴阳无停机，谁能识其故。"]},{"t":"拟古四首 其四","f":"五言律诗","c":["南山青桂枝，奄忽易生蠹。","荣悴更相共，去来同旦暮。","秦皇与汉武，千载终不悟。","为乐当及时，弃置贫与富。"]},{"t":"雨后杏花发对酒有怀故人","f":"五言古诗","c":["雨后杏花发，斗酒思所亲。","爱兹花上月，共赏今夕春。","如何同心者，总是他乡人。"]},{"t":"春夜与友饮别","f":"五言古诗","c":["高堂秉华烛，四座惨无辉。","鹍弦奏急响，商飙吹我衣。","□□今夕欢，明旦与子违。","何异林栖鸟，凌晨各分飞。","悠悠空中云，聚散无定期。","云出尚有归，此别将何依。","且尽尊中酒，永言长相思。"]},{"t":"仙人","f":"五言律诗","c":["金鳌十五头，盘盘戴山起。","仙人居其巅，俯视东海水。","吹笙弄明月，翱翔麟凤洲。","风车傥可驭，飞步綵云秋。"]},{"t":"房中思","f":"五言律诗","c":["红烛照啼痕，当窗伴孤影。","莎鸡语庭树，长夜心耿耿。","梦寻关山去，不识关山路。","长亭枫叶秋，忆君相别处。"]},{"t":"征妇词","f":"五言古诗","c":["商声振庭树，匹马鸣萧萧。","念汝出门去，关山怅迢遥。","床头无百金，焉能买宝刀。","阿母泪双下，灯前裁战袍。","稚女才倚床，少妇针指劳。","半年一得书，使我心忉忉。"]},{"t":"送人之京","f":"五言古诗","c":["大江春水满，芳洲蒲叶短。","黄帽唱吴歌，东风吹不断。","江君英少年，贡入司成馆。","袖有五色毫，文藻光纂纂。","人生意气合，何论相见晚。","君如千里驹，跌荡走长坂。","我如九皋鹤，长鸣任萧散。","去去毋少留，严程不容缓。","欲持一杯酒，迢迢碧云远。","明年杏花开，待我上林苑。"]},{"t":"题槐阴亲舍","f":"五言古诗","c":["慈乌夜夜啼，宛在慈溪西。","大槐高过屋，慈乌来上栖。","乌雏思返哺，哑哑愁日暮。","白云飞度江，恨不随云去。","雏有青霄翮，翱翔霜柏枝。","慈溪东入海，雏心无已时。"]},{"t":"送贡士之京","f":"五言古诗","c":["一水通震泽，张帆挂秋风。","霭霭天际云，迢迢江上峰。","朝饮枫桥酒，夕闻寒山钟。","三年读礼馀，挟策还辟廱。","愿言枉尺素，时寄南飞鸿。"]},{"t":"送人秩满之京二首 其一","f":"五言古诗","c":["乌啼海门树，旭日生苍凉。","秋风棹歌发，起拂帆上霜。","刘侯忠孝裔，三载佐黄堂。","兹焉报佳政，冠佩生辉光。","祖饯长亭下，共酌青霞浆。","侧身睇鸿鹄，万里高翱翔。"]},{"t":"送人秩满之京二首 其二","f":"五言古诗","c":["凤皇出丹穴，文采何翩翩。","朝栖岘山树，夕饮汉江泉。","一朝衔瑞图，飞鸣凌紫烟。","双阙九天上，冠盖如星联。","朝回有馀暇，早寄琼琚篇。"]},{"t":"题硖川佳胜图","f":"五言古诗","c":["昔有紫薇郎，登眺东西山。","持节去不返，名留天地间。","我尝览陈迹，行寻顾况宅。","峨峨读书台，苍烟锁荆棘。","仙翁葛稚川，丹井尚依然。","井畔长松树，不闻啼杜鹃。","鸡鸣海波赤，东望榑桑日。","六寺发鲸音，长林起萧瑟。","俱胝天竺来，一喝洞门开。","凿厓閟灵迹，老石封莓苔。","回看山下路，超然起黄雾。","憧憧往来人，日中自旁午。","关西供奉孙，两峰青到门。","微风生绮席，明月落清尊。","乘閒来访我，中流浮一舸。","手持三尺图，恍如山中坐。"]},{"t":"秀州夜泊","f":"五言古诗","c":["回舻泊晚渚，暂息嘉树阴。","清飙散狂澜，纤月生远岑。","悠悠归岫云，交交度水禽。","同舟遂幽赏，玄谈惬素心。","况兹水凉夕，觞至时一斟。","道合理无忤，怡然澹冲襟。"]},{"t":"百年寓华屋","f":"五言古诗","c":["仙人好楼居，乃在南城隅。","大江从天来，白虹绕其庐。","朝旭丽丹桷，凉飙生绮疏。","清谈落珠唾，列坐跄琼琚。","秉心介于石，富贵浮云如。","寓形百年内，逍遥以自娱。"]},{"t":"千载居山丘","f":"五言古诗","c":["四序更代谢，羲和无停辀。","达人观大化，委顺复何忧。","瞻彼池塘山，郁郁松与楸。","栖鸟自回翔，归云亦悠悠。","嗟哉泉下人，永为长夜游。","流泽衍馀庆，千载贲兹丘。"]},{"t":"送澜典藏还天界寺","f":"五言古诗","c":["大海流不息，浮云无定踪。","人生有聚散，幻相本来空。","上人得真传，何别复何同。","飞锡沧洲上，言登第一峰。","得玉勿抵鹊，探珠必求龙。","定起有馀暇，题诗寄南鸿。"]},{"t":"题望云图","f":"五言古诗","c":["何山无白云，游子心独苦。","千里万里间，见云思见母。","白云有聚散，儿心无已时。","北风何栗烈，吹裂身上衣。","母居泽山阳，倚门怀远道。","何以报区区，春晖寸心草。"]},{"t":"病中谢友见访","f":"五言律诗","c":["春阴散微雨，小阁倦登临。","万子偶相过，泠然披素襟。","裴回日将暮，负疴力不任。","王乔有只履，持以谢知音。"]},{"t":"雪中怀皓上人","f":"五言古诗","c":["高阁暮寒甚，不知春雪来。","急霰鸣竹间，顷刻覆青苔。","数日寡轮鞅，林扉谁与开。","故人寄禅居，雅趣亦悠哉。","熏炉与茶鼎，真足外形骸。","坐久夜钟过，起思重裴回。"]},{"t":"清乐轩","f":"五言古诗","c":["乾坤有清气，付与贤者乐。","贤者乐其清，所乐应不浊。","鸣蝉乐饮露，聚蚁乐慕膻。","岂不同其乐，斯乐有间焉。","鸢飞乐乎天，鱼跃乐乎水。","察彼俯仰间，谁能知乐此。","彼乐或在外，此乐乃在中。","外乐易消歇，内乐无终穷。","蒙也乐濠梁，尹也乐莘野。","欲知圣贤乐，孔颜真乐者。","郑公乐其天，乐清以名轩。","清与乐俱有，动静无不然。","山以乐吾仁，水以乐吾智。","居乐适其安，行乐随所寄。","人知使君乐，不知使君心。","安得穆清风，乐哉以长吟。"]},{"t":"送人秩满之京","f":"五言古诗","c":["严城钟鼓动，曙色明榑桑。","车骑何骈阗，祖帐生辉光。","荆君英杰士，入幕赞黄堂。","三年主画诺，一日登朝行。","卿云丽阊阖，玉琯回初阳。","行当祝万寿，逍遥紫霞觞。"]},{"t":"送岁贡生之京","f":"五言古诗","c":["俞生英妙年，读书南城下。","暇日从儿嬉，骑竹当骢马。","弱冠入虞庠，良金贵陶冶。","聱牙稽训诰，葩正习风雅。","譬彼珊瑚器，宗庙安可舍。","今春贡京师，如生才亦寡。","雍雍成均地，济济文学者。","纵横三千字，寸晷擅挥洒。","龙门锦先夺，雁塔名须写。","有使即寄书，停云念乡社。","摛辞继班马，射策希董贾。"]},{"t":"觉非诗","f":"五言古诗","c":["晨兴正冠裳，端居俨若思。","先哲有遗训，兢兢常在兹。","贤哉蘧伯玉，五十始知非。","是非日相仍，何以决群疑。","四勿我裘领，三省我蓍龟。","衡以较重轻，鉴以别妍媸。","直者不可枉，白者不可缁。","愿言保终始，中心毋自欺。"]},{"t":"送黄鍊师还天台","f":"五言古诗","c":["冲漠混元化，形神合自然。","至人保遐寿，虚灵洞玄玄。","金鳌戴宫阙，此地多神仙。","绛节凌回飙，霞裾飘紫烟。","安期啖玉枣，一笑三千年。","火乌出东方，玄兔没西海。","万古复千年，出没互相待。","蓬莱鹤上仙，何曾一人在。"]},{"t":"寄万百户","f":"五言古诗","c":["客从海上来，惠我锦字书。","开缄挹光采，字字明月珠。","藏之怀袖间，鱼目安能如。","相见一何晚，相望一何远。","迢迢河汉流，双星隔清浅。"]},{"t":"送人之京","f":"五言古诗","c":["李侯西江彦，矫矫麒麟驹。","读书司成馆，佐政东海隅。","会当驰广陌，安可困盐车。","兹焉沐清化，去谒承明庐。","霜风凄以寒，飘然曳长裾。","青云近在望，壮志毋踟躇。"]},{"t":"题澄心堂","f":"五言古诗","c":["人心本清净，湛然井中水。","井水常自澄，波澜不曾起。","张子雅好道，堂以澄心名。","卖药城市间，隐居如宋清。","我昨过其家，燕坐接谈笑。","何以效区区，操存一言要。"]},{"t":"送马文学之惠安教谕","f":"五言古诗","c":["英英马文学，年方三十馀。","秩然瑚琏器，文采玉不如。","昔也未加冠，今焉颇有须。","献艺上春官，司教闽粤墟。","翱翔南溟下，播弄明月珠。","鸿涛际大海，渺在天一隅。","文光射南斗，乐育君子儒。","愿凭青鸟使，寄我空中书。"]},{"t":"题春晖堂","f":"五言古诗","c":["青天何高高，中有三春晖。","母年日已迈，儿心尝依依。","此心向谁道，一寸阶前草。","宦辙东西驰，千里万里道。","儿骑青骢马，身著绣罗裳。","何异五色衣，笑舞春晖堂。","春晖无时已，照见东流水。","水中双鲤鱼，朝盘奉甘旨。","庭前有高树，慈乌日夕来。","乌雏思返哺，飞绕黄金台。"]},{"t":"题綵烟山人瑞槐堂","f":"五言古诗","c":["青青堂下槐，乃在綵烟山。","一本如合璧，两枝若联环。","堂中有贤母，日行槐树间。","槐根两兄弟，綵服何斑斑。","母今发已皓，人与槐俱好。","但见槐树长，不知母身老。","上有返哺乌，下有忘忧草。","返哺识劬劳，忘忧思襁褓。","槐今高过屋，屈指三十年。","东西或拱揖，左右相回旋。","不有两儿孝，安知慈母贤。","草木亦微物，永锡信苍天。","儿今何所愿，愿槐长在目。","槐花年年开，槐叶朝朝绿。","岂无蝼蚁梦，纷纷斗蛮触。","一笑天地宽，白云满空谷。"]},{"t":"送人还贵州","f":"五言古诗","c":["别情何草草，倾盖苦不早。","暌违三十年，隔越万里道。","忆在东冈日，彬彬丽文藻。","子少我当壮，子壮我复老。","人生百年内，安得长美好。","故交曙星稀，先哲流电扫。","岂无杯中物，与子一倾倒。","昨游玄都观，共觅安期枣。","挂弓榑桑枝，洗剑沧海岛。","酒阑别我去，何以慰幽抱。","楚山郁丛丛，巴水深浩浩。","愿言崇令德，黄发永相保。"]},{"t":"送人考满之京","f":"五言古诗","c":["伊昔太昊氏，教民以佃渔。","神禹平水土，群生奠厥居。","伯益掌山泽，立官自唐虞。","泽梁古无禁，庶鲜给朝餔。","后世务财用，输纳穷锱铢。","吾皇一四海，恩波被八区。","南樯与北柂，晏然如坦途。","英英南昌彦，聿来东海隅。","钓鳌龙伯国，簸弄明月珠。","清于出壑冰，置之白玉壶。","赋税日以羡，声誉日以敷。","我家临江滨，里社同枌榆。","谬登铨曹选，获与吾子俱。","得钱即相觅，有酒即相呼。","勖哉金石交，愧彼势利途。","三年当考最，驾言之京都。","京都九天上，冠盖如云趋。","蜚英大鸿胪，揽辔青云衢。","岂无伯乐氏，顾此千里驹。","大江秋水落，旭日照樯乌。","柳条不堪折，击缶歌呜呜。","方当维新日，群才应时需。","子行勿踟躇，善保千金躯。"]},{"t":"友人邀饮予病不赴作诗答之","f":"五言古诗","c":["积雨散烦燠，虚阁延清风。","故人赏我趣，觞酒坐从容。","此意岂不佳，老病苦相攻。","长途足无力，忧来郁忡忡。","知音有颜李，迹异心自同。","题诗谢不敏，恢量还当容。"]},{"t":"早朝","f":"五言古诗","c":["象魏临丹阙，钩陈直紫微。","蜿蜒扶日上，夭矫挟云飞。","望拜千官集，柔怀万国归。","春班随仗入，午漏隔花稀。","晃朗金银气，昭回黼黻衣。"]},{"t":"次周纪善韵","f":"五言古诗","c":["大鹏抟九霄，不如海鸥逸。","白首归故里，心神犹恍忽。","我足不良行，我言竟谁述。","多君富文藻，词源倒溟渤。","安流既崩奔，坦途亦崎崛。","升沉任云止，祸福由中出。","缅思七闽地，云是锦绣窟。","寄言塞上翁，善保千金骨。"]},{"t":"次昙师见寄韵","f":"五言古诗","c":["高吟寄天末，寒茧曳孤篁。","烱若双明珠，九渊安可藏。","出户见明月，流光入中堂。","载弹绿绮琴，匡坐白云床。","寥寥太古调，谁论虞与唐。","知音谅非远，我心自忧惶。","挑灯耿无寐，清泪洒淋浪。","赖有一瓢酒，慰兹离别肠。"]},{"t":"孙武","f":"五言古诗","c":["吾闻孙武子，教战阖庐城。","美人出后宫，百花媚春晴。","三令复五申，约束何分明。","一鼓玉颜笑，再鼓蛾眉倾。","雷霆肃将令，颇觉君命轻。","西来破楚疆，北灭齐晋兵。","英姿渺千古，飒爽悲风生。"]},{"t":"孙膑","f":"五言古诗","c":["孙膑古名将，庞涓俱学兵。","刖足见齐使，始识田将军。","指麾辎车中，号令若风霆。","引兵走大梁，遂解邯郸城。","救韩示怯战，减灶功乃成。","马陵书大木，弩发如流星。","跛鳖信千里，刑馀安可轻。"]},{"t":"吴起","f":"五言古诗","c":["吴起好用兵，尝学曾子法。","东出卫郭门，齧臂与母诀。","鲁君不见用，杀妻与齐绝。","将军自吮疽，士卒甘喋血。","击秦拔五城，魏侯尚功烈。","在德不在险，舟中尽吴越。","孰云猜忌人，千载名不灭。"]},{"t":"李牧","f":"五言古诗","c":["李牧守边日，屯兵雁门关。","槌牛飨士卒，十年戎马闲。","黄云覆沙漠，白雪漫天山。","狼烽日以远，骍弓不敢弯。","后来防秋戍，思之应腼颜。"]},{"t":"廉颇","f":"五言古诗","c":["相如拜上卿，岂畏廉将军。","两虎若共斗，其势不俱生。","秦兵不加赵，功归吾二人。","忠臣当殉国，志士当殉名。","不有负荆谢，安知刎颈亲。"]},{"t":"田单","f":"五言古诗","c":["田单破燕壁，神人为我师。","凿城出火牛，被以兽文衣。","壮士五千人，衔枚突其围。","斩将败骑劫，迎王入临淄。","齐城七十馀，一旦俱复之。","雄风千载下，英名良不隳。"]},{"t":"张良","f":"五言古诗","c":["良貌若美妇，本图报韩仇。","击秦博浪沙，隐迹下邳游。","既进黄石履，复运沛公筹。","关中兴汉业，天授非人谋。","谢事从赤松，功成愿封留。","一掉三寸舌，名高万户侯。"]},{"t":"怀李白","f":"五言律诗","c":["日落江水黄，云开楚山碧。","南风吹大帆，倏尔临采石。","缅怀谪仙人，醉魂招不得。","頫仰天地宽，谁云锦袍窄。"]},{"t":"题三桂堂","f":"五言古诗","c":["生儿贵生男，男可应门户。","种树当种桂，桂能耐寒暑。","君家有三儿，一一青琼枝。","时来三树下，骑竹相娱嬉。","大儿眉宇好，小儿奇绝倒。","中儿更可人，比兄读书早。","愿儿读书早，长大俱成名。","年年桂花发，来听读书声。"]},{"t":"九日望海觞咏","f":"五言古诗","c":["放旷麋鹿性，消摇林野娱。","良时遂倾盖，真赏偶联裾。","高云澄泰宇，旭日朗以舒。","亭亭远峰出，靡靡幽花敷。","凭高倚飞阙，遐想入方壶。","幸陪金闺彦，获与静者俱。","何当凌八表，飞舄蹑双凫。"]},{"t":"伤思次韵","f":"五言律诗","c":["江上双鸳鸯，双飞复双起。","如何南来雁，只影沈湘水。","芦花似朝霜，漫漫逐风起。","欲寄故乡书，悲哉远游子。"]},{"t":"次友人韵","f":"五言古诗","c":["青鸟海上来，五采何翩翩。","口衔三素云，满几生晴烟。","墨池夜来雨，空碧涵漪涟。","安得王内史，一埽九万笺。","因风托青鸟，寄谢瀛洲仙。"]},{"t":"题牧童骑牛图","f":"五言律诗","c":["牛背稳于马，骑过南山下。","竹鞭三尺长，不用紫游缰。","四郊干戈罢，归放桃林野。","一曲太平歌，尔童奈乐何。"]},{"t":"古意","f":"五言古诗","c":["皎皎连城璧，乃在巨璞中。","无人辨其真，甘与燕石同。","所以卞和氏，抱泣秋山空。"]},{"t":"水中蒲","f":"五言古诗","c":["青青江上蒲，宛宛水中鱼。","楚楚东家女，盈盈楼上居。","泠泠抚瑶瑟，粲粲被罗襦。","昔如昆山玉，今如浊水珠。","美玉尚待价，明珠终不污。"]},{"t":"拟今日良宴会","f":"五言古诗","c":["今日惨不乐，忧来郁无端。","华堂秉明烛，思奉君子欢。","南窗抚瑶瑟，含情不能弹。","君情与妾意，忧乐转指间。","人生非金石，流景若飞丸。","何不返初服，英英谷中兰。","无言混萧艾，委质霜露间。"]},{"t":"得雨","f":"五言律诗","c":["夜闻蕉叶声，秋至得凉雨。","推窗云气暝，枕簟净无暑。","竹间萤火度，草际莎鸡语。","焦原当复荣，慰我三农苦。"]},{"t":"送岁贡生之京","f":"五言古诗","c":["开岁倏五日，青阳动熹微。","回塘夜来雨，碧水生涟漪。","明发戒舟航，翩翩上京师。","官曹送子行，酌以黄金卮。","师友送子行，载歌鹿鸣诗。","乡老送子行，夹道迎春旗。","父母送子行，密缝身上衣。","子今朝天去，翱翔凤凰池。","愿言登太学，肃肃慎其仪。","尚友古之人，明哲以为期。"]},{"t":"送张将军之京","f":"五言古诗","c":["曜灵启旸谷，春云曳华旌。","将军奉明诏，揽辔出严城。","风吹杏雨白，火改榆烟青。","仪凤五色羽，神驹千里程。","论功锡重爵，远迩振英声。"]},{"t":"题金兰图","f":"五言古诗","c":["英英风露姿，托根在空谷。","何人撷其芳，置之黄金屋。","彼美同心者，可以慰幽独。"]},{"t":"寄宋纪善三首 其一","f":"五言古诗","c":["东海有黄鹄，托巢琪树间。","朝浴咸池水，夕息三神山。","翩然上霄汉，翱翔白玉关。","我欲往从之，短翮无由攀。","雄飞谅有道，雌伏何足叹。"]},{"t":"寄宋纪善三首 其二","f":"五言古诗","c":["幽兰在空谷，无人知其芳。","天风一披拂，置之君子堂。","擢颖萧艾间，锐叶何辉光。","盈盈汉皋女，拾翠江之傍。","所思隔远道，欲寄双明珰。","明珰不可寄，展转郁中肠。"]},{"t":"寄宋纪善三首 其三","f":"五言古诗","c":["青鸟天上来，寄我云锦书。","开缄挹华采，字字明月珠。","佳期渺天末，怅望心萦纡。","我无青琼琚，何以报区区。","愿言敦夙好，善保千金躯。"]},{"t":"佳人折花联句","f":"五言律诗","c":["婉婉水边来，盈盈花畔立。","霞侵玉指煖，露沁罗裳湿。","刺密尚迟攀，条长讵能及。","持归玉台前，自掩红颜泣。"]},{"t":"题琴轩","f":"五言律诗","c":["南州有高士，手抱龙门桐。","披襟坐磐石，泠泠和松风。","上弦奏鸣凤，下弦鼓飞鸿。","寄情山水间，所乐无终穷。"]},{"t":"效陶","f":"五言律诗","c":["晨策何所之，言往南山阳。","白云生其颠，归鸟共回翔。","采采篱下菊，宾至同一觞。","醉卧北窗下，悠然傲羲皇。"]},{"t":"效韦","f":"五言律诗","c":["我本麋鹿性，爱兹林壑幽。","夕泉分涧落，晴岚出树浮。","披襟挹高爽，策杖散烦忧。","归鸟引馀兴，裴回去复留。"]},{"t":"题敬义斋","f":"五言古诗","c":["南州有一士，卜隐大江滨。","端居坐终日，尚友古之人。","古人不可作，圣远复言湮。","出门岐路多，何由问通津。","有客过其家，诲语何谆谆。","集义以养气，主敬以修身。","请子事斯语，永言书诸绅。"]},{"t":"送侄从戎云南兼柬居掾史","f":"五言古诗","c":["我祖自南渡，世为盐官人。","家传安定谱，子孙多搢绅。","嗟汝英妙年，从戎万里道。","断蓬离本根，骨肉岂相保。","忆汝别家曰，妇病在膏肓。","小妹应门户，两女才倚床。","一年一得书，见书如见汝。","蹉跎十五年，阅尽寒与暑。","昨者奉军帖，仓卒暂还家。","两女上堂拜，不识去时爷。","朝纺木棉花，夜织机中布。","裁为身上衣，梦绕天南路。","天南有名将，云是汉嫖姚。","威声振夷夏，勋业著皇朝。","汝今向前去，勿恋故乡住。","生入玉门关，会当有奇遇。","乌啼海东树，落月在城头。","送汝北郭门，霜花满征裘。","千金买宝刀，岂若聊城箭。","鲁连倜傥生，何曾叹贫贱。","洞庭秋水落，三峡夜猿哀。","船过瞿唐口，还经滟滪堆。","严程不可缓，别去关山远。","缩地恨无方，我肠辘轳转。","辕门有知己，远惠白象梳。","琼瑶无以报，为我谢区区。"]},{"t":"送东既白上人之京","f":"五言律诗","c":["旭日东方来，起送东既白。","山笠野云深，田衣江水碧。","去登千里道，归化三生石。","鹤羽振高飙，迢迢望飞锡。"]},{"t":"送浙江佥宪金台王公考满之京","f":"五言古诗","c":["王公希代宝，本自金台人。","素抱匡济略，华年登要津。","布衣谒万乘，意气干青云。","恩承凤凰诏，擢为乌府臣。","钱唐古都会，一水东西分。","三年持玉节，远迩劳咨询。","冰壶贮秋月，藻鉴无纤尘。","兹焉考嘉绩，封章朝紫宸。","天子坐南面，视听自下民。","苟乏耳目官，上天何由闻。","公今司献纳，一一请具陈。","某郡山水美，某州风俗淳。","某守贪以墨，某吏清以仁。","某田足禾稼，某冶饶金银。","某灶可淅卤，某营可屯军。","某曹奸且黠，某士才更文。","里巷某贞节，岩穴某隐沦。","忠良荐某辈，淫祀黜某神。","虎拜伏阙下，正及鸡鸣晨。","天颜动微笑，孰不荷陶甄。","维时晴雪后，吴水碧粼粼。","张帆南斗下，伐木大江滨。","我亦刍荛者，斐词公勿瞋。","愿言宣大化，四海回阳春。"]},{"t":"题晓峰","f":"五言古诗","c":["在山不见山，出山山更好。","披衣五更起，山色入门早。","空翠落琴床，晴光动林表。","自有天地来，万仞青不了。","寄言山中人，古今亦昏晓。"]},{"t":"送叙班刘南奎还临江省亲","f":"五言古诗","c":["日出狮峰顶，鹊鸣庭树枝。","慈母出门望，儿从天上归。","一别十三年，母子隔远道。","不忧岁月深，但恐母年老。","儿仕大鸿胪，母在高堂居。","有禄不得养，问安徒寄书。","儿今乞归省，诏许还乡井。","暂经洪都门，遥指白云岭。","一笑偶相逢，论诗铁柱宫。","相逢即相别，挂席趁回风。","回风吹五两，南浦春波长。","就船买鲤鱼，沿月棹歌响。","登堂进流霞，更栽萱草花。","百岁母身健，愿儿长在家。"]},{"t":"雪","f":"五言古诗","c":["晴响始鸣条，寒威稍侵户。","声䋣知杂霰，溜密应兼雨。","寻灯靡靡飘，度隙斜斜舞。","兴极还思剡，歌长重和楚。","寂寞大音希，悠然向谁语。"]},{"t":"辞世颂","f":"五言古诗","c":["臣有一寸葵，托根空谷间。","中有向日心，炳如九还丹。","日照葵在地，葵倾日在天。","由来忠义者，存殁无不然。","臣心愿如葵，日照千万年。"]},{"t":"前有千万年","f":"古风","c":["前有千万年，不知是何物。","后有千万年，变化安可测。","河中龙马未生时，谁辨东西与南北。","混沌死，七窍生。","昆崙水源直到海，千流万派何由清。","但见两轮日月东西走不息。","人言火精与水银，锻冶红颜冻梨色。","消磨绿发如星星，人生得意且为乐，何用空名留汗青。"]},{"t":"有所思三首 其一","f":"五言律诗","c":["脉脉有所思，泠泠寄哀弦。","弦声久已绝，思君聆我弹。","君情与妾意，忧乐转指间。","幸随南风调，流响九嶷山。"]},{"t":"有所思三首 其二","f":"楚辞体","c":["落叶随风飞，欲归在何时。","人生千里不得会，空向天涯歌所思。","黄陵女儿泣湘月，苍梧鸣凤千年别。","弹折秋风五十弦，妾貌如花命如叶。","青猿夜啼三峡长，望美人兮良可伤。","回雁峰前有来使，愿寄一书还故乡。"]},{"t":"有所思三首 其三","f":"古风","c":["所思向何方，所思今有所。","食蓼不知辛，食檗不知苦。","惟有所思愁杀人，蓼檗不能如苦辛。"]},{"t":"长相思四首 其一","f":"古风","c":["长相思，千万里。","相思如车下轮，相思如江中水。","江中之水朝暮流，车下之轮何日休。","胡不斫车轮，塞江水。","车不能行水不流，世上相思何时已。"]},{"t":"长相思四首 其二","f":"古风","c":["长相思，路遥遥。","相思如大江水，相思如杨柳条。","杨柳条长尚可剪，大江水流不可断。","长相思，深复深。","平原莫绣五色线，子期莫铸双南金。","人生知己古亦少，相思之心向谁道。"]},{"t":"长相思四首 其三","f":"古风","c":["长相思，江悠悠。","洞庭木落三湘秋。","梦中不识别时路，九嶷云黯苍梧树。","翠华南去不复还，双娥洒泪愁空山。","五十哀弦雏凤语，鹧鸪啼处斑斑雨。","长相思，思转深。","请以白玉璞，琢出相思心。","三湘之水东入海，相思之心终不改。"]},{"t":"长相思四首 其四","f":"五言绝句","c":["三年不见郎，万里梦他乡。","江水直到海，寸心如许长。"]},{"t":"思君恩","f":"五言绝句","c":["君恩深似海，君德浩如天。","岁岁流红日，山呼亿万年。"]},{"t":"千里思","f":"古风","c":["五里复十里一，日不见心萦纡。","何况千里别十，年五年不得书。","君如天上云我，如水中泥云在。","青霄泥在水相，思千里不相知。"]},{"t":"静夜思","f":"楚辞体","c":["出门月色白如霜，静夜所思思断肠。","有美人兮天一方，碧云迢迢河汉长。","河汉长，不可越。","但有一寸心，含情托明月。","明月照人心不移，静夜所思谁得知。"]},{"t":"思归引","f":"古风","c":["寄声托明月，为我照家乡。","十年不得归，今夕在路傍。","路傍杨柳树，犹记来时路。","越鸟恋南巢，燕鸿怀北度。","去来南北无了期，人生莫作杨花飞。"]},{"t":"长歌引","f":"古风","c":["短歌歌不足，长歌断复续。","六龙之车海上来，千秋万古无停毂。","碾雪推霜入镜中，坐见绿发如飞蓬。","满堂窈窕春花红，长歌一曲歌未终，西陵陇树生秋风。"]},{"t":"秋梦引","f":"七言律诗","c":["井乌啼月银床冷，辘轳声断青丝绠。","美人梦逐綵云飞，鹦䳇隔窗呼不醒。","小鬟临镜双盘鸦，熏笼火暖篆烟斜。","一寸芳心化胡蝶，飞来自采芙蓉花。"]},{"t":"走马引","f":"五言律诗","c":["千金买骏骨，五花散春云。","章台杨柳陌，醉蹋落花春。","烽烟四边静，宝玦腰间冷。","寄谢少年人，男儿当惜身。"]},{"t":"估客乐","f":"五言绝句","c":["今日采石酒，明日广陵花。","大帆随处泊，终岁不思家。"]},{"t":"宫中乐","f":"五言绝句","c":["初日上蓬莱，平明玉殿开。","春风双凤琯，吹下世间来。"]},{"t":"绿水曲","f":"五言律诗","c":["绿水何盈盈，方舟出兰渚。","美人临清流，相期拾翠羽。","翠羽不可拾，春波荡人心。","人心如绿水，谁能知浅深。"]},{"t":"江南曲三首 其一","f":"七言绝句","c":["江上水生蒲叶短，白沙晴卧凫鹥暖。","木兰舟上紫云娘，笑入荷花羞见郎。"]},{"t":"江南曲三首 其二","f":"七言古诗","c":["水痕渐绿蒲芽短，雪消沙浦双凫煖。","一夜鹅黄著柳枝，春愁暗逐春潮满。","江上蒲帆鸟翼张，船头槌鼓出回塘。","吴中女儿不解饮，呼酒隔帘催劝郎。","并州剪刀金两股，不剪人间别离苦。"]},{"t":"江南曲三首 其三","f":"五言绝句","c":["湘云剪舞衣，楚月裁歌扇。","荡舟莲叶深，羞与郎相见。"]},{"t":"江上曲三首 其一","f":"七言绝句","c":["春江水深蒲叶短，双凫交颈晴沙暖。","青裙女儿木兰舟，白苧歌回花满头。"]},{"t":"江上曲三首 其二","f":"五言古诗","c":["郎乘木兰舟，说道长干去。","长干好女儿，留郎再三住。","郎留岂不好，妾思令人老。","郎心生蒺藜，不如女萝草。","妾有一掬泪，洒向大江流。","愿为西北风，吹转郎船头。"]},{"t":"江上曲三首 其三","f":"五言律诗","c":["蒲叶何短短，潮来江水满。","岂无金错刀，割水水不断。","山下蘼芜草，江边杜若花。","采芳思寄远，游子隔天涯。"]},{"t":"江皋曲","f":"五言绝句","c":["日暮清江上，临流采白蘋。","微波将远意，寄与弄珠人。"]},{"t":"春江曲","f":"七言绝句","c":["清江水深蒲叶短，野凫双浴春波煖。","吴宫女儿白苧歌，一曲春风吹不断。"]},{"t":"春波曲","f":"五言绝句","c":["新妇矶头雨，小姑山下云。","无情江上水，总是别离痕。"]},{"t":"金井曲","f":"五言绝句","c":["井上青丝绠，年深石有痕。","石痕犹不灭，况是感君恩。"]},{"t":"大堤曲","f":"五言律诗","c":["朝看堤上花，暮折堤上柳。","相送大堤人，同倾大堤酒。","酒酣蹋歌去，留郎堤上住。","翻翻白马蹄，草绿无寻处。"]},{"t":"大道曲","f":"五言绝句","c":["将军紫罗襦，燕坐城南陌。","手拨紫檀槽，市中人不识。"]},{"t":"横塘曲","f":"五言古诗","c":["妾家横塘口，门前种杨柳。","春风吹舞腰，劝饮桃花酒。","垂杨千万缕，下蘸横塘水。","何事织离愁，春风吹不起。","塘上谁家女，红裳白雪衣。","采菱愁日晚，相待月明时。","妾家住横塘，郎过须下马。","手把珊瑚鞭，挂在垂杨下。"]},{"t":"凉州曲","f":"五言绝句","c":["曾闻一斗酒，换得凉州牧。","寄语远征人，莫唱凉州曲。"]},{"t":"越城曲","f":"五言绝句","c":["尝胆不知苦，捧心徒自颦。","年年江水碧，愁杀浣纱人。"]},{"t":"城傍曲","f":"五言绝句","c":["乌啼城上头，枕戈明月下。","十年不得归，愿放华阳马。"]},{"t":"城门曲","f":"五言绝句","c":["城头乌夜啼，月落少城西。","夜半传军令，天明祭大旗。"]},{"t":"湖中曲","f":"五言古诗","c":["外湖湖水浊，里湖湖水清。","妾不爱浊水，长向里湖行。","手折芙蓉花，佳期碧云远。","临水照蛾眉，盈盈愁日晚。","日晚当奈何，湖中莲刺多。","回舟荡桨去，莫唱采莲歌。"]},{"t":"天河曲","f":"七言古诗","c":["天河之水向西流，双星夜夜当南楼。","机中细织云锦字，美人不来生远愁。","日夕河边待灵鹊，玉宇高寒露花落。","愁心飞绕金井阑，辘轳牵断青丝索。","灵槎一去秋冥冥，白榆千年那得青。","天上回波还入海，东西相望心不改。"]},{"t":"七夕曲","f":"七言古诗","c":["妾在河东郎在西，妾秉机杼郎扶犁。","夫田秋来不收谷，妾织锦云空满轴。","一年一度寄郎衣，妾抱苦辛郎不知。","今宵河畔一相见，风露无声乌鹊飞。","乌鹊飞来莫飞去，借尔河东白榆树。","树头结巢生子孙，不愁填河河水浑。","百年三万六千日，今日谁云逢七七。","人言织女嫁牵牛，灵鹊作桥天上头。","妾是河东天帝女，郎司天田妾机杼。","年年不敢误秋期，愿田有黍机有丝。","丝能煖人黍能饱，妾亦何心频赐巧。"]},{"t":"夜夜曲","f":"五言律诗","c":["夜夜望明月，初若蛾眉弯。","夜夜望明月，今如白玉盘。","玉盘有时缺，蛾眉愁万结。","月照闺中人，如何有离别。"]},{"t":"夜长曲","f":"七言律诗","c":["金虬无声银箭缓，清夜何长昼何短。","七星斜挂少城西，群乌叫月霜花满。","铜盘煖蜡绛纱明，胡蝶梦寒龟甲屏。","三尺床头白鹇尾，五更又逐鸡声起。"]},{"t":"寒夜曲 其一","f":"七言律诗","c":["绛河冻合白如霜，北斗挂树天苍苍。","美人裁衣金剪冷，梦入梨云吹不醒。","玉关迢迢南燕飞，灯花喜报行人归。","行人不归花自落，月满城头夜吹角。"]},{"t":"寒夜曲 其二","f":"七言律诗","c":["玉河回天冻光白，流云作冰飞不得。","铜龙嘶寒漏声涩，七星离离挂城北。","美人罗袜妒铅霜，兰烟唤香归洞房。","何人一笛关山月，吹落梅花满城雪。"]},{"t":"寒夜曲 其三","f":"七言律诗","c":["铜龙嘶寒漏声涩，夜半氍毹霜气入。","冻蜡凝膏不作花，地炉火煖麒麟泣。","酸风射入如箭急，燕律吹春竟何及。","平明起视三足乌，红盆刷羽冰花湿。"]},{"t":"寒夜曲怀二子","f":"七言古诗","c":["城头乌啼寒夜长，北斗挂树天苍苍。","展转不寐意徬徨，我思二子如凤凰。","大儿读书不下堂，小儿写字能成行。","我欲挟子翱且翔，手挥鸣弦发清商。","侧身西望千仞冈，令人怀思不能忘。"]},{"t":"采莲曲二首 其一","f":"七言绝句","c":["湖中女儿眉黛秋，采莲日日唱吴讴。","何如生长玉井水，同擢仙人一叶舟。"]},{"t":"采莲曲二首 其二","f":"五言古诗","c":["昨日采莲花，今日采莲子。","贱妾比红衣，宁教抱香死。","溪上采芙蓉，兰舟荡晚风。","叶如郎意薄，花似妾颜红。","采花莫临水，水深清见底。","水有见底时，郎心隔千里。","一去不思家，秋风吹若耶。","只愁霜露重，妾貌不如花。"]},{"t":"折荷曲","f":"五言绝句","c":["折荷莫折茎，中有千万丝。","秋风吹不断，总是长相思。"]},{"t":"结杨柳曲","f":"五言古诗","c":["千结江上柳，万结离人心。","千结与万结，何如结衣襟。","结襟尚可解，结心终不改。","初结明月环，再结同心带。","带以结绸缪，环以结欢爱。"]},{"t":"花游曲","f":"五言律诗","c":["东阑杏花雨，袅袅寒食烟。","相期洛阳陌，斗草赌金钱。","白玉装车轴，珊瑚作马鞭。","章台年少子，走马绿杨边。"]},{"t":"槟榔曲","f":"古风","c":["与郎相别时，槟榔高过屋。","妾有回文锦字诗，为郎翻作槟榔曲。","绿窗沈沈春昼閒，金盘钿合罗两鬟。","苦心一寸谁解识，中含血泪红斑斑。","昨梦郎归采蒌叶，丹髓凝春霞满颊。","愿封珠唾寄蛮笺，郎若见时还念妾。"]},{"t":"绿珠曲","f":"五言绝句","c":["郎有百斛珠，妾有一寸心。","宁甘坠楼死，花落故园深。"]},{"t":"田家曲","f":"七言律诗","c":["门前一雨秧田绿，柘叶重重覆茅屋。","今岁篱傍笋最多，南风一夜吹成竹。","趁煖吴蚕已上山，缫车声动水车閒。","幸喜村深无虎过，柴门终夜不曾关。"]},{"t":"蒿里曲","f":"古风","c":["蒿里曲，春草绿，人生百年如转烛。","石家美人双翠蛾，尊前妙舞扬清歌。","一朝艳骨化黄土，富贵浮云可奈何。"]},{"t":"出塞曲","f":"五言律诗","c":["将军乌角弓，壮士远从戎。","剑倚燕云白，旗翻汉日红。","雪窖数行泪，天山三箭弓。","铙歌应有曲，报捷未央宫。"]},{"t":"登楼曲","f":"五言绝句","c":["今夜凭高望，青天月色多。","入窗风露冷，开户看星河。"]},{"t":"迎客曲","f":"古风","c":["陈绮席，进华觞，主人临轩客上堂。","绮席陈，瑶觞进，清歌缓舞情无尽。"]},{"t":"携手曲","f":"五言律诗","c":["携手复携手，携手杏花前。","白玉装车轴，黄金铸马鞭。","容华易消歇，流光若逝川。","寄言贵游子，欢娱当少年。"]},{"t":"捣衣曲","f":"七言绝句","c":["去年捣衣郎有书，今年捣衣郎在途。","手悬双杵不敢下，只恐梦惊堂上姑。"]},{"t":"寄远曲","f":"七言律诗","c":["美人别后关山长，买丝绣得金鸳鸯。","鸳鸯交颈不飞去，与郎缝作征衣裳。","长长搓线莫教短，短线恐郎情易断。","衣成更写数行书，书中泪是蛟人珠。"]},{"t":"懊恼曲","f":"五言绝句","c":["懊恼复懊恼，懊恼无人知。","阿婆不嫁女，夜夜守空闺。"]},{"t":"吟叹曲","f":"古风","c":["王子乔，好神仙，吹玉笙，上青天。","七月七日缑山颠，青鸾白鹤相后先。","安得金丹蜕凡骨，我亦从之凌紫烟。"]},{"t":"双凫曲","f":"七言绝句","c":["江上春生蒲叶短，双凫昼卧晴沙暖。","一声欸乃钓船归，锦翼斑斑相逐飞。"]},{"t":"鸡鸣曲三首 其一","f":"七言古诗","c":["晨鸡初鸣当夜半，少妇出房愁思乱。","晨鸡再鸣月入帷，少妇出门郎马嘶。","晨鸡三鸣月在道，道上马嘶声渐杳。","马嘶渐杳鸡乱鸣，桃灯泣泪天未明。","后夜闻鸡北窗下，梦里鸡声候郎马。"]},{"t":"鸡鸣曲三首 其二","f":"七言律诗","c":["一鸣六龙海波赤，再鸣旸谷东方白。","三鸣阊阖参差开，紫云飞绕金银台。","天街夜夜鸡鸣早，珂佩朝回霜满道。","绮疏花影晏眠人，梦里鸡声不知晓。"]},{"t":"鸡鸣曲三首 其三","f":"七言古诗","c":["晨鸡初鸣月在堂，少妇挑灯开洞房。","晨鸡再鸣月在树，门前马嘶郎欲去。","城西月落鸡三鸣，出户不闻郎马声。","马声已远鸡声静，回首不知郎远近。","寄语晨鸡休浪啼，啼时愿郎归马嘶。"]},{"t":"乌栖曲","f":"七言绝句","c":["今夜乌栖向何处，哑哑飞绕深宫树。","宫中美人醉不醒，空劳尔乌啼到明。"]},{"t":"乌啼曲","f":"七言绝句","c":["秦乌哑哑啼复啼，夜夜不离庭树枝。","妾听乌啼识乌意，明日官家赦书至。"]},{"t":"城乌曲","f":"五言律诗","c":["乌啼城上树，飞来复飞去。","乌去有时来，郎今在何处。","月出女墙头，乌啼碧树秋。","哑哑声不断，啼月过西楼。"]},{"t":"别鹤曲","f":"七言律诗","c":["缟素作衣丹作顶，夜夜月明看舞影。","今朝童子起开笼，不闻戛戛回天风。","缑山仙人吹凤琯，八极无尘綵云断。","何由振羽当我前，借骑一只蓬莱天。"]},{"t":"骢马曲","f":"古风","c":["御史骢，青连钱，嘶风刷电朝九天。","昨日街头人避马，今朝喋血车轮下。","后夜鸡鸣闻曙钟，绣衣又复骑青骢。"]},{"t":"迎龙曲","f":"古风","c":["朝迎龙，暮迎龙，旱火烧天龙在宫。","县官投牒石潭中，山南山北鼓逢逢。","蜿蜒跃入杨枝水，山云一缕随龙起。","龙未离山雨到城，城中三日不得晴。","明朝打鼓送龙去，愿龙十日行一雨。","种田有水刈麦乾，年年谢龙神亦欢。"]},{"t":"送龙曲","f":"古风","c":["迎龙来，送龙去，翠雾红云拥龙驭。","家家买纸谢龙神，甘雨应期龙有灵。","明珠之宫紫贝阙，碧潭无声湛秋月。","愿龙在山云在天，岁岁谢龙歌有年。"]},{"t":"乌栖曲","f":"七言绝句","c":["城头月明乌夜栖，栖到天明啼复啼。","底事夜栖朝复去，不识朝阳凤凰树。"]},{"t":"迎龙词","f":"古风","c":["鼍鼓逢逢，龙在王宫。","电虩虩，云重重。","启贝阙，精诚通。","驱五雷，招八风。"]},{"t":"送龙词","f":"楚辞体","c":["龙之来，兮蜿蜒。","龙之去，兮连蜷。","沛神泽兮沃秋田，云为车兮电为鞭。","陈玉醴，进琼筵，感神惠兮不可言。","愿五风，兮十雨，绥万邦兮屡丰年。"]},{"t":"白鹦鹉词","f":"古风","c":["白鹦鹉，陇西来，金笼驯养无人开。","绮窗谈舌学人语，字字分明如处女。","一朝持入沈香亭，玉环自教蜜多经。","解听月殿霓裳曲，惯识梨园羯鼓声。","无端羽化冲霄去，?在碧桃花落处。","陇头迢遰陇云深，无复重栖旧时树。"]},{"t":"山鹧鸪词 其一","f":"七言绝句","c":["劝郎莫过洞庭湖，湘妃庙前啼鹧鸪。","可恨九嶷山隔断，翠华无处问苍梧。"]},{"t":"山鹧鸪词 其二","f":"七言绝句","c":["江上有山复有山，鹧鸪啼处雨斑斑。","一声两声行不得，南船北船朝暮还。"]},{"t":"精卫词","f":"古风","c":["精卫精卫飞且鸣，千年填海海不平。","世传此是炎帝女，不知何年填海水。","海山石烂海水枯，是时精卫安得无。","如何精卫鸟，只填东海水。","海水尚可填，人心浩无底。"]},{"t":"鲛人词","f":"七言律诗","c":["并刀翻水凝不流，碧绡如烟张素秋。","蛟人夜织鱼鳞屋，月色澄澄湛寒绿。","卖绡来从城市居，主翁不识明月珠。","明珠赠君世无价，明年有绡复来卖。"]},{"t":"蚕簇词","f":"古风","c":["拜蚕室，祭神桑，吴蚕在箔神在堂。","愿神佑蚕风日好，取茧倍多蚕缕长。","十日天阴未开箔，蚕吐丝迟茧还薄。","地炉火煖借春回，再祷神蚕须急作。","缫车易转茧易抽，长丝满桁晴不收。","新妇登堂向姑道，今岁衣姑丝不少。"]},{"t":"神树词","f":"七言古诗","c":["田家种田无五行，屋西神树生有灵。","年年祭树卜水旱，祈雨即雨晴须晴。","鸡豚拜扫无閒日，乌鹊群飞来啄食。","剪纸作钱挂树枝，祝田有来蚕有丝。","收麦上场神得食，缫丝纳官神得衣。"]},{"t":"田家词","f":"七言古诗","c":["村巷深深枣花落，少妇缫丝催织作。","上堂正恐阿婆瞋，不愤田头叫姑恶。","大儿翻垄牵疲牛，小儿作军边上头。","今年雨多麦穗黑，较比上年无半收。","白头不愿识官府，但愿有租应门户。"]},{"t":"渔父词 其一","f":"古风","c":["家住琴江江，上头拓卦洲。","前春水流桂，枝楫木兰舟。","终日忘鱼不下钩。"]},{"t":"渔父词 其二","f":"古风","c":["侬是烟波一钓徒，持竿东海拂珊瑚。","女儿港，番君湖，浪静风恬过小孤。"]},{"t":"渔父词 其三","f":"古风","c":["黄梅岭下是侬家，白石矶边把钓车。","友麋鹿，侣鱼虾，不在山颠即水涯。"]},{"t":"渔父词 其四","f":"古风","c":["大江西去是，庐山云白山。","青罨画间彭，蠡泽海门关。","莫待风波及早还。"]},{"t":"渔父词 其五","f":"古风","c":["白石矶头春水流，朝朝暮暮伴沙鸥。","山渺渺，水悠悠，笑杀磻溪下直钩。"]},{"t":"渔父词 其六","f":"古风","c":["磻溪野老发垂肩，钓得周家八百年。","鱼换酒，不论钱，醒即长歌醉即眠。"]},{"t":"仙人词","f":"七言绝句","c":["金鳌背上蕊珠宫，千岁桃花几度红。","曾见茂陵松柏下，铜仙清泪落秋风。"]},{"t":"秋胡词","f":"七言律诗","c":["陌头桑叶春阴阴，少妇采桑多苦心。","朝来出门日已晏，蚕饥叶稀姑未饭。","少年骑马桑间来，黄金不博笑颜开。","但令人似秋胡妇，世上黄金不如土。"]},{"t":"吴女词二首 其一","f":"七言绝句","c":["吴中女儿绝可怜，裁得春衫称少年。","身未嫁夫无处著，至今留在母床边。"]},{"t":"吴女词二首 其二","f":"五言绝句","c":["二八吴女儿，画桨摇春煖。","贪看双鸳鸯，采菱归日晚。"]},{"t":"征妇词","f":"七言律诗","c":["妾身愿如弓上弦，万里随郎长在边。","郎身莫如弦上箭，一去无还不相见。","堂上阿婆今白头，妾守空闺郎远游。","请郎看取门前树，上有慈乌不飞去。"]},{"t":"去妇词三首 其一","f":"五言律诗","c":["出户心悄悄，中情向谁道。","吞声不敢啼，又恐傍人笑。","妾有嫁时镜，请郎留自照。","镜里见新人，还思旧人貌。"]},{"t":"去妇词三首 其二","f":"古风","c":["东山生兔丝，西山生蒺藜。","二物不相偶，美恶人自知。","妾有堂上姑，妾有怀中儿。","生儿未及长，姑老将何依。","妾今别夫去，裴回向何处。","他日黄泉相见时，墓前莫种相思树。"]},{"t":"去妇词三首 其三","f":"五言古诗","c":["妾去何足惜，妾留不自安。","高堂有老姑，孰知饥与寒。","妾昔念有家，妾今如风花。","何如千尺松，而不附女萝。","哀哀别姑去，泪下不能语。","姑若念妾时，看取床头女。"]},{"t":"老妇叹镜词二首 其一","f":"七言古诗","c":["妾有团团古时镜，在匣浑如月端正。","朝朝持向玉台前，秋水芙蓉两相映。","自从十五画脩蛾，白发相看尘渐多。","绣得合欢双宝带，今朝携上街头卖。","满城新镜照新人，此镜无人定高价。"]},{"t":"老妇叹镜词二首 其二","f":"七言古诗","c":["妾有团团嫁时镜，比似青天月端正。","少年锦带绣芙蓉，照妾颜色如花红。","妾今对镜头如雪，辜负青天端正月。"]},{"t":"明镜词","f":"五言古诗","c":["我有古时镜，照君玉雪颜。","湛然如止水，终古无波澜。","世人但照面，照心不自见。","照面不照心，妍媸竟何辨。","所以百鍊精，鬼神无遁情。","愿为千里月，远近逐君行。"]},{"t":"照镜词","f":"五言绝句","c":["颜看镜中红，发看镜中白。","如何一寸心，镜中看不得。"]},{"t":"照镜词赠镊工潘郎","f":"七言古诗","c":["潘郎买得扬州镜，团团比似扬州月。","持向扬州住十年，旦暮照人头上雪。","明月楼前问月人，琼花观里赏花春。","回头不觉红颜改，对面应嗟白发新。","男儿立功当及早，莫向潘郎镜中老。"]},{"t":"白苧词三首 其一","f":"古风","c":["剪冰绡，缝雪缕，馆娃宫人越溪女。","回风吹雪长袖举，玉阶缤纷落花舞。","白月堕地星河高，流云卷空翻翠涛，宫门鱼钥夜迢迢。"]},{"t":"白苧词三首 其二","f":"七言古诗","c":["绿窗樱桃花乱飞，美人当窗缝舞衣。","纤歌窈窕扬蛾眉，鸾停鹄立佩陆离。","馆娃宫深更漏稀，北斗斜挂宫门西，觚棱渐明乌人啼。"]},{"t":"白苧词三首 其三","f":"七言律诗","c":["浣纱女儿颜如花，一朝进入吴王家。","吴王宫中歌白苧，水殿芙蓉不知暑。","翔鸾舞鹄雪满堂，回风吹花响屧廊。","宫门乌啼更漏长，曈曈旭日生榑桑。"]},{"t":"焦尾词","f":"五言古诗","c":["龙门千尺桐，化为爨下焦。","不遇蔡中郎，大音终寂寥。","所以九苞凤，千年鸣一朝。"]},{"t":"团扇词二首 其一","f":"五言古诗","c":["明月有时缺，团扇空自圆。","月缺终还满，扇圆仍弃捐。","不如秋水镜，长挂玉台前。"]},{"t":"团扇词二首 其二","f":"七言绝句","c":["团扇团如白玉盘，玉盘比似月团团。","早知玉树秋风近，不把閒愁写素纨。"]},{"t":"香风词","f":"七言绝句","c":["洛阳万花如锦机，春风吹上绣罗衣。","日高走马章台路，蛱蝶一双相逐飞。"]},{"t":"春夜词","f":"七言律诗","c":["大江春水流汤汤，中有万斛之龙骧。","南北二斗相低昂，泰阶六符白煌煌。","牵牛织女遥相望，欲渡不渡河无梁。","我思美人天一方，展转不寐愁何长。"]},{"t":"游春词","f":"五言绝句","c":["杏雨不沾泥，流莺恰恰啼。","弯弓驰紫陌，跃马过金堤。"]},{"t":"乞巧词","f":"古风","c":["平生甘抱拙，何用天孙巧。","不知柳柳州，年年乞多少。","天孙今夜渡天河，人言天上巧最多。","妾今抱拙不求巧，愿赐拙多宁巧少。","东家巧女如凤凰，罗襦绣得金鸳鸯。","少年嫁夫先得巧，明珠论斗金盈箱。","妾守空闺甘寂寞，苦心不恋东家乐。","却笑天孙长别离，纵使巧多徒尔为。"]},{"t":"唐宫行乐词 其一","f":"七言绝句","c":["明日内家游上苑，许教斗草赌金钗。","怕人先记花名字，隔夜潜偷玉篆牌。"]},{"t":"唐宫行乐词 其二","f":"七言绝句","c":["华清赐浴晚凉回，水殿芙蓉彻夜开。","碧盌调冰消酒渴，金盘又进荔枝来。"]},{"t":"调笑词二首 其一","f":"古风","c":["杨柳，杨柳，一夜绿如春酒。","今朝起送归人，关山千里暮春。","暮春，暮春，春暮目断天涯烟树。"]},{"t":"调笑词二首 其二","f":"古风","c":["胡蝶，胡蝶，飞绕碧桃千叶。","今朝走觅南邻，明日天涯暮春。","暮春，暮春，春暮花落蝶归何处。"]},{"t":"刺促词","f":"五言律诗","c":["刺促何刺促，夜泊长江曲。","同是远游人，何须论迟速。","刺促复刺促，刺促向谁道。","青青高山树，不如墙下草。"]},{"t":"宛转词 其一","f":"七言绝句","c":["宛宛转转车下轮，红红绿绿百花春。","纷纷汨汨马蹄尘，寂寂寞寞闺中人。"]},{"t":"宛转词 其二","f":"七言绝句","c":["宛宛转转机上丝，红红绿绿绣为衣。","纷纷汨汨胡蝶飞，寂寂寞寞人别离。"]},{"t":"宛转词 其三","f":"七言绝句","c":["宛宛转转弦上音，红红绿绿陇西禽。","纷纷汨汨愁人心，寂寂寞寞春闺深。"]},{"t":"采菱词","f":"五言古诗","c":["江水明于镜，江波皱如縠。","采菱溪上头，爱此溪水绿。","昨日采菱去，菱多满载归。","今日采菱去，叶多菱角稀。","采菱不采叶，空回木兰楫。","菱刺牵人衣，江空正愁妾。"]},{"t":"采莲词","f":"五言绝句","c":["秋风昨夜起，花落翠房深。","欲识妾心苦，试尝莲子心。"]},{"t":"浮萍词","f":"七言绝句","c":["半随波浪半黏沙，漂泊东西不恋家。","莫怪生来无定迹，只缘根本是杨花。"]},{"t":"新柳词","f":"七言绝句","c":["纤腰袅袅春风前，十五女儿真可怜。","天气困人眉不展，也随蚕事学三眠。"]},{"t":"柳花词二首 其一","f":"七言绝句","c":["迎得春来又送归，被他撩乱扑征衣。","莫教十字街头种，花到开时四散飞。"]},{"t":"柳花词二首 其二","f":"五言古诗","c":["随风为白雪，入水化青萍。","无限离人意，长亭又短亭。","上天如白云，入水化萍叶。","云萍无定踪，如何不愁妾。","盈盈墙下桃，花落子留树。","薄命似杨花，随风不知处。","朝扑绮罗衣，夕委黄尘道。","不知长江上，化作浮萍草。"]},{"t":"杨柳词二首 其一","f":"七言绝句","c":["扬子江边杨柳条，风前学舞斗纤腰。","来往游人攀折少，也胜种在灞陵桥。"]},{"t":"杨柳词二首 其二","f":"五言律诗","c":["袅袅翠腰柔，春来舞到秋。","郎行莫回顾，中有断肠愁。","一缕一缕愁，千丝千丝苦。","宁见章台春，莫逢灞陵雨。"]},{"t":"柳枝词 其一","f":"七言绝句","c":["一送离人折一枝。","长条折尽短条衰。","飞花自是浮萍草，莫向尊前怨别离。"]},{"t":"柳枝词 其二","f":"七言绝句","c":["门前杨柳欲藏鸦。","可恨萧郎不在家。","妾有蛾眉如柳叶，郎今踪迹似杨花。"]},{"t":"柳枝词 其三","f":"七言绝句","c":["旧日吴王百尺台。","万株杨柳是谁栽。","阊门城外春阴里，多少将军繫马来。"]},{"t":"杨柳枝词","f":"七言绝句","c":["郎听妾歌杨柳枝。","明年二月望郎归。","柳眉如妾镜中黛，柳色比郎身上衣。"]},{"t":"竹枝词 其一","f":"七言绝句","c":["溪北溪南春雪消。","溪水一夜忽平桥。","明朝艇子载书画，繫在屋前杨柳条。"]},{"t":"竹枝词 其二","f":"七言绝句","c":["屋前柳色鹅儿黄。","鹅儿队队在林塘。","柳色似鹅鹅似酒，春来自是断人肠。"]},{"t":"博溪舟中赋竹枝词 其一","f":"七言绝句","c":["东溪月出西溪阴。","溪上荡舟溪水深。","郎今唱歌向何处，白鸟湾头高树林。"]},{"t":"博溪舟中赋竹枝词 其二","f":"七言绝句","c":["白鸟湾头高树林。","十年相约到如今。","拢船不怕风波急，侬有竹篙知浅深。"]},{"t":"西湖竹枝词 其一","f":"七言绝句","c":["荷叶盖头花拂衣。","今夜采莲当早归。","昨日小孤回棹晚，鸳鸯惊过里湖飞。"]},{"t":"西湖竹枝词 其二","f":"七言绝句","c":["侬家住在玛瑙坡。","与郎湖上采么荷。","侬比莲心心最苦，郎如藕丝丝更多。"]},{"t":"西湖竹枝词 其三","f":"七言绝句","c":["妾是藕条郎似荷。","劝郎听唱竹枝歌。","藕条抱节丝难断，荷叶留心苦更多。"]},{"t":"西湖竹枝词 其四","f":"七言绝句","c":["妾是浮萍郎似花。","花随风去落天涯。","浮萍只恋池中水，花性飘扬不恋家。"]},{"t":"西湖竹枝词 其五","f":"七言绝句","c":["妾是荷花郎是萍。","萍随波浪任飘零。","荷心不离泥中藕，花谢明年叶再青。"]},{"t":"西湖竹枝词 其六","f":"七言绝句","c":["郎是天河妾是星。","与郎相见最分明。","河流只向西南去，抛妾东边渡不成。"]},{"t":"西湖竹枝词 其七","f":"七言绝句","c":["西子湖边杨柳花。","随风随雨落天涯。","莫教飞入湖中去，化作浮萍不恋家。"]},{"t":"西湖竹枝词 其八","f":"七言绝句","c":["湖中荷叶绿田田。","恰似人间子母钱。","若能买得春愁断，侬亦移家傍水边。"]},{"t":"过浦赋竹枝词 其一","f":"七言绝句","c":["通浦灞前春雨晴。","大船小船南北行。","凭仗篙师一问讯，归帆已到秀州城。"]},{"t":"过浦赋竹枝词 其二","f":"七言绝句","c":["雪后江南春到时。","鹅黄已染杨柳枝。","东风不解离别意，一日恼人千万丝。"]},{"t":"次韵王继学滦河竹枝词 其一","f":"七言绝句","c":["滦河嘴头积雪多。","山下石子青盘陀。","侬在江南望江北，恰如织女隔天河。"]},{"t":"次韵王继学滦河竹枝词 其二","f":"七言绝句","c":["百两宫车碾雪泥。","山前二月春草齐。","去年羽书星火急，妇女上马小儿啼。"]},{"t":"次韵王继学滦河竹枝词 其三","f":"七言绝句","c":["滦河杏花如雪匀。","小雨三日不生尘。","垆头少妇劝郎酌，花如人面草如茵。"]},{"t":"次韵王继学滦河竹枝词 其四","f":"七言绝句","c":["去年大旱气不苏。","道傍行泣妇与姑。","不似江南连月雨，夜夜夜啼山鹧鸪。"]},{"t":"次韵王继学滦河竹枝词 其五","f":"七言绝句","c":["滦阳河畔女如云。","生长不识江南春。","大字青帘卖官酒，莫辞注玉更倾银。"]},{"t":"次韵王继学滦河竹枝词 其六","f":"七言绝句","c":["山前马嘶苜蓿花。","山下麻茹胜蕨芽。","细肋沙羊割红玉，不识雪水夜煎茶。"]},{"t":"次韵王继学滦河竹枝词 其七","f":"七言绝句","c":["白翎双飞秋草黄。","云沙万里接天长。","番僧个个杨梅帽，日暮闻钟来上方。"]},{"t":"次韵王继学滦河竹枝词 其八","f":"七言绝句","c":["天上金根回六龙。","年年田舍及秋舂。","白头父老出门拜，汉官威仪今载逢。"]},{"t":"次韵王继学滦河竹枝词 其九","f":"七言绝句","c":["蓟门关外故人居。","十年不见音问疏。","昨日江头见来雁，寄得滦河一纸书。"]},{"t":"次韵王继学滦河竹枝词 其十","f":"七言绝句","c":["李陵台西避暑宫。","穹庐月白夜生风。","吴侬解唱竹枝曲，此调不与江南同。"]},{"t":"竹枝词 题梅效竹枝体","f":"七言绝句","c":["侬家向南雪一株。","春后春前常见渠。","瘦影从教比郎瘦，孤山终不似侬孤。"]},{"t":"竹枝词 其一 过太湖竹枝歌","f":"七言绝句","c":["第四桥头枫叶青。","白龙吹雨浪花鯹。","过桥买酒待月出，今夜夜宿垂虹亭。"]},{"t":"竹枝词 其二 过太湖竹枝歌","f":"七言绝句","c":["青裙女儿双髻螺。","唱得吴宫子夜歌。","酒醒月明眠不得，秋风吹落洞庭波。"]},{"t":"竹枝词 其三 过太湖竹枝歌","f":"七言绝句","c":["西山日落东山黄。","侬唱竹枝行晚凉。","十幅蒲帆弓样满，南风吹过白龙堂。"]},{"t":"薤露歌","f":"古风","c":["薤上露，何离离。","人生不满百，欢乐当及时。","东方三足乌，啼老榑桑枝。","古来圣与贤，一去无还期。","薤上露，令人悲。","薤上露，何瀼瀼。","蓬莱变清浅，海水漂枯桑。","有生会俱尽，宁论弱与强。","空馀三尺土，千年閟幽光。","薤上露，令人伤。","薤上露，何漙漙。","朝日上陇头，叶上露易乾。","乌啼松树间，相送入空山。","白骨委黄壤，亲朋各自还。","薤上露，令人叹。"]},{"t":"云歌","f":"五言古诗","c":["五色承朝日，晖晖黼黻衣。","朝随黄鹤去，暮逐玉龙飞。","欲知栖息处，长是恋金扉。"]},{"t":"白日歌二首 其一","f":"七言绝句","c":["烛龙烛龙尔何速，三绳莫繫乌三足。","鲁阳之弋徒尔为，安得长挂榑桑枝。"]},{"t":"白日歌二首 其二","f":"古风","c":["东榑桑，西若木，中有赤龙口衔烛。","东驰西走无停毂，人生何为苦不足。"]},{"t":"子夜歌","f":"五言绝句","c":["试问铜壶水，今宵几许深。","漏长如妾泪，水浅是郎心。"]},{"t":"吴宫子夜四时歌","f":"五言古诗","c":["御柳袅金丝，宫莺拂柘衣。","帘阴随日转，漏点出花迟。","雨过太湖上，芙蓉水殿开。","綵舟邀月上，玉盌送冰来。","玉宇夜沈沈，天河似海深。","下阶齐拜月，纤手学穿针。","城上七星低，宫鸦绕树啼。","朔风吹不入，自有辟寒犀。","美人歌竹枝，胡蝶傍花飞。","白日东窗静，金刀剪苧衣。","雨过湖波绿，荷花水殿开。","隔花人似玉，船上买冰来。","秋风昨夜起，吹月到房栊。","梦入关山去，江枫树树红。","一尺街头雪，朝来没马蹄。","狐裘不觉煖，更有辟寒犀。"]},{"t":"襄阳歌","f":"古风","c":["襄阳太守白接䍦，襄阳儿唱白铜鞮。","今朝载酒向何处，言往习家池上去。","醉春日，歌春风。","马上归，花正红。"]},{"t":"吴歌","f":"七言绝句","c":["第四桥边枫叶秋，青裙少妇木兰舟。","月明打桨唱歌去，惊起芦花双白鸥。"]},{"t":"商歌","f":"七言律诗","c":["白日粲粲南山阿，长夜漫漫愁奈何。","停车夜宿郭门外，悲风烈烈闻商歌。","歌云不遭舜与尧，单衣短布风萧萧。","人生卑微何可忽，后车载之相齐国。"]},{"t":"吴人歌","f":"古风","c":["江悠悠，挽使舟。","吴人歌，歌邓侯。","江水东流去不返，邓侯邓侯舟莫挽。"]},{"t":"东邻美女歌","f":"五言绝句","c":["机上凤凰梭，盈盈抹两蛾。","谢鲲双齿折，犹不废鸾歌。"]},{"t":"廉叔度歌","f":"七言绝句","c":["成都太守廉叔度，三年守城人案堵。","桑叶阴阴歌满路，不歌一襦歌五裤。"]},{"t":"范史云歌","f":"古风","c":["三日不食釜生鱼，五日不食甑生尘。","丈夫未遇甘贱贫，呜呼，岂无人间范史云。"]},{"t":"独漉歌","f":"古风","c":["独漉独漉，水深没足。","水中有泥不见玉，世上人心易翻覆。"]},{"t":"扊扅歌二首 其一","f":"古风","c":["停赵舞，罢秦声，妾歌扊扅君试听。","五羖皮，西入秦。","妾烹伏雌君远行，君今富贵忘贱贫。"]},{"t":"扊扅歌二首 其二","f":"古风","c":["燃蜡不如炊扊扅，炰凤不如烹伏雌，太官之羊不如五羖皮。","妾弹秦筝君不知，吁嗟乎百里奚。"]},{"t":"骊驹歌二首 其一","f":"古风","c":["朝出北郭门，骊驹在路傍。","路傍秋草短，江月白如霜。","歌骊驹，唱吴歈。","千里万里道，三年两年书。","愿为金络随君马，愿为双轮逐君车。"]},{"t":"骊驹歌二首 其二","f":"古风","c":["河之水，清泱泱，津吏伐鼓声镗镗。","主当渡河吏乃醉，女娟操舟赎父罪。","持楫中流发棹歌，津吏酒醒女渡河。","鸳鸯双飞可奈何。"]},{"t":"黄鹄歌","f":"七言古诗","c":["太液池水清涓涓，金衣菊裳下九天。","建章宫中生紫烟，凤凰来仪羽翩翩。","至德广被千万年。"]},{"t":"凤凰操","f":"楚辞体","c":["凤凰兮衔图，殷道衰兮周德之符。","岐山兮苍苍，五色烂兮朝阳。","殷日短兮周日长。","千秋万岁兮于彼翱翔。"]},{"t":"别鹤操","f":"古风","c":["别鹤翩翩，结缡五年。","吁嗟乎，欲移我所，天中夜倚户心悁悁。","妾心直如琴上弦，为君一弹别鹤篇。"]},{"t":"精卫操","f":"古风","c":["石磊磊，海茫茫。","白石不可烂，海尘何日黄。","嗟哉精卫尔勿伤，昨日麻姑过东海，蓬莱弱水又生桑。"]},{"t":"越裳操","f":"古风","c":["有雉有雉，来于越裳。","文王之德，孚于万方。","远人其归，家国永昌。"]},{"t":"襄陵操","f":"楚辞体","c":["登彼会稽兮洪水滔滔。","嗟我黔首兮百万嗷嗷。","胼胝兮乘橇，过门不入兮使我心劳。"]},{"t":"涂山操","f":"古风","c":["有白者狐，九尾差差。","时哉时哉，应彼昌期。","水土底平，告功锡圭。","坤德承乾，维王之基。"]},{"t":"箕山操","f":"楚辞体","c":["箕之山兮颍之阳，箕之人兮濯沧浪。","彼何人兮牵牛，吾洗耳兮徜徉。"]},{"t":"湘灵操二首 其一","f":"楚辞体","c":["湘之水兮潺潺，湘之竹兮斑斑。","湘之女兮绿云间，望重华兮不复还。","九嶷兮苍苍，青猿啼兮夜何长。","折琼芳兮寄远，鼓瑶瑟兮心伥伥。"]},{"t":"湘灵操二首 其二","f":"古风","c":["湘之水，清泱泱，二妃夜泣青筼筜。","斑斑清泪流不尽，五十哀弦瑶瑟冷。","鹧鸪啼处数峰青，一夜月明悲洞庭。"]},{"t":"八公操二首 其一","f":"古风","c":["淮南王，好神仙。","朝餐金盘之玉屑，夕鍊宝鼎之神丹，骑龙下上超天关。","超天关，驭天风，山前桂树青丛丛。","人间白日西复东，安得从之招八公。"]},{"t":"八公操二首 其二","f":"七言古诗","c":["淮山苍苍淮水黄，桂树丛生山之阳。","丹砂成金寿命长，身骑飞龙恣翱翔。","千秋万古乐未央。"]},{"t":"石妇操","f":"古风","c":["山头白石高数尺，人言贞妇化为石。","贞妇化石不回头，俯视千年江水流。","江水流，不可断。","行人归，白石烂。"]},{"t":"伤殷操","f":"楚辞体","c":["麦渐渐，黍油油，昔日殷墟今日周。","吞声不语泪交流，玉杯象箸兮，何以解忧。"]},{"t":"思亲操","f":"古风","c":["儿陶于河，有乌傞傞。","儿渔于泽，有乌翼翼。","彼乌返哺，历山之下。","归哉归哉，慰我父母。"]},{"t":"履霜操","f":"楚辞体","c":["晨履霜兮，河之上。","考不顾兮，儿见放。","儿饥而寒兮，蓐食而荷衣。","䜛口铄金兮，考胡不知。","吁嗟命之穷兮，于河之湄。"]},{"t":"采薇歌","f":"楚辞体","c":["西山有薇，薄言采之。","周人有粟，弗疗我饥。","宁薇而甘兮，毋粟而惭兮。","维首阳之岩岩兮。"]},{"t":"崩城操二首 其一","f":"古风","c":["一哭长城崩，谁言土无情。","至今城下水，犹闻呜咽声。","吾皇万古基太平，妇女不哭城不倾。","城不倾，四海宁。"]},{"t":"崩城操二首 其二","f":"五言绝句","c":["以妾眼中泪，洒向城下土。","城崩见夫骨，始知妾心苦。"]},{"t":"君道篇","f":"古风","c":["夸娥莫移山，精卫莫填海。","天作高山与海深，黄河一清圣人在。","圣人有道津梁通，千门万户皆春风。","岂不闻越裳重译贡白雉，万国归之若流水。"]},{"t":"美女篇","f":"五言古诗","c":["有女颜如花，生长越王家。","浣纱白石上，何曾知馆娃。","高台凌青天，朝歌暮复弦。","宫人裁白苧，只知长少年。","日月无停车，流光迅于电。","春风吹落花，不到黄金殿。"]},{"t":"宝剑篇","f":"五言律诗","c":["床头有古剑，白虹夜流辉。","炯然三尺雪，化作青蛇飞。","岂无千金直，待价将安归。","挂向徐君墓，时闻鬼母啼。"]},{"t":"明珠篇","f":"五言律诗","c":["煌煌明月珠，乃在龙颔下。","下沈无底谷，得之世无价。","或人不爱宝，弹雀千仞冈。","得失何足较，所嗟无夜光。"]},{"t":"君道篇","f":"五言古诗","c":["君道天广大，王言出如纶。","雨露及草木，万物皆阳春。","九重坐南面，四海奉一人。","禹稷犹已溺，唐虞视同仁。","华盖当中天，列星环北辰。"]},{"t":"月漉漉篇","f":"古风","c":["月漉漉，银塘曲。","兔影蘸金波，龙绡皱文縠。","越女浣纱归，双蛾湿秋影。","移舟明镜中，露下菱花冷。"]},{"t":"白马篇","f":"七言古诗","c":["房星夜坠秋河碧，夭矫雄姿龙八尺。","何年飞下九重天，自□人间骑不得。","置之天上白玉阑，长鸣直欲趋天关。","瑶池碧桃千万片，回风吹雪春斑斑。","不学开元照夜白，西入褒斜走荆棘。","愿逐轩辕凌紫霞，远游常在太清家。"]},{"t":"黄鹄行","f":"古风","c":["东海有黄鹄，两雏何翩翩。","朝戏沧海上，暮栖琼树颠。","一朝挟其雏，裴回上青天。","一雏归故巢，一雏委身草莽间。","黄鹄哀鸣向他山，侧身东望何时还。","他山岂无匹，凤凰五色翰。","渴有醴水，饥有琅玕。","黄鹄不愿同饮啄，得归东海心即乐。"]},{"t":"野田黄雀行","f":"古风","c":["黄雀啄啄野田间，饥鹰侧目下空山。","黄雀投虞罗，低摧伤羽翰。","少年拔剑捎罗网，黄雀高入青云上。","回首裴徊谢少年，虞罗勿令张野田。"]},{"t":"日出入行","f":"古风","c":["海东之山曰桃都，上有三足黄金乌。","三更乌啼海色动，六龙飞出榑桑隅。","浴旸谷经天衢羲，和揽辔无停车吾。","不知东西相去几万里，夜入咸池朝复起。","紫云红雾天苍苍，为天作眼明四方。","臣愿陛下八万四千岁，日出日没皆封疆。"]},{"t":"月初生行","f":"古风","c":["月初生二八，蛾眉初画成。","渐如弓弦复如镜，一月两回亏复盈。","弓弦不射天外信，明镜不照人间情。","马上行行屡回首，一钩空挂他乡柳。"]},{"t":"北风行","f":"七言绝句","c":["北风萧萧寒堕指，悲笳一声泪如水。","丈夫生出玉门关，回首家乡数千里。"]},{"t":"苦热行","f":"古风","c":["江南五六月，无地寻清凉。","东家少年不怕暑，玉盌冰花调蔗浆。","平头奴子面如玉，纨扇驱风入脩竹。","安知跃马走红尘，畏途炎蒸愁杀人。"]},{"t":"冬暖行","f":"古风","c":["冬日何短短，昨日苦寒今日暖。","不见门前桃李花，一时向暖舒春葩。","花前一双黄蛱蝶，东家飞过还西家。","明朝严霜凋百草，蛱蝶不来花又老。"]},{"t":"少年行二首 其一","f":"七言律诗","c":["越罗春衫绣凤凰，黄金压辔青丝缰。","张绪风流骋年少，走马章台游猎场。","斗鸡五坊白日晚，夜宿倡楼不知返。","白日西飞海倒流，红颜少年春复秋。"]},{"t":"少年行二首 其二","f":"五言律诗","c":["白马紫游缰，行过洛阳道。","不顾落花飞，只道青春好。","日日青楼醉，章台蹋月归。","秋风昨夜起，又试越罗衣。"]},{"t":"壮士行","f":"七言律诗","c":["千金宝刀百金马，称是人间骁勇者。","射虎曾过南山前，斩蛟复入长桥下。","何不生出玉门关，为君谈笑斩楼兰。","汉家得此英雄将，塞上琵琶怨莫弹。"]},{"t":"从军行","f":"五言绝句","c":["万里燕山道，花开不见春。","闺中儿在腹，何日替爷身。"]},{"t":"狭邪行","f":"五言古诗","c":["朝行狭邪路，暮行狭邪路。","谁道不容车，双轮竟朝暮。","路狭尚可过，人心易风波。","相逢不相识，如隔万里河。","惊飙吹落叶，寒衣在故箧。","莫抱齐门竽，且弹冯生铗。","虎啸风出山，龙升云上天。","狭邪勿云狭，王道自平平。"]},{"t":"蓟门行","f":"五言古诗","c":["天上白雪飞，将军朝猎围。","大野地椒短，草深狐兔肥。","健儿先报捷，生缚楼兰归。"]},{"t":"步出夏门行","f":"古风","c":["步出夏门，言登泰山。","道逢赤松，方瞳玉颜。","飞霞为佩，明月为环。","授我宝诀，惠我大丹。","回视东海，黄尘蔽天。","骖麟翳凤，逍遥永年。"]},{"t":"采桑行","f":"古风","c":["结发五日与郎别，妾颜如花命如叶。","桑间五见戴胜飞，高堂姑老郎不归。","郎归有黄金，妾心终不移。","若欲知妾心，沂水清瀰瀰。"]},{"t":"宛转行二首 其一","f":"古风","c":["宛转复宛转，一日千万思。","宛转如琴上弦，宛转如机上丝。","机中别愁安可织，弦中别愁弹不得。","关河迢迢隔远天，归路直如琴上弦。","人间安得并州剪，剪断琴弦与机丝，别情庶有穷尽时。"]},{"t":"宛转行二首 其二","f":"古风","c":["宛转复宛转，宛转如水中波。","宛转复宛转，宛转如机上梭。","水波流恨去不返，机梭织愁可奈河。","人生托交在知己，何论千里与万里。","长沙尚谪贾少年，东海谁招鲁连子。","丰城双剑埋泥沙，斗间紫气腾光华。","当时张雷不识宝，千年绣涩生苔花。","我歌宛转行，使君倾耳听。","圣人在位黄河清，腰金佩玉皆俊英。","莫恋山中紫芝好，丈夫立功当及早。"]},{"t":"宛转行寄高徵君","f":"五言古诗","c":["宛转复宛转，日没还上天。","宛转复宛转，月破还再圆。","天道谅如此，人情当复然。","与君虽未遇，何用数芳年。","不见黄河水，朝朝入东海。","东海有时枯，思君镇相待。"]},{"t":"相逢行","f":"五言绝句","c":["使君驰五马，贱妾在桑阴。","纵有黄金饼，何曾换妾心。"]},{"t":"长歌行","f":"五言律诗","c":["长歌如茧丝，缫之不能断。","丝断尚可续，歌长安可短。","短歌续长歌，歌长可奈何。","愿学青松树，千年附女萝。"]},{"t":"艳歌行","f":"古风","c":["堂前燕，尾差差，远行兄弟不如归。","一朝流宕在他县，故衣未补新衣绽。","主妇敬爱客，为补故衣裳。","夫婿入门来，斜昐情内伤。","请卿勿斜盼，门有池水清泱泱。","水中白石郎自见，妾心如石不可转。"]},{"t":"怨歌行效庾信体","f":"古风","c":["白白机头素丝，制作吴宫舞衣。","纤罗不受尘污，细縠常避风吹。","馆娃夜深月色，长洲春老花枝。","秋风树头相待，随例承恩几时。"]},{"t":"长门怨","f":"五言绝句","c":["燕体徒自轻，蛾眉易生妒。","妾有千黄金，不买长门赋。"]},{"t":"玉阶怨","f":"五言绝句","c":["露下瑶阶冷，流萤湿不飞。","长门今夜月，特地上秋衣。"]},{"t":"秋闺怨","f":"七言绝句","c":["郎作征车妾作轮，关山远近得随君。","自从别去秋容减，络臂真珠小几分。"]},{"t":"金井怨","f":"五言绝句","c":["露下青桐叶，滴滴银床里。","妾泪不曾乾，多于井中水。"]},{"t":"春怨","f":"七言绝句","c":["昨夜春寒冷如水，梦入关山数千里。","萧郎近报在凉州，一寸心驰边上头。"]},{"t":"独处愁","f":"五言绝句","c":["脉脉背孤镫，迢迢数长漏。","下阶不见人，空帷月如昼。"]},{"t":"白头吟二首 其一","f":"五言古诗","c":["双鱼生水中，朝暮不相离。","鸳鸯在河浒，同出复同归。","茂陵多姝子，新花非故枝。","请看膝上琴，是妾手中丝。","琴心有时改，妾心终不移。"]},{"t":"白头吟二首 其二","f":"五言古诗","c":["妾乘油壁车，郎骑青骢马。","愿作双车轮，随郎马蹄下。","成都不可住，郎题桥上柱。","临邛道上花，是妾当垆处。","门前沟中水，日夕东西流。","上有双鸳鸯，交颈同白头。"]},{"t":"陇水吟","f":"古风","c":["陇头水，鸣呜咽。","朝洗秦人骨，暮流汉人血。","秦骨化黄土，汉血归黄泉。","水流如人声，夜哭长城边。"]},{"t":"辘轳吟","f":"五言绝句","c":["一转一回肠，再转肠应断。","不愁井水深，只恐郎恩短。"]},{"t":"百舌吟","f":"古风","c":["众鸟皆一舌，尔鸟百舌声关关，青春白日鸣花间。","绿窗佳人怨离别，脉脉閒愁向谁说。","东家鹦鹉锁金笼，让尔百舌当春风。"]},{"t":"络纬吟二首 其一","f":"五言律诗","c":["唧唧始临楹，袅袅复移树。","露叶惊虚织，风条劳暗度。","盈盈窗间女，皎皎机中素。","姑寒未得衣，先催了官赋。"]},{"t":"络纬吟二首 其二","f":"古风","c":["唧唧复唧唧，络纬啼东壁。","如何终夜鸣，辛苦劳虚织。","贫家素丝未了官，堂上老姑衣正寒。","嗟尔年年催懒妇，露绩风缫竟何补。","愿妾长勤姑有衣，买丝纳官先上机。"]},{"t":"秋夜吟二首 其一","f":"七言律诗","c":["玉盘堕地天如水，露重流萤飞不起。","头白老乌城上啼，七星斜挂城楼西。","行人起视河汉低，门前萧萧班马嘶。","十八卫娘羞画眉，笑指镫花占远归。"]},{"t":"秋夜吟二首 其二","f":"古风","c":["秋夜长，漏声缓，馆娃宫中愁日短。","十围画烛照吴台，花落半天红纂纂。","綵云凝歌吹不断，蹋月双回小龙管。","鸦啼金井东方明，宝鸭烟笼绮疏煖。"]},{"t":"望月吟","f":"五言古诗","c":["明明三五月，二八还复缺。","他乡见月团，何如在家欢。","在家杯酒煖，在路衣裳寒。","泪随天河水，流向海东边。","海东有弱流，转首为桑田。","哀哀精卫鸟，冤苦相交煎。","含情诉明月，愿月长在天。","云来月暂晦，云去月依然。","瑶琴弹别鹤，会待知音传。"]},{"t":"花下吟赠友","f":"古风","c":["昨日桃花开，今朝李花落。","开落自有时，红颜不如昨。","手提青丝白玉壶，得钱何惜花下沽，今日有花明日无。"]},{"t":"贫女吟","f":"七言古诗","c":["妾年十五处洞房，自小何曾出中堂。","去岁秋田不收谷，今年春月无蚕桑。","长兄从军在远道，制衣常恐天寒早。","但得不离慈母傍，玉颜何惜春花老。","东邻少女花满头，日日歌舞倡家楼。","无端嫁作商人妇，却抱琵琶弹别愁。"]},{"t":"贫女叹","f":"古风","c":["妾年八九龄，始知男女别。","十三学女工，穿针向秋月。","十五绣得双鸳鸯，自小不离慈母傍。","有髻不簪金雀钗，有耳不悬明月珰。","朝朝画眉临古井，爱渠百尺波澜静。","水底桃花不见春，愁心乱若青丝绠。","东家女儿花满头，问妾不嫁心焉求。","鹦鹉愿依丹桂老，蟪蛄安识青松秋。","乾坤无情白日短，寂寞空闺绿苔满。","何当约取许飞琼，月明夜夜吹琼琯。"]},{"t":"越女叹","f":"七言古诗","c":["越王城头箭如雨，妾是溪边浣纱女。","虏妾军中两见春，好花开谢春无主。","将军重色不重人，贱妾如花岂爱身。","妾岂不知身可惜，落叶随风归不得。","妾岂不知节可全，白璧一碎何时完。","妾今但有双泪血，流向曹娥江上月。"]},{"t":"巴陵女子辞","f":"古风","c":["青枫岭头月，照见巴陵女儿血。","血书石上痕不消，祠前古木风萧萧。"]},{"t":"木兰辞","f":"古风","c":["纂纂墙下枣，人生不如在家好。","木兰夜织流黄机，窗间络纬啼复啼。","平明军帖疾如羽，阿爷无男止生女。","木兰下机换戎装，灯前不洒泪千行。","髻捐金雀钗，耳脱明珠珰。","左持白羽箭，右挽青丝缰。","一朝姓字上军籍，军中不知是女郎。","祁连山前秋草白，马上单于吹筚篥。","霜花如钱风格格，万里黄云度沙碛。","木兰在边十二年，论功还谒九重天。","九重敕赐尚书诰，木兰感恩不敢言。","乞身朝出金门去，还家犹记庭前树。","入门先解战时衣，明朝复上流黄机。","木兰忠孝有如此，世上男儿安得知。","雄雉声角角，雌雉嘴啄啄。","两雉上天飞，谁能辨我是雄雌。"]},{"t":"平戎辞","f":"七言绝句","c":["旌旗捲尽渡黄河，春满皇州雨露多。","直过李陵台北畔，番人皆唱汉铙歌。"]},{"t":"望春辞","f":"七言绝句","c":["起登高阁望春来，浅白深红次第开。","凭仗东风须耐久，莫教容易堕尘埃。"]},{"t":"捉搦辞","f":"古风","c":["华阴山头井水深，女儿照影不照心。","影可照，心莫宣，欲知妾心井底天。"]},{"t":"白苧辞","f":"七言律诗","c":["馆娃宫中春日长，新裁白苧白如霜。","纤尘不动响屧廊，美人起舞双鸾翔。","芙蓉水殿夜生凉，飘飖回雪纷满堂。","鸡人唱筹宫漏浅，乌啼金井桐阴转。"]},{"t":"繫马辞","f":"五言绝句","c":["翩翩白鼻騧，繫在门前树。","莫学杨白花，随风渡江去。"]},{"t":"白鹭辞","f":"楚辞体","c":["白鹭白且鲜，羽翼何翩翩。","朝飞枫叶雨，暮宿芦花烟。","一双潜鳞在密藻，安知照影苔矶边。","嗟尔鹭兮，外洁其色，内娠厥凶。","胡不翔远，海搏高风。","尺泽之鱼不足充尔腹，慎勿见羁虞网中。"]},{"t":"古谣 其一","f":"七言绝句","c":["一东一西天上星，一聚一散水中萍。","一来一去道傍人，一颠一倒花下巾。"]},{"t":"古谣 其二","f":"七言绝句","c":["一东一西参与商，一聚一散鸳与鸯。","一来一去马上郎，一颠一倒九回肠。"]},{"t":"天上谣","f":"七言古诗","c":["碧云团盖凝瑶光，龙汉五气浮苍苍。","绛宫参差十二级，鹤背高寒露华湿。","白榆历历东井傍，帝子夜织天文章。","河西牵牛不服箱，灵鹊影断秋无梁。","一水盈盈河汉长，白河云片龙鳞光。","六符夜明七斗芒，天门无阶不可度。","梦蹋玉虹朝紫皇，三更露落黄姑渚。","鸾背吹笙载秦女，东方神人呼赤龙，彷佛觚棱绛霞曙。"]},{"t":"天上谣","f":"七言律诗","c":["梦飞八翼登天门，紫霞红雾通朝暾。","星河夜寒银浪白，河东拾得支机石。","绛节朝回贯月槎，琼楼缥缈太清家。","虞廷九奏钧天曲，凤池波煖鹓雏浴。"]},{"t":"白云谣","f":"七言律诗","c":["白云英英在昆丘，人间白日如水流。","穆王八骏去不返，碧桃花落三千秋。","茂陵刘郎不知死，阿母曾分七桃子。","露华夜半泣铜仙，白云英英空在天。"]},{"t":"女娲补天谣二首 其一","f":"古风","c":["不周山崩天柱折，帝遣娲娥补天裂。","穹然一盖青团团，东南天漏补不完。","徒令杞国忧，日夜摧心肝。","呜呼，世无仲山甫，衮职之阙谁为补。"]},{"t":"女娲补天谣二首 其二","f":"古风","c":["天冥冥，地冥冥，娲娥锻鍊天地精。","手抟五色云，上补青天青。","青天青如石，天柱不倾天漏塞。","黄道星辰明历历，于万斯年建皇极。"]},{"t":"城中谣","f":"五言绝句","c":["螺髻高一尺，蛾眉广半额。","王言出如丝，涣汗收不得。"]},{"t":"筑堤谣","f":"五言古诗","c":["朝凿西山石，暮填东海水。","西山石可尽，海水浩无底。","水犀莫射潮，祖龙莫驱石。","海水尚可填，人心填不得。","哀哀精卫鸟，东飞复西飞。","填得海波浅，愁杀弄潮儿。"]},{"t":"甘棠谣","f":"楚辞体","c":["甘棠堤上水平溪，野人掘河新筑堤。","春风杏花三十里，长城道边闻马嘶。","使君考绩朝天去，沙堤惟见棠梨树。","儿童骑竹待公还，父老攀辕愿公住。","公今到京勿久留，骢马重来堤上头。","盐官户口三十万，寒则思衣饥则饭。","我今试作甘棠歌，父兮母兮可奈何。"]},{"t":"老父谣送南昌康侯考绩如京师","f":"古风","c":["我行南昌道，相逢白头老。","白头甘老南昌村，一生不识府县门。","去年卖剑买黄犊，今年纳租租易足。","白头种柳县门前，愿留康侯住数年。","侯今报政金门下，待侯重来繫骢马。"]},{"t":"田妇谣","f":"古风","c":["大妇采凫茨，中妇汲湖水。","少妇晨烹双鲤鱼，日上阿婆犹未起。","长兄筑城行不归，西到钱唐百馀里。","妾家种田三十春，输租不劳官吏瞋。","去年输官曾卖屋，今年输官应卖身。","昨日使君骑白马，过妾门前楸树下。","出门长跪谢使君，喜得今年徵敛罢。","生儿不愿太官羊，愿妾身安婆寿长。"]},{"t":"禳田","f":"古风","c":["坎坎鼓，祀田祖。","新酒在盂豚在簠，阿翁呼孙儿馌妇。","拜跪祈神降田所，愿神再三听祝语。","五日一风十日雨，穰穰满家多黍稌。","往来野田无雀鼠，出入道路无豺虎。","丁男在家应门户，先祈一半输官府。","神今有食农有土，常年力作甘辛苦。","春秋报神神莫负。"]},{"t":"伤田家","f":"七言古诗","c":["低田水深愁没稻，高陇地乾多稗草。","地势由来苦不平，农家辛苦何时了。","低田车水出下塘，高陇翻江朝夕忙。","秋来雨多禾耳黑，县吏索租催上仓。","东家借米依程限，剜却心头医得眼。","宁教借米倍还人，莫遣打门官吏瞋。"]},{"t":"张京兆","f":"七言绝句","c":["摇摇珂佩堤上归，朝回无事但画眉。","莺啼落花昼不飞，美人照镜愁春闺。"]},{"t":"卓文君","f":"古风","c":["郎乘车，妾御马。","东郭门前绿杨下。","郎乘马，妾御车，长安道边花满株。","马翩翩，车轧轧，二月上林花正发。"]},{"t":"杞良妻","f":"五言律诗","c":["一哭长城裂，再哭长城崩。","长城窟中水，夜夜闻啼声。","哀哀双泪血，洒向城上月。","长城若不倾，何由见夫骨。"]},{"t":"自君之出矣","f":"五言古诗","c":["自君之出矣，我琴不曾弹。","弦中哀与乐，只在转指间。","自君之出矣，蛾眉向谁画。","思君如明镜，挂在东窗下。","自君之出矣，夜夜卜灯花。","思君如车轮，何时碾到家。","自君之出矣，一望一回头。","思君如辘轳，展转何时休。"]},{"t":"公无渡河","f":"古风","c":["公无渡河，河流如雪山，出门滔天行路难。","公不听妾语，被发徉狂向何许。","公今渡河妾无主，妾弹箜篌泪如雨。","公无渡河，水有鼋鼍。","公今欲渡，妾当奈何。","公无渡河，水有蛟龙。","公今欲渡，妾安所从。","陆则有车，水则有舟。","公今溺流，妾弹箜篌。"]},{"t":"妾安所居二首 其一","f":"五言古诗","c":["贱妾安所居，所居在中堂。","女子不出门，肯离慈母傍。","十三学织素，绣得金鸳鸯。","十五嫁夫婿，佩以双明珰。","一朝复一朝，芙蓉照秋镜。","自倚颜如花，不识郎心性。","嫁鸡逐鸡飞，郎情与妾违。","愿为松柏树，长附女萝衣。"]},{"t":"妾安所居二首 其二","f":"五言古诗","c":["贱妾安所居，所居在空闺。","女子不出门，颜色无人知。","一朝嫁夫婿，未几生别离。","流水逝不返，浮云无定姿。","妾居非无所，妾心良独苦。","愿如松上萝，不离树根土。"]},{"t":"妾薄命","f":"古风","c":["妾薄命，何足嗟。","妾愿如墙下草，不愿学风中花。","风花漂泊无定所，墙下草生长在家。"]},{"t":"铜雀妓二首 其一","f":"五言律诗","c":["高高铜雀台，望望西陵墓。","翠辇不归来，空帏愁日暮。","花落不返柯，水流无回波。","月初与十五，歌舞奈君何。"]},{"t":"铜雀妓二首 其二","f":"五言绝句","c":["高台悲风生，望望西陵道。","昨日宫中花，今朝墓前草。"]},{"t":"小垂手","f":"五言律诗","c":["朗月生瑶海，华星度绛河。","美人小垂手，广袖舞傞傞。","歌阑明烛短，舞罢落花多。","平旦临鸾镜，脩眉抹翠蛾。"]},{"t":"沐浴子","f":"五言绝句","c":["沐发恶蒙尘，振衣贵自洁。","何以清我心，长空有明月。"]},{"t":"望夫石","f":"七言绝句","c":["妾心化石石不转，妾身化石石不移。","身心与石若可转，千里万里夫当归。"]},{"t":"望乡台","f":"五言绝句","c":["一登还一望，一望复惆怅。","乡关望不见，泪落荒台上。"]},{"t":"长安道二首 其一","f":"古风","c":["长安道，长安道上多芳草。","一株杨柳驿门前，朝迎官马暮迎船。","来船去马无閒日，人笑人歌年复年。"]},{"t":"长安道二首 其二","f":"古风","c":["长安道，南北东西尘浩浩。","车轮朝碾长安花，马蹄暮蹋长安草。","黄金白璧如丘山，买官未得不肯还。","不及终军年最少，弃繻生出玉门关。"]},{"t":"上留田","f":"古风","c":["上留田，上有白日与青天。","人言弟死兄不?，他人野祭孤坟前。","一雁入缯缴，群雁鸣声哀。","如何骨肉亲，弃之委蒿莱。","淮南徒闻歌尺布，田家无复栽荆树。","上留田，良可怜。"]},{"t":"巫山高","f":"古风","c":["巫山高，青入天。","丹崖翠谷相钩连，中有玉妃凌紫烟。","凌紫烟，过楚宫，药房蕙幄春融融。","琼台银阙与天通，朝云暮雨无终穷。"]},{"t":"登高丘望远海","f":"古风","c":["登高丘，望远海。","昆崙桃花千岁红，阿母蛾眉青不改。","金鳌戴出三蓬莱，徐家楼船安在哉。","鲸涛无梁不可渡，坐见浅浅浮黄埃。"]},{"t":"关山月二首 其一","f":"古风","c":["关山月，昨夜团圆今夜缺。","他乡月与故乡同，何苦征夫久离别。","有客南来报捷音，为说良人戍桂林。","若使仙家能缩地，便须一刻比千金。"]},{"t":"关山月二首 其二","f":"古风","c":["明明天上月，照妾绮窗间。","梦随明月去，不省在关山。","关山月若知人意，送妾良人及早还。"]},{"t":"薤上露","f":"古风","c":["薤上露，朝日晞，昨日相见今日违。","力拔山，气如虎。","朝日晞，薤上露。"]},{"t":"见新月","f":"五言绝句","c":["下阶拜新月，比妾镜中眉。","郎在天涯见，莫忘初画时。"]},{"t":"上山采蘼芜","f":"五言律诗","c":["上山采蘼芜，本是王孙草。","王孙去不归，妾颜为谁好。","磨砖作明镜，照妾不见容。","年年湘水上，洒泪向春风。"]},{"t":"江南可采莲","f":"五言律诗","c":["江南可采莲，中有木兰船。","妾愁莲菂苦，郎爱露珠圆。","珠圆不长好，菂苦向谁道。","愿为泥中藕，洁身恒自保。"]},{"t":"折杨柳","f":"五言绝句","c":["一折一断肠，再折再回首。","平生故人泪，并落尊中酒。"]},{"t":"折杨柳送人之京","f":"五言古诗","c":["江头折杨柳，一枝赠一人。","去年枝欲尽，今年枝又新。","折柳莫折短，短条容易断。","如何离别情，苦被春风管。","折柳当折长，长条为马鞭。","上林春色好，相约凤池边。"]},{"t":"双桐生","f":"五言绝句","c":["双桐生古井，井上桐花落。","妾心如辘轳，繫在青丝索。"]},{"t":"芳树","f":"五言律诗","c":["青青道傍树，飞花委道傍。","不恋道傍土，一夕随风翔。","高飞上青天，低飞入流水。","花性自飘扬，孰谓因风起。"]},{"t":"东海有珊瑚","f":"古风","c":["东海有珊瑚，乃在龙伯宫。","托根蓬莱石，丹霞绚晴虹。","铁网求之无底谷，一朝置在黄金屋。","石家富儿不识珍，如意一击同飞尘。","岂如阆苑蟠桃树，一花一实三千春。"]},{"t":"秋夜长","f":"古风","c":["秋夜长，秋月光，月色照见罗衣裳。","美人盈盈立秋霜，琼楼玉宇遥相望。","明河迢迢鹊无梁，天高海阔思茫茫。","思茫茫，秋夜长。"]},{"t":"拟一日复一日","f":"五言律诗","c":["一日复一日，一朝复一朝。","欲识去来心，钱唐江上潮。","潮去不待送，潮来不待招。","潮来复潮去，使我心摇摇。"]},{"t":"拟一日白一发","f":"五言律诗","c":["一日白一发，况在九年间。","请持蟠龙镜，照子冰雪颜。","发白何足惜，故人难再得。","有使即寄书，无使长相忆。"]},{"t":"久别离","f":"古风","c":["近别三日尚思家，久别万里令人嗟。","他乡春色岂不好，那如故园桃杏花。","故园桃杏去时种，花落花开谁与共。","桃杏今年已过墙，良人何事不思乡。","久别离，愁断肠。"]},{"t":"远别离","f":"古风","c":["远别离，天有参商之二星。","东西相隔数万里，中有一带天河横。","天河水流直到海，织女牵牛两相待。","早知离别如参商，不用灵鹊为河梁。","宁为参商不相识，庶免郁郁愁中肠。","河可填，海可塞，别离之恨无终极。"]},{"t":"远如期二首 其一","f":"五言律诗","c":["去时愁远别，别久竟忘归。","五见门前树，秋风落叶飞。","落叶萦愁思，纷纷若乱丝。","仙家能缩地，莫使阻归期。"]},{"t":"远如期二首 其二","f":"五言绝句","c":["去时期一载，不道又三秋。","待得郎回日，松花满陇头。"]},{"t":"远将归二首 其一","f":"古风","c":["一日白一发，一年三百茎。","在家梳头霜满镜，何况远归千里程。","去时道远归渐近，人生谁不恋乡井。","昨夜青灯寒结花，远人明日当还家。"]},{"t":"远将归二首 其二","f":"五言绝句","c":["朝闻灵鹊语，夕见青灯花。","空闺占吉梦，远客将还家。"]},{"t":"行路难","f":"古风","c":["出门登山无太行，出门涉水无瞿唐。","太行羊肠九折坂，谁道车轮去不返。","瞿唐虎须千丈渊，谁道此中能覆船。","惟有人心不可测，当面波澜与荆棘。","我欲剪荆棘、平波澜，出门莫歌行路难。"]},{"t":"车遥遥二首 其一","f":"七言古诗","c":["鸦啼金井东方白，起送关山远行客。","前车轧轧后车催，莫问东西与南北。","天上日月无停轮，有泪不洒车中尘。","黄尘如海车如水，出门遥遥千万里。","相思日夜听车声，归时还待鸦啼起。"]},{"t":"车遥遥二首 其二","f":"古风","c":["车遥遥，上青天，门前路，直如弦。","茫茫名利途，谁斲车轮圆。","安得两轮生四角，朝朝相见心即乐。"]},{"t":"车遥遥送人之京","f":"古风","c":["车遥遥，云路长。","车轮不生角，马蹄安得方。","英英冠玉车中郎，欲行不行官道傍。","我辕西行无鸟道，我辙北上无羊肠。","平明起拂车上霜，金鸡叫日升榑桑。","避尘有巾雨有盖，无疾无驱镇相待。"]},{"t":"雨霖铃","f":"古风","c":["雨霖铃，铃声杂雨随车行。","鸟道西来与天平，不闻华清环佩声。","白发梨园吹觱篥，望京楼上空相忆。","惟有张徽识此情，御前曾教雨霖铃。"]},{"t":"秦罗敷","f":"五言古诗","c":["昔有邯郸女，艳色世无如。","手提青丝笼，采桑城南隅。","头上金雀钗，耳傍明月珠。","素手挽柔条，风吹绣罗襦。","使君驰五马，冠盖丽且都。","桑间问彼姝，云是秦罗敷。","裴回日将夕，命妾载后车。","长跪谢使君，妾有堂上姑。","剖竹节乃直，裂松心不枯。","使君善自爱，妾志终弗渝。"]},{"t":"五杂组","f":"古风","c":["五杂组，故园花。","去复还，返哺鸦。","不获已，远思家。","五杂组，身上衣。","去复还，梭上机。","不获已，久思归。","五杂组，园中花。","去复还，道上车。","不得已，久思家。","五杂组，金缕罗。","往复还，机上梭。","不得已，阻关河。","五杂组，斑斓衣。","往复还，乌哺儿。","不得已，久思归。"]},{"t":"染丝上春机","f":"七言律诗","c":["吴蚕八茧缫长丝，玉纤染云上春机。","大姑爱织榴花色，小姑爱织梨花白。","小姑回头语大姑，梨花洁白不受污。","大姑榴花故自好，以色娱人岂长保。"]},{"t":"两头纤纤 其一","f":"七言绝句","c":["两头纤纤梭上机，半白半黑枰上棋。","腷腷膊膊啄木儿，磊磊落落曙星稀。"]},{"t":"两头纤纤 其二","f":"七言绝句","c":["两头纤纤月初生，半白半黑天未明。","腷腷膊膊断肠声，磊磊落落东方星。"]},{"t":"莫洗红","f":"古风","c":["莫洗红，洗红红渐少。","郎爱新红鲜，妾怜旧红好。","少妇回看机上丝，笑言还胜未红时。"]},{"t":"将进酒三首 其一","f":"古风","c":["弹鹍弦，调凤琯，玉醅滟滟流霞煖。","东方风来吹落花，随风漂泊天之涯。","去年花谢今年发，今朝人醉明朝别。","明朝别去可奈何，且尽花前金叵罗。"]},{"t":"将进酒三首 其二","f":"古风","c":["四座且勿喧，听我歌长谣。","百年三万六千夜，百年三万六千朝。","三万六千朝与夜，几度花开与花谢。","杯行到手请勿辞，金尽床头莫论价。","不见洛阳城里人，化为北邙山下尘。","今朝共饮碧玉醑，明日更漉乌纱巾。"]},{"t":"将进酒三首 其三","f":"古风","c":["将进酒，酒进君莫停。","我有长歌君试听。","地有酒泉，天有酒星。","不持寸铁，直破愁城。","将进酒，酒进君莫止。","我有长歌君侧耳。","白日西飞，沧波东逝。","古来达人，皆止于此。","将进酒，请君听我歌。","我欲长绳繫白日，精卫填沧波。","沧波不可填，白日不可繫，进酒当君莫辞醉。"]},{"t":"辞欢伯","f":"楚辞体","c":["彼欢伯兮何仇。","吾将汝兮解忧。","汝何为兮我尤。","眵吾之睫兮翳吾之眸。","我思汝由。","汝莫我留。","我不汝谋。","我目其瘳。"]},{"t":"提葫芦","f":"古风","c":["碧酒白玉壶，金钱花下沽。","无情花间鸟，更唤提葫芦。","提壶劝人但饮酒，百岁称觞为君寿。"]},{"t":"悲铜驼","f":"古风","c":["悲铜驼，洛阳桃李春风多。","千乘万骑陌上过，流光衮衮东逝波。","铜盘露冷铜仙去，忍见铜驼埋棘处。"]},{"t":"野田雀","f":"古风","c":["野田雀，鸣啾啾。","啄我黍，何时休。","我黍半输官，我黍半养家。","尔雀群飞无网罗，我黍日减雀日多。","野田雀，奈尔何。"]},{"t":"艾如张二首 其一","f":"七言律诗","c":["野田黄雀朝暮飞，碧云茫茫艾叶肥。","少年张罗雀不知，误触毛羽鸣声悲。","凤凰翱翔千仞冈，五色文采鸣朝阳。","托巢蓬莱白玉树，此生安识艾如张。"]},{"t":"艾如张二首 其二","f":"古风","c":["东山有凤，西山有麟。","张罗于野，其心匪仁。","天池之鹏，扶摇直上。","翼如垂云，安畏尔网。"]},{"t":"婆饼焦","f":"古风","c":["婆饼焦，阿婆有饼教妾烧。","妾烧饼焦婆不食，上堂见婆无颜色。","不学姑恶死怨姑，深林日夕鸣相呼。","但愿麦黄婆有饼，年年唤婆欲婆醒。"]},{"t":"姑恶词","f":"五言绝句","c":["姑恶叫青春，声声恼杀人。","啼时休近户，妾恐老姑瞋。"]},{"t":"雪中乌","f":"古风","c":["雪中乌，雪中乌，城头积雪白模糊。","天寒失其巢，哑哑无宇居。","巢中有雏尾毕逋，雏不见母母忆雏。","雪中乌，孤复孤。"]},{"t":"琼州乌","f":"古风","c":["琼州乌，夜夜夜啼琼树枝，一朝雄死遗孤雌。","为母在秦川，日望天南啼复啼。","如何母与子，同天不同栖。","雏今海南去，勿恋琼州树，秦川故巢不相依。","母挟子，早来归，东海燕燕待子飞。"]},{"t":"乌生八九子","f":"古风","c":["乌生八九子，朝栖城上树，暮饮城下水。","母昔翩翩引子飞，子今啄啄哺母饥。","子多不愁哺母食，夜夜来巢城树枝。"]},{"t":"乌夜啼","f":"古风","c":["乌夜啼，城上头。","城中少妇弹箜篌。","起闻乌啼生远愁。","乌不能言解乌意，愿乌啼时赦书至。"]},{"t":"雉朝飞","f":"楚辞体","c":["雉朝飞，鸣复止。","饥食野田粟，渴饮野田水。","绣颈斑斑相逐飞，何人感之犊牧子。","圣人在位歌关雎，吁嗟雉兮今何如。"]},{"t":"胡蝶舞","f":"七言律诗","c":["东家西家胡蝶飞，东家花落胡蝶稀。","西家明年花又放，胡蝶还从花下归。","东家还向西家道，眼底青春为谁好。","人生行乐须及时，莫遣花前胡蝶少。"]},{"t":"孤雁翔送马山人归颍川","f":"古风","c":["孤雁翔，颍之阳，秦淮十月天雨霜。","人生岂无兄与弟，独夜哀鸣楚江水。","颍之阳，孤雁翔，尔何为乎不作行。","明年寄书到东海，日日沙头镇相待。"]},{"t":"鹊失巢","f":"古风","c":["双鹊结巢庭树枝，雌雄饮啄长相依。","东方风来知太岁，树高巢重身多累。","引雏树问高下飞，长见鸣鸠好羽仪。","岂意尔鸠鸣聒聒，白书相期即相夺。","鹊失巢，良可悲。","高冈凤凰知不知。"]},{"t":"鸠逐妇二首 其一","f":"古风","c":["朝呼晴，暮呼雨。","晴即相求雨相离，相求何喜离何怒。","离合如关喜怒中，青天长愿日轮红。","不见鸳鸯河水上，一生交颈无惆怅。"]},{"t":"鸠逐妇二首 其二","f":"七言古诗","c":["屋头桑子红纂纂，一双饮啄桑阴煖。","绣颈斑斑相颉颃，此时不道恩情短。","春云淡荡生朝阴，尔雄聒聒啼高林。","岂意相呼即相逐，可怜同宿不同心。","嗟尔孤雌向何处，裴回□忍他枝去。","早识长情不见疑，托巢栖傍朝阳树。","桑叶阴阴日当午，桑下声声鸠逐妇。","喜即相呼怒即离，轻薄恩情付晴雨。","恨尔不见双鸳鸯，一双头白在回塘。"]},{"t":"衔泥燕","f":"古风","c":["衔泥燕，尾毵毵。","昨日衔泥在城北，今日衔泥在城南。","城南华屋故巢改，城北故巢无复在。","裴回不敢离旧栖，主翁一别何时归。"]},{"t":"君马黄","f":"古风","c":["君马黄，臣马白，君马在德臣马力。","华山之阳春草长，臣今矍铄马力强。","不愿相遇王良与伯乐，但愿老归田子方。"]},{"t":"题猫捕雀图","f":"楚辞体","c":["强之食，弱之肉，飞者安知行者逐。","纷纷眼底人猫多，雀兮雀兮可奈何。"]},{"t":"古乐府","f":"五言律诗","c":["妾有青铜镜，置君白玉台。","无盐与西子，都入此中来。","郎采芙蓉花，侬采芙蓉叶。","叶绿比郎衣，花红似侬颊。"]},{"t":"古意二首 其一","f":"五言古诗","c":["皎皎蟠龙镜，娟娟秋月晖。","粲粲东窗女，盈盈桃李姿。","婉婉惜芳年，脉脉处香闺。","昔如璞中玉，今如琴上丝。","玉质恒自爱，琴心终不移。"]},{"t":"古意二首 其二","f":"五言律诗","c":["郎如川上水，妾似水中天。","流水何曾定，青天不离川。","妾手不停织，郎车不停轮。","长怜机上丝，长寄车中人。"]},{"t":"拟唐人十二月乐章并闰月 其一 正月","f":"七言律诗","c":["青阳荡荡天门开，太乙神君天上回。","翠旗青仗出蓬莱，金花叠鼓鸣春雷。","黄河冰裂鱼龙喜，煖绿鳞鳞凤池水。","曲尘吹黄上宫柳，明日朝天称万寿。"]},{"t":"拟唐人十二月乐章并闰月 其二 二月","f":"古风","c":["日照曲江津，千叶宫桃红笑人。","梨园羯鼓趣花神，綵丝五色绣青春。","金堤软碧草如茵，美人蹋歌停素云，蛱蝶飞上榴花裙。","翠袖扶春海棠醉，绛蜡通宵照花睡。"]},{"t":"拟唐人十二月乐章并闰月 其三 三月","f":"七言古诗","c":["洛阳牡丹赪玉盘，宫城落絮春漫漫。","千轮万毂昼驰道，一日看花心未了。","黄金买春恐春老，锦帐围天觉天小。","撞钟槌鼓白日晏，汉宫传烛千枝烂。","南园草绿送春归，花落莺啼綵云散。"]},{"t":"拟唐人十二月乐章并闰月 其四 四月","f":"七言古诗","c":["稚子斑斑穿碧草，吴蚕缫雪车声早。","内园中使进樱桃，单罗玉色试宫袍。","碧殿南薰生五弦，高槐夹道团晴烟，金沟荷叶绿田田。"]},{"t":"拟唐人十二月乐章并闰月 其五 五月","f":"五言律诗","c":["明月裁团扇，榴花照舞衣。","吴娃木兰楫，日暮采莲归。","龙绡围水榭，湘簟鱼波动。","郎餐九节蒲，妾食九子粽。"]},{"t":"拟唐人十二月乐章并闰月 其六 六月","f":"古风","c":["裁红绡，曳白苧，馆娃宫中催避暑。","夜凉水殿芙蓉开，矫如惊鸿下瑶台，隔花玉盌调冰来。"]},{"t":"拟唐人十二月乐章并闰月 其七 七月","f":"五言古诗","c":["碧落散金气，明河白浮浮。","鹊鸣知露重，萤过学星流。","纨扇朝辞宠，罗衾夜抱愁。","暑退长生殿，凉归乞巧楼。","月明吹玉琯，开户望牵牛。"]},{"t":"拟唐人十二月乐章并闰月 其八 八月","f":"五言律诗","c":["城头夜传柝，露脚月中飞。","羌笛卷叶吹，候雁向南归。","缸花泣红泪，染丝上寒机。","莎鸡且勿啼，妾制边人衣。"]},{"t":"拟唐人十二月乐章并闰月 其九 九月","f":"七言律诗","c":["桂影离离画阑曲，露重铜盘泣寒玉。","辘轳轧轧转金井，美人手怯青丝绠。","鲤鱼风高浪花白，湘浦芙蓉失颜色。","七星挂树长琅玕，玉阶罗袜生春寒。"]},{"t":"拟唐人十二月乐章并闰月 其十 十月","f":"七言古诗","c":["冰蟾蹋云乌夜啼，银汞洗空霜倒飞。","蜡花巧缀蜻蜓眼，铜龙无声停漏板。","白天冻合玉河乾，金井裁衣素手寒，北风吹梦度关山。"]},{"t":"拟唐人十二月乐章并闰月 其十一 十一月","f":"七言古诗","c":["绿毛倒挂梨花云，辟寒犀煖蕙帏春。","玉妃剪水空中堕，熏笼不断沈香火。","宫中五色添长线，旭日曈曈上瑶殿。"]},{"t":"拟唐人十二月乐章并闰月 其十二 十二月","f":"七言绝句","c":["匝地冻云飞不起，翡翠寒欺合欢被。","何人吹律待春阳，三百六旬今复始。"]},{"t":"拟唐人十二月乐章并闰月 其十三 闰月","f":"古风","c":["桃之都，三足乌，三年乌生三十雏。","东方烛龙夜回车，气朔推迁盈复虚。","缇室重吹凤凰琯，雌雄十二春声煖。"]},{"t":"垂虹亭晚泊","f":"五言律诗","c":["泊舟垂虹亭，水气秋冥冥。","泛滥露浮白，依微天倒青。","钟声临水度，渔唱隔林听。","赖得知心友，因倾双玉瓶。"]},{"t":"池上","f":"五言律诗","c":["池上坐来久，风荷杂雨声。","林虚容鸟度，水动见鱼行。","意惬理无忤，神閒苧亦清。","裴回不知晚，有待月华生。"]},{"t":"秋日喜雨","f":"五言律诗","c":["惊雷初动地，甘雨最知时。","石有交飞燕，田无再坼龟。","稻花齐覆水，荷叶乱翻池。","早赛鸡豚社，秋成信有期。"]},{"t":"秋后三日得雨","f":"五言律诗","c":["立秋三日后，好雨应时来。","岂但农心悦，频消旱魃灾。","风雷生白昼，河汉洗黄埃。","拟撰丰年颂，惭无冠世才。"]},{"t":"登大悲阁","f":"五言律诗","c":["日照绀园秋，登临阁上头。","云随飞鸟没，天入大江流。","华盖瞻双阁，金沙见十洲。","龙王宫里月，夜夜白莲浮。"]},{"t":"过扬子江","f":"五言律诗","c":["雨过大江秋，苍茫一叶舟。","乡心随去鸟，旅梦学眠鸥。","水与天同色，云兼月共流。","谁家歌楚调，令我不胜愁。"]},{"t":"出扬子江","f":"五言律诗","c":["出江风力便，买纸赛龙君。","篷响浑疑雨，帆高不碍云。","地维从古险，天堑此中分。","渐近金山寺，疏钟水上闻。"]},{"t":"春日东园即事","f":"五言律诗","c":["旭日上林扉，馀寒入苧衣。","傍阑移芍药，编竹引蔷薇。","野兴同谁领，閒身与世违。","多情双燕子，重觅故巢归。"]},{"t":"东园雨晴即事","f":"五言律诗","c":["兼旬积雨声，旭日弄初晴。","花上野禽语，竹间萱草生。","煮茶寻活火，临水濯烦缨。","门巷无车辙，陶然少俗情。"]},{"t":"移芍药","f":"五言律诗","c":["去冬移芍药，日日待花开。","屈指到三月，傍阑看几回。","露花滋茧栗，春色满池台。","不学魏家紫，儿孙无地栽。"]},{"t":"挽郭子振","f":"五言律诗","c":["阁泪强裁诗，临风咏白圭。","凭棺犹有仆，属纩竟无儿。","只道归全璧，安知梦一炊。","我来松树下，哭到月明时。"]},{"t":"挽曲江友人","f":"五言律诗","c":["罗刹江边赋，慈恩塔上名。","杏园春寂寞，槐国梦分明。","酒进杯留影，诗传画有声。","哲人今已矣，无复见升平。"]},{"t":"送百户徐叔之甘州","f":"五言律诗","c":["乌啼城上头，白发梦甘州。","自是劳行役，非关好远游。","边云随雁落，河水带冰流。","万里无烽燧，功归定远侯。"]},{"t":"送人归黄岩","f":"五言律诗","c":["黄山高徵士，白首解穷经。","里巷闻弦诵，儿童识姓名。","芸窗山气暝，竹簟水纹清。","更有佳孙子，芝田产玉英。"]},{"t":"送人还越","f":"五言律诗","c":["閒居多种竹，开径接羊求。","老去便孤啸，诗来遣百忧。","鹅群翻墨沼，兔颖涤冰瓯。","每有登临兴，凭阑望越州。"]},{"t":"题画","f":"五言律诗","c":["小雨落桐英，群峰出晚晴。","树藏茅屋小，溪涨野桥平。","童去因沽酒，船回不到城。","此中真可隐，亦足慰吾生。"]},{"t":"春思","f":"五言律诗","c":["脉脉动春思，临鸾懒画眉。","唤人閒斗草，分子共敲棋。","舞倦罗衫重，歌长玉漏迟。","纤腰如弱柳，浑不似当时。"]},{"t":"食新鲊","f":"五言律诗","c":["海鲚出银涛，长于金错刀。","未书裹鲊帖，先压真珠槽。","一笑出奇味，数杯惭老饕。","醉归诗有兴，坐剪烛花高。"]},{"t":"寄震龙门和尚 其一","f":"五言律诗","c":["最忆龙门老，高情似远公。","胸藏千亩竹，手植万株松。","林晚床留虎，溪凉钵引龙。","玄关须一扣，莫遣白云封。"]},{"t":"寄震龙门和尚 其二","f":"五言律诗","c":["安平池子上，不到十馀年。","石老三生梦，茶枯一味禅。","涧泉通屋下，山雨落尊前。","我亦除烦恼，还来了胜缘。"]},{"t":"寄震龙门和尚 其三","f":"五言律诗","c":["山临此地平，不改旧时青。","双塔云中见，孤钟雨外听。","苔深松有甲，笋长竹添丁。","料得无多事，观心即是经。"]},{"t":"送云季昭","f":"五言律诗","c":["夫子才名重，丹山出凤毛。","九年三闰月，千载一蟠桃。","阊阖青云近，蓬莱紫气高。","单罗秋水色，裁作上官袍。"]},{"t":"挽友人妻李氏","f":"五言律诗","c":["结缡从少艾，属纩在今朝。","宝月空鸾镜，银河断鹊桥。","湘灵安可吊，楚些若为招。","閒却黄金剪，谁缝白苧袍。"]},{"t":"送陈知县之建昌","f":"五言律诗","c":["三年登太学，一日宰南康。","白雁连淮远，青山入楚长。","灯前慈母线，花下故人觞。","傥有南来使，因风寄数行。"]},{"t":"秋夜怀友","f":"五言律诗","c":["朗月生瑶浦，流云度绛河。","微凉通海气，清籁落空歌。","过雁分明见，飞萤即渐多。","有怀人不至，孤影倚松萝。"]},{"t":"冬夜有怀","f":"五言律诗","c":["柴门掩晴雪，户外无俗驾。","悠悠怀故人，寂寂坐终夜。","冻云归远浦，朗月生虚榭。","古意寄冰弦，何由共清话。"]},{"t":"挽一臂和尚 其一","f":"五言律诗","c":["山顶白云层，重来不见僧。","人多收舍利，谁与续传灯。","谩说三番咒，徒闻最上乘。","裴回双树下，何处觅南能。"]},{"t":"挽一臂和尚 其二","f":"五言律诗","c":["幽栖二十年，足不到山前。","麈尾风生海，军持月浸泉。","字留怀素草，社散远公莲。","无复论三昧，唯应上五天。"]},{"t":"舟中怀友人 其一","f":"五言律诗","c":["白头人已老，同约不同游。","寒食他乡酒，春波各自舟。","见灯思越语，闻橹待吴讴。","安得须叟见，令人散百忧。"]},{"t":"舟中怀友人 其二","f":"五言律诗","c":["夜泊长江上，何人笑语同。","月依临浦树，云逐渡江风。","短发明灯下，浮生大梦中。","却怜河汉水，咫尺不相通。"]},{"t":"舟中","f":"五言律诗","c":["舟行一水间，同泊大江湾。","白见初生月，青怜已过山。","有家形老梦，无酒慰愁颜。","仰睹云霄上，冥鸿不可攀。"]},{"t":"过小姑","f":"五言律诗","c":["灵峰倚玄穹，古殿穗帷冷。","云霞冠阳冈，雷电蓄阴岭。","凭高鬼神会，直下鱼龙静。","王事有严程，无由登绝顶。"]},{"t":"美妾换马","f":"五言律诗","c":["掩泪整花钿，当阶卸锦鞯。","徒誇珠络臂，不及玉连钱。","一笑千金直，长鸣万里天。","明妃青冢草，遗恨寄婵娟。"]},{"t":"题张真人画","f":"五言律诗","c":["生绢才一幅，云是上清来。","过雨晴犹湿，归云晚不开。","神龙回洞府，老鹤识楼台。","拟著芒鞋去，跻攀紫翠堆。"]},{"t":"初夏","f":"五言律诗","c":["快雨知春尽，鸣禽觉夏初。","日高槐影直，风细竹声疏。","帘静惟留燕，池清足养鱼。","閒居无杂事，点检箧中书。"]},{"t":"送马公肃之颍川","f":"五言律诗","c":["读礼三年后，张帆十月初。","千金司马赋，八法右军书。","远道无来使，空山有故庐。","持竿东海上，只钓北来鱼。"]},{"t":"题永思堂","f":"五言律诗","c":["爱日情无已，终天志可哀。","每于堂上见，多是梦中来。","冰鲤空朝馔，寒乌静夜台。","十年馀手泽，不敢向人开。"]},{"t":"送崇德县簿之京","f":"五言律诗","c":["溪明秋水凉，百丈出回塘。","帆影冲南斗，钟声别上方。","三年传美誉，千里沐清光。","想见回舻日，青袍雨露香。"]},{"t":"春山烟雨","f":"五言律诗","c":["春雨不作泥，春林布谷啼。","山头烟羃树，溪上水平堤。","翳翳岩花重，萧萧涧竹低。","平明看野色，骑马过湖西。"]},{"t":"舟中积雨","f":"五言律诗","c":["一雨复一雨，渡江重渡江。","风雷自动荡，水石相冲撞。","月影忽堕地，雨声犹在窗。","閒愁千万斛，安得酒盈缸。"]},{"t":"舟次番湖风顺雨晴柬同舟李纪善","f":"五言律诗","c":["潮落大江开，春流碧似苔。","沙明分岛屿，山远出楼台。","白日千帆过，青天一鸟来。","同舟李供奉，真有济川才。"]},{"t":"题青山读书图","f":"五言律诗","c":["咫尺出林下，翛然一草亭。","云归天姥白，山落镜湖青。","月色当窗见，秋声隔树听。","柁楼如有约，来写换鹅经。"]},{"t":"城东获野鹿","f":"五言律诗","c":["城东四月交，野鹿走林坳。","本是归灵囿，何因出近郊。","生无青涧饮，死有白茅包。","猿鹤同惊怨，呦呦失故巢。"]},{"t":"五月一日千秋节","f":"五言古诗","c":["凤历纪初元，龙飞御九天。","贤王开大国，宗社镇长年。","东井回羲驭，南风入舜弦。","阶蓂晴散雨，宫树晓凝烟。","乐奏彤庭上，班齐紫殿前。","鸣珂穿柳过，清漏隔花传。","律应蕤宾节，星当翼轸躔。","菖蒲浮玉醴，葵萼照琼筵。","自愧龙钟老，叨陪雁序联。","愿言安社稷，馀庆福绵绵。"]},{"t":"送褚项民之京","f":"古风","c":["阊阖青天上，蓬莱紫气中。","六符随斗转，一水与天通。","子抱才华去，人称翰墨工。","按图真得骏，戏技匪雕虫。","?接河南远，群超冀北空。","壶分官酒碧，衣映苑花红。","岁月淹行李，江湖念转篷。","暂辞金马直，归拜白头翁。","禄养嗟何及，交情恨莫穷。","儿心徒耿耿，王事且匆匆。","解䌫潮初起，停杯曲未终。","秋声今夕共，月色异乡同。","伐木歌鸣鸟，挥弦送去鸿。","窗閒辟蠹草，池冷换鹅笼。","慎勿誇燕石，须令得楚弓。","诗成何限恨，吟遍木犀风。"]},{"t":"送云季昭","f":"五言古诗","c":["有美云夫子，河间好弟兄。","多才谙世事，一见遂交情。","奇论诸生服，雄谈四座惊。","夜吟催烛换，晨讲候钟鸣。","凿井思泉及，为山待篑成。","图探河马秘，书赞洛龟灵。","礼重春秋祀，名高月旦评。","历经三闰月，天转九周星。","远近皆知化，西南喜得朋。","广文延郑老，同舍识袁宏。","春郭花边酒，秋窗雨外镫。","字临怀素草，诗寄剡溪藤。","蹋月多寻友，看云或访僧。","襟期恒坦坦，履践必兢兢。","相见嗟何晚，先生自此升。","治安须贾谊，授业望阳城。","祖道歌初发，炎天暑尚蒸。","片帆悬碧落，斗酒醉金陵。","阿阁思巢凤，天池拟化鹏。","壮怀今若此，离思祗难胜。","昼漏趋青琐，秋河近玉绳。","榜看题后墨，壶出赐来冰。","太乙珠联纬，蓬莱翠作层。","河清还献颂，旭日在觚棱。"]},{"t":"患眼偶述","f":"五言古诗","c":["幽居气郁蒸，病眼偶相仍。","翳翳如迷雾，荧荧若乱星。","无愁眵满睫，不泣泪交膺。","晨起羞看日，宵眠怕见灯。","金篦那可刮，银海若为澄。","爽忆铜盘露，寒思玉井冰。","但令心似水，宁望酒如渑。","欢伯从今断，仙方信莫凭。","披襟从放浪，散发任鬅鬙。","白葛巾休裹，乌皮几暂凭。","坐须临水竹，行必倚山藤。","即遣三尸去，非关五色瞢。","宗之元自白，阮籍本来青。","才匪张司业，诗惭杜少陵。","挥毫聊自慰，持以谢良朋。"]},{"t":"拟呈无为真人二十韵","f":"五言古诗","c":["上界金为阙，蓬莱玉作城。","日行黄道正，星列泰阶平。","尧帝尊巢父，轩皇候广成。","真符传世久，公衮赐衣荣。","屡遣皇华使，遥迎碧落卿。","竹宫祠太乙，桂殿礼通明。","班出三台立，身先百辟行。","琅函宣蕊笈，琼醴进霞觥。","河应千年润，嵩呼万岁声。","飙车回绛节，霜匣秘苍精。","凫坠云中舄，鸾吹月下笙。","山林皆动色，猿鸟亦知名。","枸杞山篱晚，芙蓉野岸晴。","极知诗有思，谁谓道无情。","草圣超怀素，传家过伯英。","书签森戢戢，琴石立庚庚。","梵气开三景，玄风被八纮。","鸿猷资化育，鲸海望澄清。","曼倩偷桃者，安期采药生。","金丹如可赐，凡骨洒然轻。"]},{"t":"柬知县陈善方","f":"五言古诗","c":["有美东曹彦，科名四海传。","长身片玉立，高论大河悬。","慷慨千人俊，驱驰万里天。","贺兰西入夏，渤海北通燕。","剑拂边霜重，弓开垄月圆。","文章韬虎豹，羽翮铩鹰鹯。","太华云随袂，长城雪拥鞯。","黄河秋汨汨，黑水夜溅溅。","旅梦双胡蝶，乡心五杜鹃。","倦弹宾馆铗，饥齧汉臣毡。","寒谷空吹律，焦桐忽断弦。","泪乾慈母线，囊涩水衡钱。","遂感王门召，惟应国士怜。","所蒙稽古力，幸免枕戈眠。","讲殿陈韬略，经帷侍简编。","名从西域播，诗到外夷传。","天地重开辟，人材肯弃捐。","词林翔鸑鷟，学海起蜿蜒。","飞动关元气，涵濡及远边。","青云瞻象魏，紫气应龙泉。","士论争推择，王言益勉㫋。","龙香濡露颖，风藻湿云笺。","杕杜劳还役，蒲萄赐别筵。","玉关归定远，银汉送张骞。","君命不俟驾，祖生先著鞭。","我知清白吏，人迓孝廉船。","大药丹初就，盘根节愈坚。","郎星吴分野，宦辙汉山川。","兰秀仍藏谷，珠明必媚渊。","有家供滫瀡，无梦属櫜鞬。","潘县花无数，庄椿寿八千。","炙分黄雀美，鲙切白鱼鲜。","忠孝原如此，升沉合自然。","锦衣行白昼，采服称华年。","下榻怀徐孺，衔杯笑郑虔。","群黎劳抚字，多士荷陶甄。","暑雨清炎瘴，秋禾满大田。","红收鹦鹉粒，青爇鹧鸪烟。","自笑雷鸣缶，深惭雪满颠。","续貂吾岂敢，聊以致拳拳。"]},{"t":"上虞太守","f":"五言古诗","c":["有美金闺彦，才名海内多。","古称清白吏，今尚孝廉科。","日照黄金节，风鸣白玉珂。","弦歌传鲁颂，书法擅虞戈。","燕寝严兵卫，宾筵设礼罗。","清尊开北海，乌舫载东坡。","欲拜车尘下，其如鹤发何。","未随童子马，先辱右军鹅。","学比雷鸣缶，文惭凤掷梭。","愿公施化雨，留意育菁莪。"]},{"t":"云门乐","f":"五言古诗","c":["八风开橐籥，一气运鸿濛。","黄屋尊尧德，玄圭锡禹功。","干羽三苗格，车书万国同。","醴泉从地出，甘泽与天通。","电绕星枢北，春回寿域中。","云门齐奏曲，彤管纪时雍。"]},{"t":"明月篇","f":"五言古诗","c":["湛湛复盈盈，当秋彻夜清。","直疑天有堑，却讶水无声。","隐约箕边起，依微斗外横。","气浮华盖动，光映泰阶平。","东去遥通海，西流澹挂城。","拟乘莲一叶，万里溯空明。"]},{"t":"圣寿无疆词","f":"五言古诗","c":["至德乾坤大，重华日月光。","罗图今有兆，宝历永无疆。","瑞凤来丹穴，神芝散玉房。","九重春荡荡，万国海茫茫。","玄圃安期枣，瑶池阿母觞。","小臣歌盛世，何幸际明良。"]},{"t":"太平乐","f":"五言古诗","c":["玉帛来王会，山河拱帝京。","日行王道正，星列泰阶平。","人醉笙歌地，山围锦绣城。","宫花留舞燕，御柳著啼莺。","蛮獠全归化，羌胡已罢兵。","愿言封禅稿，虎拜颂河清。"]},{"t":"乐未央","f":"五言古诗","c":["天临丹凤阙，日上翠云裘。","社稷安如堵，君王百不忧。","䧿鸣宫掖曙，鸡唱禁城秋。","白玉装车轴，黄金络马头。","钧天聆广乐，丹扆俨垂旒。","此乐真无极，洪恩被九州。"]},{"t":"朝宗引","f":"五言古诗","c":["海郡同歌舞，神人共赞尧。","有天皆入贡，无地不来朝。","玉烛调元气，璇玑运斗杓。","六龙高扈驾，五凤夹吹箫。","瑞应清河颂，欢腾击壤谣。","翔南声教远，干羽格三苗。"]},{"t":"百兽舞","f":"五言古诗","c":["飞动关元气，音声感至和。","石当夔击拊，琴协舜赓歌。","海内文麟出，朝端振鹭多。","跄跄随列仗，肃肃动鸣珂。","玄圃生朱草，丹山产玉禾。","万方无一事，多士集銮坡。"]},{"t":"沐恩波","f":"五言古诗","c":["綵凤衔图日，金鸡放赦时。","恩波宽似海，天语出如丝。","雨露垂丹扆，风云会玉墀。","沾濡涵宇宙，涣汗被华夷。","金镜千秋录，瑶池万寿卮。","朝阳有灵鹊，长占上林枝。"]},{"t":"苍龙阙","f":"五言古诗","c":["鸿龙排绛阙，象魏辟金扉。","太乙昭黄道，勾陈直紫微。","蜿蜒扶日上，夭矫挟云飞。","望拜千官集，柔怀万国归。","春班随仗入，午漏隔花稀。","愿奏虞廷乐，长瞻黼黻衣。"]},{"t":"凤凰城","f":"五言古诗","c":["旭日丽金城，祥云护玉京。","九重双阙近，五采百花明。","缥缈瞻飞盖，葳蕤见折旌。","琼林生竹实，粉蝶坠桐英。","阿阁思重见，岐山待一鸣。","伶伦裁律吕，九奏协天声。"]},{"t":"何本先以天香茶见惠奉赋一首","f":"五言古诗","c":["金粟与金芽，都收陆羽家。","候雷春采叶，和月夜分花。","暖焙筠笼火，凉敲玉臼砂。","比圭方不琢，如璧瑩无瑕。","饼制龙团小，书封白绢斜。","奇芬疑入麝，古字学盘蛇。","清可轻肌骨，甘须沃齿牙。","唤醒蟾窟梦，直欲佩飞霞。"]},{"t":"题雪斋","f":"五言古诗","c":["簌簌复翛翛，寒斋坐寂寥。","瓦鸣知杂霰，林重想封条。","白向虚中见，声从静处消。","窗鸡惊曙早，厩马觉寒骄。","送酒当檐舞，随风入户飘。","埽门思往见，犹恐碎琼瑶。"]},{"t":"送僧游补陀","f":"五言古诗","c":["上人飞锡处，来去即虚空。","金沙随地涌，碧海与天通。","凭高惟鸟道，直下是龙宫。","瀑飞寒涧雨，松挟夜涛风。","度岭三山鹤，横天万里虹。","望中秋色远，浩气入无穷。"]},{"t":"题秋江别意图送人之还南雄","f":"五言古诗","c":["在山泉水清，出山泉水浑。","三山通震泽，九委派昆崙。","晚树依城郭，秋潮出海门。","张帆临月窟，系䌫倚云根。","大庾黄梅岭，长亭绿酒尊。","风尘嗟远道，雨露荷深恩。"]},{"t":"送判府万侯秩满如京","f":"五言古诗","c":["汉运兴黄祚，真人御赤龙。","将军雄武略，槐里建侯封。","奕世功何厚，诸孙秀所钟。","冥鸿翔大海，秋隼立高峰。","佐郡劳三载，承恩入九重。","临风何所赠，江上采芙蓉。"]},{"t":"赋僧言补陀","f":"五言古诗","c":["僧言海上来，曾上妙高台。","瑞相天浮月，潮音地殷雷。","沙如金粟布，山似碧莲开。","雨带龙鯹过，云随鹤影回。","幽探还得宝，径渡不须杯。","我有登临兴，南游识善财。"]},{"t":"送钟孟振服满之京","f":"五言古诗","c":["宣城禢太守，相见内门前。","为问洪都士，言登孝子船。","张帆当五月，读礼又三年。","梅子经旬雨，蓬莱咫尺天。","贤哉钟子耳，寂甚伯牙弦。","自叹初倾盖，那堪在别筵。","青云从此去，丹凤睹争先。","出饯惭衰老，题诗在烛边。"]},{"t":"呈卞博士","f":"五言古诗","c":["华顶仙人宅，瀛洲学士家。","乾坤钟间气，江海抱清华。","礼乐稽三代，文章擅五车。","泰山高莫极，沧海浩无涯。","夜视明光草，朝看上苑花。","九霞分内酝，八饼试春茶。","职掌丝纶重，恩承雨露嘉。","调高知寡和，言大实非誇。","自笑盐车骥，真如坎井蛙。","会须逢伯乐，振鬣向风沙。"]},{"t":"送岁贡生酆叔宏","f":"五言古诗","c":["圣代开文运，春官选俊英。","时当王正月，岁贡鲁诸生。","辛苦三冬学，扶摇万里程。","怀才期大用，努力在兹行。","阊阖彤云晓，蓬莱快雪晴。","掖梧多集凤，宫柳早闻莺。","好寄龙河信，须题雁塔名。","子今游太学，师必见阳城。","良璞无三献，洪钟待一鸣。","相知如见问，烦道别来情。"]},{"t":"题长江雪霁图","f":"五言古诗","c":["雪压秦山白，云横陇树黄。","二仪分上下，一水入沧茫。","势接龙门远，寒通鸟道长。","石犹含冻色，林未动晨光。","历历槎头钓，萧萧马上郎。","若非韩吏部，定是孟襄阳。","汉水鱼偏美，郫筒酒正香。","何当凌汗漫，万里共翱翔。"]},{"t":"题张氏家谱为硖川张嗣成赋","f":"五言古诗","c":["彼美留侯裔，传芳直到今。","千年遗谱在，万水一源深。","剖石方知玉，淘沙始见金。","簪缨联世胄，阀阅冠儒林。","吴郡名犹著，车溪迹可寻。","幽光仍耿耿，流景自骎骎。","霜露孤猿泪，乾坤寸草心。","紫薇山下路，佳气郁森森。"]},{"t":"望紫金山","f":"七言律诗","c":["万年佳气拥蟠龙，秀拔神京第一峰。","五色云中金翡翠，九重天上玉芙蓉。","幸陪周士歌丰镐，敢效封人祝华嵩。","明旦闻鸡趋凤阙，丹霞承日色曈昽。"]},{"t":"三月二日侍燕","f":"七言律诗","c":["春明侍燕三公府，正是龙飞第一年。","内膳八珍分翠釜，上尊九酝出琼筵。","箫韶乐奏祥云外，葵藿心驰化日边。","白首承恩何以报，愿言宗社福绵绵。"]},{"t":"三月二日陛辞钦蒙赐赉","f":"七言律诗","c":["贤王开国大江西，侍从朝辞白玉墀。","曙色飞回双阙凤，春声唱彻五门鸡。","烟霏缥缈凝丹扆，天语从容降紫泥。","惭愧微臣蒙赐赉，姓名亲向御前题。"]},{"t":"扈王驾出都城","f":"七言律诗","c":["三月三日天宇晴，千官扈从出瑶京。","桃花水动黄龙舫，柳絮风扬翠羽旌。","宝历万年宗社固，金城百雉瘴尘清。","白头奔走惭何后，载笔题诗纪远行。"]},{"t":"从祀南郊次韵","f":"七言律诗","c":["从官鹄立不知寒，先敕飞廉扫玉坛。","星拱帝居云澹荡，日宾旸谷雨阑珊。","礼严郊祀天人格，恩及臣邻远近欢。","最羡能诗陈奉祀，龙旗影里簉朝班。"]},{"t":"次韵观驾入洪武门","f":"七言律诗","c":["遥望觚棱曙色明，浮空御气满金城。","象舆前导临双阙，凤盖中居集五兵。","广乐钧天云外奏，灵旗太乙日边行。","兹晨饮福颁春宴，百郡同沾雨露荣。"]},{"t":"登玉皇阁","f":"七言律诗","c":["玉女开关扫白云，非烟非雾结絪缊。","蓬莱晴拥金银气，阊阖晨朝黼黻文。","历历白榆天上见，珊珊琼佩日边闻。","空歌一曲无人和，惊起松头鹳鹤群。"]},{"t":"赐胙次何尹韵","f":"七言律诗","c":["九天日月绘旂常，冠盖如云拥帝乡。","价重黄金求骏马，盘行白玉赐羔羊。","宫壶敕许千官禄，朝佩恩沾两袖香。","礼乐光华今复见，载歌雅颂美成康。"]},{"t":"又用赐胙韵喜何尹还邑","f":"七言律诗","c":["杜陵行处非寻常，朝回日醉蓬莱乡。","也知扬州跨一鹤，绝胜仙家骑五羊。","雪消江水暮帆健，花发驿亭春酒香。","归来满县种桃李，长与野人歌岁康。"]},{"t":"送尚书贡先生入闽","f":"七言律诗","c":["敬亭山下秋云飞，钱唐江头风露微。","三更南斗海底出，八月白鸿天际归。","椰子槟榔南去远，荔枝龙眼北来稀。","明年漕运归来日，好为君王补衮衣。"]},{"t":"雪中玉堂夜直次黄清老韵","f":"七言律诗","c":["银河剪水渐霏微，供奉承恩直禁闱。","琪树有花春不老，玉堂无月夜生辉。","寒催光禄分官酒，暖觉归春入赐衣。","铃索声沈宫漏静，巴歌谁共和金徽。"]},{"t":"题上清真人送贵溪县尹诗卷","f":"七言律诗","c":["上清之宫仙所都，此邦曾剖使君符。","种来棠树勿剪伐，别去桃花还有无。","碧落空歌龙作篆，丹山文采凤衔图。","何当更换金丹秘，长使藏身白玉壶。"]},{"t":"送进士会试之京","f":"七言律诗","c":["十载萤窗不惮劳，少年文雅涉风骚。","已闻蟾窟分丹桂，又向龙门钓六鳌。","一片布帆天上近，九重金阙日边高。","文场战罢承恩日，更赋新诗夺锦袍。"]},{"t":"送俞员外归省如京","f":"七言律诗","c":["积雪拥门三尺馀，好春来自玉阶除。","郎官近拜回鸾诰，父老争迎驷马车。","生菜翠盘朝具馔，高花红烛夜看书。","出门便是云泥隔，日日江头候鲤鱼。"]},{"t":"祷雨有感 其一","f":"七言律诗","c":["天坛昨夜秋如水，袖里青蛇作电飞。","海水立时风乍起，毕星临处月初离。","仙人谁挟飞霞佩，太守还题喜雨诗。","不用胡麻炊作饭，大田有粟可充饥。"]},{"t":"祷雨有感 其二","f":"古风","c":["海上炎氛十丈红，仙人曾此有神功。","云随鸾鹤飞丹篆，雨挟蛟龙出贝宫。","星汉水流天上下，稻畦香动?南东。","白头野老歌仁惠，击壤清时祝岁丰。"]},{"t":"题苏武牧羊图","f":"七言律诗","c":["十九年中仗节旄，祁连山下梦劳劳。","一行书寄边鸿远，万里心悬汉月高。","沙碛尘随归日骑，河梁泪洒别时袍。","画中偶识麒麟像，忍见秋霜点鬓毛。"]},{"t":"和张贞居寄倪云林韵","f":"七言律诗","c":["昔闻公孙浑脱舞，今见书法有张颠。","君能高歌白云调，我欲笑拍洪崖肩。","玉笙皓鹤久无信，青李来禽真可怜。","洞庭春水碧于酒，细雨绿蓑须放船。"]},{"t":"题大悲阁","f":"七言律诗","c":["宝阁凌空十丈高，倚阑南望际鲸涛。","天花散处皆金地，海月生时见玉毫。","夜气澄清龙在窟，秋声萧爽鹤鸣皋。","丹梯咫尺诸天近，香雾霏霏湿苧袍。"]},{"t":"寿张河泊","f":"七言律诗","c":["三山紫翠压金鳌，琪树英英长凤毛。","正月江南春意早，明河天上使星高。","王乔应下双飞舄，方朔曾偷两度桃。","醉把流霞唤鹦䳇，风吹花气满宫袍。"]},{"t":"春日即事","f":"七言律诗","c":["草堂长日无车马，雨后空阶长绿苔。","已见梅花当户放，更移萱草近窗栽。","引雏沙燕时高下，作伴江鸥自往来。","物色于人俱适意，诗篇吟罢共谁裁。"]},{"t":"镜中梅","f":"七言律诗","c":["日上绮窗啼翠禽，临鸾点额晓寒侵。","一泓自照春风面，百鍊方知铁石心。","白玉台前怜影瘦，黄金矿内觉情深。","锦囊收拾馀音去，月落空闺何处寻。"]},{"t":"滴翠轩","f":"七言律诗","c":["武隆山下望晴晖，岚气濛濛翠欲飞。","龙带晚云归夜榻，鹤翻朝露湿秋衣。","石洼承溜泠泠泻，水乐悬崖点点稀。","恰似匡庐招五老，屏风九叠护霏微。"]},{"t":"游葆真观 其一","f":"七言律诗","c":["百尺飞楼接帝青，非烟非雾入冥冥。","云间鸡唱朝迎日，海底蛟眠夜见星。","函谷有关瞻紫气，蓬莱无地问丹经。","道人肉重不骑鹤，一曲空歌醉复醒。"]},{"t":"游葆真观 其二","f":"七言律诗","c":["黄鹤一去不复返，紫阳有孙能学仙。","蓬莱如隔三千里，萍水相望四十年。","炼就大丹金作鼎，种来灵草玉为田。","无端四月枇杷雨，不共青镫一醉眠。"]},{"t":"游葆真观 其三","f":"七言律诗","c":["蓬莱东畔是仙家，旭日苍凉绚紫霞。","门外黄尘皆海水，窗间青鸟识桃花。","閒寻墨沼来题竹，拟借丹炉学鍊砂。","千岁安期吾有约，他年同吃枣如瓜。"]},{"t":"苦热","f":"七言律诗","c":["溽暑经旬懒出门，风亭水榭亦昏昏。","徒闻露下黄姑渚，漫想冰生玉女盆。","筠簟不教眠得稳，蔗浆犹觉饮来温。","故人病起应相忆，何日从容共晚尊。"]},{"t":"寄枢上人","f":"七言律诗","c":["上人年少解言诗，应是前身本姓支。","多病养成丘壑志，学书临得庙堂碑。","萝窗翳翳云封屋，茧纸重重墨满池。","想得山中三日雨，煮茶烟起落花时。"]},{"t":"次韵 其一","f":"七言律诗","c":["黄花翠竹带清溪，方外诗名惠远齐。","铁钵夜分鲸海月，袈裟晴污燕巢泥。","三生石上今重见，百丈峰头拟共跻。","闻道御前宣教旨，天花如雨散龙墀。"]},{"t":"次韵 其二","f":"七言律诗","c":["支许论诗已有年，还同食蜜味中边。","题名正喜芭蕉写，入定从教薜荔缠。","暮雨疏钟高阁外，秋云短锡故山前。","相过只说无生话，似觉浮生绝世缘。"]},{"t":"柬直方居士 其一","f":"七言律诗","c":["髯翁经夏稀相见，绝爱清容似我兄。","好采紫芝娱晚景，更栽红杏待春耕。","长安女子应知姓，庐阜仙人早得名。","从此草堂三日雨，相过莫厌绿苔生。"]},{"t":"柬直方居士 其二","f":"七言律诗","c":["自笑读书长闭户，每逢清友即同游。","柴门可是妨人扫，斗酒还能与妇谋。","任尔雨晴来看竹，从渠雪夜竟回舟。","风流此意谁能识，赖有忘机海上鸥。"]},{"t":"柬直方居士 其三","f":"七言律诗","c":["墨池昨夜水生波，换得山阴道士鹅。","盖世文章今有几，传家书谱已无多。","休粮服得霞千片，握发盘成雪两螺。","拟借白云分半榻，醒时言笑醉时歌。"]},{"t":"柬直方居士 其四","f":"七言律诗","c":["鹤背东来不待招，云裳霞佩思飘飘。","语言已觉无烟火，襟度还能振泬寥。","近海玉楼天不远，当阶珠树雪初销。","此中别有箕山趣，莫为风声即弃瓢。"]},{"t":"采莲女","f":"七言律诗","c":["小小兰舟棹晚凉，双双新浴锦鸳鸯。","舞回叶底春无力，笑入花间水亦香。","妾恨恰如莲菂苦，郎情应似藕丝长。","娉婷却笑东家女，换得明珠论斗量。"]},{"t":"鞋山 其一","f":"七言律诗","c":["一叶青莲堕碧波，美人不见奈愁何。","天边有月羞弓样，水底无尘污袜罗。","五老著来云气湿，小姑行处露花多。","足音未许人间识，蹴蹋风涛几度过。"]},{"t":"鞋山 其二","f":"七言律诗","c":["曾忆兰舟问二姑，何年只履堕晴湖。","满江波浪流不去，小龙女儿穿得无。","只许足音闻谷口，不教踪迹混泥途。","至今想见凌波袜，隔水盈盈不受呼。"]},{"t":"春日东园即事 其一","f":"七言律诗","c":["小园今日春意动，风目正东来草堂。","萱草渐抽书带绿，柳条都酿曲尘黄。","鸟声近屋啼偏好，雨点沾衣湿不妨。","稚子下阶频指点，去年种竹已过墙。"]},{"t":"春日东园即事 其二","f":"七言律诗","c":["东园检点旧生涯，春色多情到我家。","谷雨前头移菊本，清明时节看梨花。","但求北郭多收秫，何待东门更种瓜。","今夜月明吹玉笛，笑呼儿女进流霞。"]},{"t":"寄东冈贾徵君","f":"七言律诗","c":["三月三日雨晴初，东望东冈无鲤鱼。","杜陵爱酒自多债，太传治安还有书。","洛中牡丹少閒地，江上燕子识吾庐。","木兰丹擢桃花水，颇怪近来踪迹珠。"]},{"t":"东园春日","f":"七言律诗","c":["检点小园无别事，清晨汲水自浇花。","蔷薇碧引风前蔓，芍药红抽雨后芽。","可是野情忘世故，正缘春色属诗家。","山僧野老时相遇，分送菩提寺里茶。"]},{"t":"寄硖山人","f":"七言律诗","c":["碣石岩前有隐君，草堂分得半间云。","两湖月色当窗见，万壑秋声隔树闻。","墨沼寒通丹井水，银床暗护紫苔纹。","此身迥出烟霞表，长倚青霄看鹤群。"]},{"t":"除夕忆京中小弟","f":"七言律诗","c":["明朝岁事又更新，应簉鹓行拜紫宸。","鳷鹊观前还见雪，脊令原上况逢春。","花占蜡炬怜今夕，酒进屠苏少一人。","池草梦中深念汝，寄来诗句莫辞频。"]},{"t":"双孔笛","f":"七言律诗","c":["混沌谁分浊与清，凿开空翠太分明。","有声本自无声出，二气还从一气生。","碧海水寒龙并语，瑶台月白凤谐鸣。","依稀黄鹤楼中听，吹落梅花雪满城。"]},{"t":"过贡秘书墓","f":"七言律诗","c":["只今学士总奔波，不似先生葬薜萝。","眼见蓬莱成海水，身骑箕尾上星河。","开元供奉江南少，天禄词臣地下多。","回首敬亭秋色远，山青云白奈愁何。"]},{"t":"西翠楼为郭医作","f":"七言律诗","c":["北郭仙人十二楼，好山多在屋西头。","凉阴晚送窗前雨，爽气朝迎笏外秋。","翡翠半帘分太华，凤凰双琯下昆丘。","安期定有如瓜枣，我欲相寻海上游。"]},{"t":"挽高处士 其一","f":"七言律诗","c":["阿翁手种春松树，预卜佳城已十年。","将老便寻身后计，有儿能守墓傍田。","晚凉就竹安茶具，春水当花放酒船。","如此风流今绝少，一回西望一潸然。"]},{"t":"挽高处士 其二","f":"七言律诗","c":["忆昨相寻高处士，回舟醉蹋藕花风。","三年别梦来溪上，一个閒身在墓中。","故老只今俱寂寞，浮生方信是虚空。","哀歌写罢缄双泪，秋叶离离夕照红。"]},{"t":"失鹤","f":"七言律诗","c":["仙人骐骥谁能驭，鍊得丹砂顶渐红。","不见将军来射石，却瞋童子惯开笼。","梦閒一曲沧洲月，声断三山碧落风。","从此竹林无伴侣，洞箫吹彻綵云空。"]},{"t":"赋惠山泉送张徵君之无锡","f":"七言律诗","c":["往年曾识惠山人，遗我灵泉一味真。","水品评来称第一，茶经著就已千春。","也知陆羽曾分汲，信有梁鸿共卜邻。","此去茅斋休煮雪，山瓶还许寄来频。"]},{"t":"题倪元镇画","f":"七言律诗","c":["往年曾访天随子，烟树微茫过太湖。","雪色寒鲈临水买，翠毛春鸟隔林呼。","只今图画浑相似，如此家山住得无。","皎皎白驹空谷里，令人搔首忆潜夫。"]},{"t":"立春雨","f":"七言律诗","c":["今朝占得正东风，春在江南好雨中。","六琯气从温室候，八方云与泰山通。","调和草色相将绿，沾洒花枝取次红。","茅舍一瓢生菜酒，自题春帖纪年丰。"]},{"t":"过吴江 其一","f":"七言律诗","c":["江上凉生白苧袍，荻花枫叶晚萧骚。","长虹饮涧天在水，怒雷劈山风送涛。","地势混茫通九泽，风流今古属二豪。","收帆暂向枫湾泊，唤索吴姬压小槽。"]},{"t":"过吴江 其二","f":"七言律诗","c":["第四桥头夕照红，收帆买纸谢龙公。","酒从今夜赊明月，船待来朝借顺风。","树色苍茫晴雨外，江光明灭有无中。","今来古往东流水，无限閒情逐去鸿。"]},{"t":"和友人韵","f":"七言律诗","c":["西望东冈首重回，菩提山在白云堆。","乌衣燕去无华屋，碧眼僧来有劫灰。","往事茫茫何足较，流年衮衮莫相催。","梨花又过清明节，载酒无由得暂陪。"]},{"t":"和黄应奉巧夕书怀","f":"七言律诗","c":["凉云如练坐来收，此夜家家望女牛。","列宿总随天北转，明河不共海东流。","铜龙漏转三更月，白雁声传两地秋。","笑卜蛛丝凭远信，有人相忆凤凰楼。"]},{"t":"夜坐玩月","f":"七言律诗","c":["紫薇花满月团团，今夜三更最好看。","碧海飞来银作阙，青云高处玉为盘。","蛟龙应有含珠泪，兔臼宁无换骨丹。","独据胡床吹短笛，苧袍风露不胜寒。"]},{"t":"江上","f":"七言律诗","c":["三湘南去别情多，不唱吴歌唱楚歌。","夜雨滴乾斑竹泪，春风吹老白蘋波。","瑶琴谁和巴人曲，锦字空劳织女梭。","却喜沅陵酒价贱，愁来犹得遣诗魔。"]},{"t":"九日和应先生韵","f":"七言律诗","c":["白发秋深莫浪悲，有酒且醉高阳池。","百年知几从古少，一日不见令人思。","醉来子细看萸佩，兴剧风流歌柘枝。","洪范桥西浣花老，得钱相觅肯教迟。"]},{"t":"悼断臂禅师","f":"七言律诗","c":["禅机山头一臂禅，幽居长在白云边。","已超世网三千劫，不出山门二十年。","坏衲朝阳松下石，春茶活火竹根泉。","法身毕竟无来去，只履还应到五天。"]},{"t":"游鸡鸣寺","f":"七言律诗","c":["夜半鸡鸣海日红，凭虚涌出梵王宫。","绀园树色朝含雨，宝塔铃声昼撼风。","飞锡神僧西域至，散花天女上方通。","曾闻翠辇登临处，御墨留题紫翠中。"]},{"t":"送杜弘道之襄阳","f":"七言律诗","c":["西阁馀寒入毳袍，一尊送别思劳劳。","路逢寒食花偏好，船压春江水正高。","汉女堤边歌芍药，习家池上醉蒲萄。","谷城令尹如相问，为说刘郎又种桃。"]},{"t":"寄宋纪善","f":"七言律诗","c":["锦里先生两鬓丝，曳裾天府际昌时。","经筵虎豹分重席，墨沼龙蛇见大旗。","白雪久传梁苑赋，清朝新睹汉官仪。","挥弦赖有知音在，欲把黄金铸子期。"]},{"t":"和贾徵君韵 其一","f":"七言律诗","c":["不见故人今半年，寄我好诗情绪牵。","朱弦泠泠有古调，玉树濯濯当春妍。","前身可是韩京兆，此地曾逢贾浪仙。","梦绕钟声寺前月，推敲两字至今传。"]},{"t":"和贾徵君韵 其二","f":"七言律诗","c":["忆昨放舟相见时，系䌫宅前杨柳丝。","别来晴云碧冉冉，看过秋叶红离离。","茶煎雪水同谁吃，书到柴门有梦知。","晴日半窗初睡起，水仙花畔和君诗。"]},{"t":"和贾徵君韵 其三","f":"七言律诗","c":["想见南窗日上时，硬黄茧纸写乌丝。","兔敲玉臼丹应就，蛇避金尊影已离。","司马时多文字渴，伯休谁遣姓名知。","流年又及春盘菜，一度停云一赋诗。"]},{"t":"次郭先生韵","f":"七言律诗","c":["南郭先生久不来，草堂日日向南开。","笋已长成高过竹，花都狼籍半为苔。","渴心谁慰病司马，诗债先偿曲秀才。","闻道放舟苕水上，看山自倒白螺杯。"]},{"t":"次复柬先生纪行之什 其一","f":"七言律诗","c":["丹凤衔图振羽仪，六龙扶驭跃天池。","紫垣月转通明殿，黄道星环太乙旗。","宝鼎香烟穿柳细，金壶漏点出花迟。","相如词赋真无敌，行见成都驷马驰。"]},{"t":"次复柬先生纪行之什 其二","f":"七言律诗","c":["清朝文轨万方同，人在金瓯覆橐中。","五色丝纶颁凤阙，千年珠贝出龙宫。","碧桃红杏当霄见，若木榑桑与海通。","寄谢紫薇山下客，穷经慎勿叹头童。"]},{"t":"次复柬先生纪行之什 其三","f":"七言律诗","c":["未明司钥启晨阍，冠盖如云谒九门。","百谷水归东海大，八方星拱北辰尊。","鸡鸣紫禁宫花合，马度金河御柳繁。","此日儒冠蒙锡赉，白头歌咏荷洪恩。"]},{"t":"晨兴七宝山有作","f":"七言律诗","c":["晨起登高望八荒，金霞承日上榑桑。","潮头白处腾蛟鳄，天目青来舞凤凰。","万井人家烟漠漠，诸天觉路海茫茫。","长斋绣佛心如水，消得梅花昨夜霜。"]},{"t":"题瞻云图","f":"七言律诗","c":["望望高云不可攀，乡心都在画图间。","门前白处皆苕水，屋上青来是弁山。","食禄正思三釜养，买舟未省几时还。","狄公勋业遗千载，莫待冯唐鬓发斑。"]},{"t":"送杨判簿考绩如京","f":"七言律诗","c":["我识关西好子孙，河源九派出昆崙。","半生华发频看镜，秋夜黄金不到门。","一曲离歌心事远，三年政绩口碑存。","无端又向明朝别，手把茱萸泛绿尊。"]},{"t":"送黄将军分镇台城","f":"七言律诗","c":["夜半鸡鸣海日晴，将军东指亚夫营。","山临华顶天逾近，星应台垣地最灵。","总道张骞曾泛海，况逢黄石共谈兵。","冬来若有长安使，只寄黄精与茯苓。"]},{"t":"海昌八咏 其一 海门洪涛","f":"七言律诗","c":["一花初起白龙堆，万骑长驱石壁开。","碧海有山都是雪，青天无雨只闻雷。","秋高鸿鹄排云去，夜静蛟龙出穴来。","借问乘槎向何处，五云咫尺是蓬莱。"]},{"t":"海昌八咏 其二 五祠古桧","f":"七言律诗","c":["灵祠双桧郁葱葱，秀色浑如在鲁东。","竽籁半空来凤吹，波涛中夜撼蛟宫。","碧云团盖天门近，翠雾当窗日观通。","会有神明扶正直，奇材真与栋梁同。"]},{"t":"海昌八咏 其三 紫峡秋云","f":"七言律诗","c":["两峡亭亭拱翠微，白云漠漠澹秋晖。","飞腾碧落从龙去，点缀青松待鹤归。","夜度钟声来梵阁，朝浮岚气湿僧衣。","会须化作商家雨，可是无心出岫飞。"]},{"t":"海昌八咏 其四 顾况书台","f":"七言律诗","c":["紫微之峰林壑幽，顾况台前曾一游。","千年古寺白云外，一个长松丹井头。","僧借翻经凉月夜，童来扫叶夕阳秋。","明朝别后登临处，惟有书声杂涧流。"]},{"t":"海昌八咏 其五 葛洪丹井","f":"七言律诗","c":["闻道仙人句漏令，烧丹此地学长生。","林光每散金银气，石髓犹含日月精。","仙药九还为白雪，灵泉一勺胜金茎。","不须更借三山鹤，便碾飙轮上玉京。"]},{"t":"海昌八咏 其六 安国禅灯","f":"七言律诗","c":["白头僧说唐朝寺，舍利犹存率堵波。","师子座空无所住，犀牛扇破竟如何。","灯悬海月慈光近，铎振天风梵呗多。","最爱平原好孙子，时来坐石看曼陀。"]},{"t":"海昌八咏 其七 张许双庙","f":"七言律诗","c":["睢阳太守清源令，衮冕巍巍共一祠。","节重长淮坚守日，功高灵武中兴时。","汗青不泯忠臣传，太白长悬大将旗。","圣代春秋严祀典，祠臣鹄立见光仪。"]},{"t":"海昌八咏 其八 虹桥夜月","f":"七言律诗","c":["渴虹饮涧不曾收，化作飞梁卧碧流。","银汉水分天上下，白莲花出海东头。","鹤归华表吹笙夜，龙献明珠解佩秋。","载酒长安三十里，醉呼鹦鹉更停舟。"]},{"t":"寄峡川杨司征","f":"七言律诗","c":["我爱关西好孙子，紫微山水足遨游。","千家树色双峰晓，万壑钟声六寺秋。","渔唱樵歌通槜李，龙光剑气属扬州。","老夫尽有登临兴，载酒能来倚暮楼。"]},{"t":"立春","f":"七言律诗","c":["申年春自申时到，万物申申总向荣。","南亩已沾三日雨，东皇能赐一朝晴。","历颁夏正乾坤大，斗指寅方海宇清。","白发野人瞻气象，五云高处泰阶平。"]},{"t":"题玉绣毬花 其一","f":"七言律诗","c":["蕊珠宫女夜回鸾，一色流苏玉作团。","琪树想从天上见，琼花曾向月中看。","当场蹴起三春暮，信手围来二尺宽。","却怪朝来万蝴蝶，随风飞舞碧阑干。"]},{"t":"题玉绣毬花 其二","f":"七言律诗","c":["蕊珠宫女夜回鸾，玉琢流苏满画阑。","偏称彩丝悬昼影，错教罗袜立春寒。","翠云欲坠风扶起，粉蝶交飞雪作团。","却笑美人惊堕马，琼花不数广陵看。"]},{"t":"游峡山寺 其一","f":"七言律诗","c":["山气英英结紫霞，上方台殿布金沙。","曾寻竺国俱胝石，因识唐朝顾况家。","龙献珠来天欲雨，鹤随丹去井无砂。","两年不到题诗处，想得枇杷又著花。"]},{"t":"游峡山寺 其二","f":"七言律诗","c":["枇杷著花当仲冬，紫薇郎在紫薇峰。","一尊明月南湖棹，两峡清霜六寺钟。","茶具入林还傍竹，经台坐石更看松。","此时何限登临兴，满抱风流属贺公。"]},{"t":"游峡山寺 其三","f":"七言律诗","c":["雨后看山罨画同，挥毫不数米南宫。","半生丘壑藏来久，一段烟霞写得工。","绝顶鸟飞空界外，右肩僧袒夕阳中。","悬知意匠经营苦，东望停云思不穷。"]},{"t":"送富天源长老","f":"七言律诗","c":["二月雪消春水肥，慧云上人明日归。","杏花飞送官河棹，木兰染成田相衣。","东海蛟龙长听法，南湖鱼鸟静忘机。","何时共话三生石，坐听钟声出翠微。"]},{"t":"题如舟斋","f":"七言律诗","c":["凭虚浑似倚蓬窗，况有鲈鱼酒满缸。","月色半帆经采石，雨声千里忆湘江。","阑干影外皆春水，欸乃声中是楚腔。","借问何人分席坐，忘机惟让白鸥双。"]},{"t":"读张外史诗","f":"七言律诗","c":["海内诗人久寂寥，静中披卷即神交。","函关紫气长怀李，句曲青山本姓茅。","快雨送晴来竹下，淡云流月过林梢。","令威若返辽东鹤，定拟云松共结巢。"]},{"t":"游东陈村","f":"七言律诗","c":["一湾晴绿转溪蘋，载酒谁家探好春。","此地久无看竹处，他山犹有种桃人。","泥添燕子巢边雨，雪点梨花陌上尘。","安得移家同卜隐，儿孙婚嫁学朱陈。"]},{"t":"病起","f":"七言律诗","c":["病起科头傍药阑，关关幽鸟语春寒。","看诗顿觉今朝健，载酒能忘旧日欢。","苔受落花当户外，笋添新竹过檐端。","白龙浑上当年月，曾泊扁舟看玉盘。"]},{"t":"赋石井送吴税使还乡","f":"七言律诗","c":["头白乌啼井上桐，桐花落尽夜来风。","愁见还乡吴季子，恨无缩地马仙翁。","辘轳声里肠应断，天柱峰头思不穷。","试把丹泉分一掬，慈颜犹得驻春红。"]},{"t":"挽赵子奇","f":"七言律诗","c":["春襟郁郁向谁开，别后那知竟不回。","载酒长怜千里隔，看花又少一人来。","论交有道嗟何及，述德无人更可哀。","留得平生数行泪，秋风洒向菊花杯。"]},{"t":"游天禧寺","f":"七言律诗","c":["梵王宫在帝城南，一锡秋飞入翠岚。","出寺已过潮十八，到京还近月初三。","祗园地布金沙满，香积厨分玉露甘。","若见黄花潭般若，凭归传语老瞿昙。"]},{"t":"秋夕玩月","f":"七言律诗","c":["今夜秋高月正中，白莲浮出海龙宫。","地临玄圃三山近，潮与银河一水通。","白玉杯盛仙掌露，黄金花散木犀风。","等閒飞步天坛上，直欲凭凌万丈虹。"]},{"t":"赋石蟹泉送僧游南山","f":"七言律诗","c":["上人卓锡风篁岭，应看山中石蟹泉。","沙晚试听蒲叶雨，水凉况近菊花天。","暗通雪窦金膏滑，清漱云根玉髓坚。","寄语无肠好公子，待余来候煮茶烟。"]},{"t":"久雨书事","f":"七言律诗","c":["三月积雨苦淙淙，茶鼎熏炉坐北窗。","墙花半庭浑是雪，沟水一夜忽如江。","醉推愁去粗能解，睡遣魔来不可降。","谁似閒居真伴侣，白鸥来往自双双。"]},{"t":"雨中答友人","f":"七言律诗","c":["春城雨脚密复疏，把钓欲访东溪渔。","白酒尚能谋一醉，青泥政恐污长裾。","鹊鸣花坞来诗卷，蜗上苔阶学篆书。","宝鸭沈烟消永日，此怀端合为君摅。"]},{"t":"答谢友人 其一","f":"七言律诗","c":["小东门外野人家，昨夜青镫定结花。","一片碧云空在望，半规明月可能赊。","杖扶紫玉过眉瘦，巾裹乌纱垫角斜。","明日更须来看竹，山瓶汲水自煎茶。"]},{"t":"答谢友人 其二","f":"七言律诗","c":["盘餐粗粝笑贫家，赖有东园茧栗花。","野水白鸥情自狎，海天黄鹄志应赊。","直须放浪超形外，更复留连到日斜。","向晚期看洛神赋，十三行畔坐分茶。"]},{"t":"寄贾彦德","f":"七言律诗","c":["凤凰冈头多碧梧，颍川之人安好无。","十年不寄一书札，两地相思今故吾。","淮云羃羃暮天远，楚水茫茫秋雁孤。","想得临池有佳趣，软黄茧纸写官奴。"]},{"t":"挽愚丘老翁","f":"七言律诗","c":["十年不见愚丘老，千里相望颍水头。","挂剑荒凉吴树晚，封书断绝楚鸿秋。","长沙不复归宣室，先友空怀记柳州。","一掬天涯数行泪，临风洒向大江流。"]},{"t":"和友人家字韵","f":"七言律诗","c":["陶令得钱付酒家，杜陵有地只栽花。","古称旷达谁能及，人卖痴呆我得赊。","半醉半醒风韵在，初三初四月钩斜。","足音若许来空谷，竹外弹琴竹里茶。"]},{"t":"次顾友常见寄前韵","f":"七言律诗","c":["丹井西头顾况家，子规啼处落松花。","怜余抱疾烟霞久，与子论交岁月赊。","海燕雨深茅屋小，江鱼潮上石帆斜。","有怀只许诗传信，相见唯应酒当茶。"]},{"t":"就韵赋林庄为惟敬作","f":"七言律诗","c":["数椽茅屋让西家，屋里琴书屋外花。","白酒且寻彭泽醉，青山未许辋川赊。","鸥边雨舫春潮急，牛背烟蓑夕照斜。","拟约班荆同话旧，蒸梨炊黍坐分茶。"]},{"t":"出东郭访贾惟敬不遇用韵","f":"七言律诗","c":["出郭行寻野老家，桑条生葚楝生花。","别来似有三秋隔，到此曾无二里赊。","白鸟随人频往返，黄茅盖屋半欹斜。","遥知去汲乌龙井，细歠菩提寺里茶。"]},{"t":"读张蜕庵先生诗集用韵","f":"七言律诗","c":["仙翁委蜕太清家，彤管长留五色花。","诗到黍离风已变，鹤归华表梦应赊。","泠泠清庙弦声古，濯濯铜盘露脚斜。","读罢令人清彻骨，底须学士凤团茶。"]},{"t":"贾先生以熏香见惠用韵","f":"七言律诗","c":["甲煎分惠及诗家，芳烈浑如百和花。","云母石头熏得薄，麻姑书尾寄来赊。","雨窗暖逼琴弦燥，风榻晴看篆缕斜。","一日所须消一饼，从教白绢莫封茶。"]},{"t":"送友人之丹丘","f":"七言律诗","c":["存心堂上丹丘老，笑语烟霞自不凡。","洗药每临青玉涧，读书长傍白云岩。","南州冠冕称高士，大阮文章重阿咸。","安得麻姑借一鹤，时令过海送诗缄。"]},{"t":"次觯上人韵","f":"七言律诗","c":["上人白毫应寿昌，寄来草圣逼钟王。","莲花漏点禅心静，蕉叶雨声诗梦长。","出海神龙还问法，上堂侍者惯烧香。","南州八月尚烦热，渴想一杯甘露凉。"]},{"t":"拜祖师墓和韵","f":"七言律诗","c":["木杯东渡海门涛，鸣鹤翩翩在九皋。","舍利夜光童子塔，袈裟秋影祖师袍。","三生石在因缘旧，两峡山来气势高。","今古一镫传不尽，白云飞处梦劳劳。"]},{"t":"东园晚兴","f":"七言律诗","c":["平头奴子挥纨扇，一饷微凉坐晚晴。","归鸟界天疏复密，残虹交日断犹明。","莎鸡欲向阶前语，萤火多从井畔生。","月下痴儿閒弄影，不知风露已三更。"]},{"t":"送何尹男从戎","f":"七言律诗","c":["白头水部在戎行，荣辱升沈得此郎。","万里苍黄问家室，三年辛苦寄衣裳。","暮投野店鸡声月，朝度关河雁背霜。","别去壮年须努力，卫青功业有辉光。"]},{"t":"观海雨阻","f":"七言律诗","c":["五鼓既作鸡三鸣，披衣起坐候朝晴。","无端东海秋潮信，又作西窗夜雨声。","红想霞生旸谷树，青怜山近越王城。","会须明日偿高兴，随意看云称野情。"]},{"t":"秋江闻雨","f":"七言律诗","c":["秋夜夜长雨复作，虚阁萧条诗梦清。","蕉叶半窗敲渐密，烛花一寸落还生。","不愁屋漏无乾处，正喜年丰有颂声。","问讯丹丘广文老，朝来病骨也须轻。"]},{"t":"寄友人 其一","f":"七言律诗","c":["秋阴阁雨幂林梢，野舫乘閒出远郊。","井就乌龙评水品，山寻白鹤借云巢。","煮茶榻共高僧坐，问字门容弟子敲。","想得东家好清事，竹间松下具行庖。"]},{"t":"寄友人 其二","f":"七言律诗","c":["东里先生眉最白，南州高士眼终青。","蓬莱弱水三清浅，胡蝶庄周一梦醒。","今日好书封禅草，他年还筑聘君亭。","看山楼外秋无际，谁识天边处士星。"]},{"t":"送人回馀杭","f":"七言律诗","c":["小阁熏炉散午烟，论诗爱尔最清妍。","夜灯三宿无他梦，春水明朝各自船。","茶到山中分谷雨，酒从地上品丹泉。","此行若过栖真洞，寄语仙翁葛稚川。"]},{"t":"谢惠桂花","f":"七言律诗","c":["金佛寺中金粟子，黄金布地即金沙。","兔公邀月来香国，龙女凌风散宝花。","撚处从教迦叶笑，寄来绝胜赵州茶。","老夫鼻观根尘断，遮莫秋风到我家。"]},{"t":"送知县陈仲信之建昌","f":"七言律诗","c":["太学儒生三载别，建昌令尹九江行。","中流鹅鹳秋帆健，五色麒麟画锦荣。","日照香炉生曙色，河翻瀑布落秋声。","清朝乐育菁莪意，复见弦歌在武城。"]},{"t":"望海","f":"七言律诗","c":["元气洪濛混太虚，天吴簸荡撼坤舆。","千年木石劳精卫，百谷波流会尾闾。","月下明珠蛟女泣，云中飞观羽人居。","秋风吹老珊瑚树，不见麻姑锦字书。"]},{"t":"寄何山人","f":"七言律诗","c":["白发梁园能赋客，近闻卜隐在林塘。","茶分陆羽评来水，药按桐君著后方。","雨杂涧声通墨沼，风吹花片落琴床。","春来佳趣同谁领，拟约诗人坐竹房。"]},{"t":"寄幽湖友人","f":"七言律诗","c":["幽湖之水清且幽，三十年前曾一游。","山中伐木歌黄鸟，海上忘机想白鸥。","别去襟期同契阔，寄来书信莫沉浮。","白沙翠竹依然在，拟棹空明一镜秋。"]},{"t":"寄高徵士","f":"七言律诗","c":["金水河边承诏日，丹阳郭外买舟时。","还家咫尺无书问，抱被寻常有梦知。","高适平生孟诸野，杜陵人日草堂诗。","乌巾且漉黄花酒，莫遣秋霜上鬓丝。"]},{"t":"寒食感怀","f":"七言律诗","c":["江柳丝丝散碧烟，异乡佳节思绵绵。","空梁燕子惊三月，疏雨梨花又一年。","鲁酒可消官舍冷，宫袍初试越罗鲜。","栝山云树无多路，空把閒情托杜鹃。"]},{"t":"挽大无外","f":"七言律诗","c":["上方钟鼓寂无声，又报茶毗一个僧。","丈室不留居士榻，邻房空施药师镫。","身离火宅三千劫，手挽牛车第一乘。","清梦定过湖上寺，梅花月色澹如冰。"]},{"t":"挽沈孟云居士","f":"七言律诗","c":["我识东阳鹤发翁，每将五采绘虚空。","浮沉梦落沙鸥外，得失机藏塞马中。","幻境因缘今日了，他生笑语几时同。","无端闻讣初三夜，哭上青天月半弓。"]},{"t":"即事","f":"七言律诗","c":["静中得句共谁论，数日长吟懒出门。","卷幔不教妨燕子，扫花长恐损苔痕。","小园避地无车马，高竹过墙有子孙。","莫笑閒居无伴侣，兴来倾倒是山尊。"]},{"t":"题多景楼","f":"七言律诗","c":["十载前登多景楼，楼中景物最清幽。","大江入海走其下，白日丽天行上头。","去雁一声归楚信，征帆十幅过淮舟。","老夫登眺情何限，又为题诗得少留。"]},{"t":"次韵 其一","f":"七言律诗","c":["客里流年衮衮驰，鸟声如语复如悲。","破除午梦凭茶鼎，鏖战春愁是酒旗。","下榻定留徐孺坐，敲门还问子云奇。","人生何处无知己，和得回仙七字诗。"]},{"t":"次韵 其二","f":"七言律诗","c":["筑得春城似锦官，东南烽火喜平安。","花前起舞还提剑，李下行歌莫正冠。","铅澒昼开苍术火，罗衣朝试杏花寒。","鸣笳鼍鼓军中乐，应念高堂菽水欢。"]},{"t":"归来","f":"七言律诗","c":["贫居侧近曳裾坊，老病归来葺草堂。","芍药玉盘花更大，枇杷金弹子能黄。","每移棋局多依竹，自理琴弦不下床。","稚子扶持日卓午，下阶先占树阴凉。"]},{"t":"暮春病起","f":"七言律诗","c":["病起不知春已归，馀寒犹滞越罗衣。","仓庚只向愁中语，胡蝶多从梦里飞。","閒绕曲阑看芍药，更添修竹架蔷薇。","故人知我逢迎懒，颇觉诗筒近日稀。"]},{"t":"招饮答谢","f":"七言律诗","c":["绿阴门巷麦秋天，欲访高斋拜不前。","诗史少陵元姓杜，文章司马旧名迁。","竹间只许安茶具，花外何烦棹酒船。","昨日山庖分盛馔，笑看儿女舞回旋。"]},{"t":"题雪溪船","f":"七言律诗","c":["爱尔雪溪船最好，棹歌声近野鸥矶。","人如天上春来坐，兴比山阴夜半归。","当席最宜明月出，持杯长见落花飞。","往年记得曾相过，醉后寒生白苧衣。"]},{"t":"挽友人妻","f":"七言律诗","c":["白首飞蓬感岁华，不随句漏饭丹砂。","一函埋骨知何地，千里看云不是家。","南国春风怀荔子，东阑暮雨泣梨花。","传家有女能全孝，属纩无儿可叹嗟。"]},{"t":"送褚二令","f":"七言律诗","c":["大江八月鲤鱼风，兴在烟波浩荡中。","雨露自天通百粤，山川何处是南雄。","晚凉歇马榕阴绿，朝日行盘荔子红。","袖有相如封禅稿，会须献纳未央宫。"]},{"t":"寿郭文伯","f":"七言律诗","c":["蓬莱宫殿压金鳌，南极星明紫气高。","太傅诸郎琼作树，开元供奉锦为袍。","逢人惟种林间杏，待我来偷海上桃。","西翠楼前今夜月，玉笙谁伴醉春醪。"]},{"t":"送人之惠安教谕","f":"七言律诗","c":["春朝射策凤凰池，一日声华四海知。","驷马桥头题柱日，三鳣堂上校文时。","晚凉移席临蕉叶，朝日行盘擘荔枝。","别去应须各努力，粤云吴树总相思。"]},{"t":"柬高上人物表","f":"七言律诗","c":["手挥玉麈坐谈空，一月不知花信风。","远公高志在物表，苏晋长斋多醉中。","方池种莲春水绿，虚室坐观夜灯红。","悬知定起了无事，煮茶赋诗谁与同。"]},{"t":"题玉川草堂","f":"七言律诗","c":["古有玉川家洛阳，今有玉川开草堂。","周公梦回日丈五，谏议书来天一方。","野鹤当阶似人立，春笋过壁比儿长。","先生闭门无一事，花雨茶烟绕石床。"]},{"t":"送南昌玄妙吴大节鍊师编书之上清 其一","f":"七言律诗","c":["青天白云如白龙，送尔上谒蓬莱宫。","谁言肉重不骑鹤，我识神清能御风。","丹篆云霞从地出，玉坛星斗与天通。","芸窗驹影良可惜，清夜好分官烛红。"]},{"t":"送南昌玄妙吴大节鍊师编书之上清 其二","f":"七言律诗","c":["仙人宫阙五云交，羽佩翩翩起白茅。","月下方诸凝墨沼，风前脉望出书巢。","丹台石室名先到，玉检金编手自钞。","想得山中寒食近，青精作饮具山庖。"]},{"t":"清白轩为都昌县丞邵让题","f":"七言律诗","c":["杨震当年畏四知，君能清白更无私。","涵空水色原澄净，映雪梅花不受缁。","百里讴歌欣政化，千家弦诵听唔咿。","他时秩满登天府，民有甘棠去后思。"]},{"t":"送玘大璞还山","f":"七言律诗","c":["放生池头朝雨晴，上人买舟明日行。","飞锡还山双屐远，渡杯到岸一鸥轻。","湖西猿鹤心先喜，海上蛟龙梦不惊。","无限送春诗思在，尽情都付子规声。"]},{"t":"送恬上人兼柬奎方舟","f":"七言律诗","c":["飞来峰顶袈裟影，正在长松落照间。","正月不归当二月，出山未久又还山。","午阶花落茶烟澹，春院苔生杏雨斑。","问讯维摩无恙否，几时能伴白云閒。"]},{"t":"挽庆云山讲师","f":"七言律诗","c":["白云飞影度前峰，去上诸天第几重。","林下经閒春卧鹿，溪边钵冷夜归龙。","传灯谁续生前火，大药难留病后容。","积雨长廊苔色满，更无人听讲时钟。"]},{"t":"望海觞咏 其一","f":"七言律诗","c":["太常博士金闺彦，也爱长斋绣佛前。","放浪形骸当九日，康强筋力称馀年。","临池写字鹅翻雪，隔竹煎茶鹤避烟。","昨日登高东海上，时人称是地行仙。"]},{"t":"望海觞咏 其二","f":"七言律诗","c":["海国凉生白苧袍，年年此日爱登高。","不妨更落西风帽，想象同持左手螯。","雨过一江澄晚色，空清万里见秋毫。","凭阑望远谁能赋，只有元龙气最豪。"]},{"t":"贺人生日","f":"七言律诗","c":["蓬莱佳气接云高，此日初筵集俊髦。","二十四人金谷友，三千馀岁玉池桃。","祯祥自昔符麟绂，文采于今见凤毛。","一笑后天同介寿，蔷薇花畔醉春醪。"]},{"t":"种竹","f":"七言律诗","c":["屋前种得万筼筜，醉日移来傍短墙。","不碍月华晴照夜，最宜雨气晚生凉。","此君对酒年年好，稚子当阶个个长。","手把玉笙吹一曲，跄然如有凤来翔。"]},{"t":"题处静轩 其一","f":"七言律诗","c":["闻道仙家多种橘，此中佳趣有谁知。","波澜不起千年井，日月长閒一局棋。","总道苏耽能养母，也知商皓是吾师。","寄声华盖峰头月，静极还应有动时。"]},{"t":"题处静轩 其二","f":"七言律诗","c":["处静轩中好赋诗，熏炉茶鼎最相宜。","梦回啼鸟日高处，坐久落花风定时。","卖药仙人多种杏，烂柯樵者亦看棋。","援琴试鼓无弦调，流水高山只自知。"]},{"t":"和郭文伯惠笔韵","f":"七言律诗","c":["兔颖应从月窟收，寄来筠管自湖州。","题诗每愧钟王帖，载酒长怀李郭舟。","鲈出四鳃莼菜雨，蟹分八跪稻花秋。","十年不饮吴江水，安得相从访旧游。"]},{"t":"题画","f":"七言律诗","c":["空青点染入秋毫，不用并州快剪刀。","太华三峰从地出，蓬莱千仞倚天高。","重重涧壑藏云气，菶菶梧桐集凤毛。","寄语山中骑马客，清时莫种武陵桃。"]},{"t":"题海雪轩","f":"七言律诗","c":["马家亭子海云边，一室空明万里天。","阆苑东来花满树，昆崙西去玉为田。","珠宫冻合龙鳞湿，斗帐寒生鹤梦圆。","坐钓珊瑚枝上月，子猷那肯便回船。"]},{"t":"题琴轩","f":"七言律诗","c":["借问轩中何所有，一琴佳趣少人知。","但能白首归元亮，何必黄金铸子期。","幽涧水声风静处，碧窗萝影月明时。","好寻太古无弦调，更赋巴人白雪词。"]},{"t":"望雨","f":"七言律诗","c":["一月不雨农心忧，两月不雨田无秋。","南山空闻雷电作，北斗不挽星河流。","赤龙枯死洞中燕，白日叫乾桑下鸠。","昨夜欣闻月离毕，照泥星出屋东头。"]},{"t":"送友人之蜀川","f":"七言律诗","c":["山上于今复有山，亲闱宛在白云间。","江帆直上五千里，秋水初生十八滩。","谢豹叫云魂魄苦，楚娥啼竹泪痕斑。","相思若有平安信，寄与明年春雁还。"]},{"t":"送人还南雄","f":"七言律诗","c":["秋风吹老白蘋花，八月归船定到家。","重见彭篯生盛代，也胜贾谊谪长沙。","云帆入楚轻于鸟，江水通巴曲似蛇。","诸蹇登堂拜郎罢，吴音越语共讴哑。"]},{"t":"送张将军之京","f":"七言律诗","c":["綵旗袅袅动春城，千里朝天上玉京。","诸将论功称李牧，小儿学语识花卿。","弯弓曾射南山虎，立马还听上苑莺。","江上梨花一杯酒，题诗相送若为情。"]},{"t":"题涵碧轩图","f":"七言律诗","c":["云影天光湛碧虚，何年卜筑傍西湖。","可怜故老归泉壤，只许儿孙见画图。","秋雁白边渔艇小，晚山青处草堂孤。","却思旧日欢娱地，花满楼船酒满壶。"]},{"t":"题秋江别意图","f":"七言律诗","c":["五色纶丝下九关，使君指日向南还。","云帆直上五千里，江水初生十八滩。","愧我安能从骥尾，如公正合在鹓班。","到家已是登高节，把菊悠然在看山。"]},{"t":"寄贡尚书侄 其一","f":"七言律诗","c":["三十年前老秘书，故家文献近何如。","诸孙总抱连城璧，遗稿谁收合浦珠。","荒冢有人来下马，秋风无树可栖乌。","嗣宗子侄唯公在，何日相过致束刍。"]},{"t":"寄贡尚书侄 其二","f":"七言律诗","c":["吴云越鸟思悠悠，每忆高人住沃洲。","诗法好追元刺史，风流还继白杭州。","钓船荷雨孤镫夜，禅榻茶烟两鬓秋。","莫恋贺家湖一曲，行看玉帛贲林丘。"]},{"t":"寄严州张同知","f":"七言律诗","c":["近闻别驾朝天去，船过长安问野人。","声价已知当代重，交情还似向来真。","月明江上鱼龙喜，日落山中虎豹驯。","肯借严陵滩畔石，持竿来共白鸥邻。"]},{"t":"赠医士长律十首 其一 上池","f":"七言律诗","c":["吾闻上池世莫识，扁鹊传来信有神。","饮水不过三十日，隔垣能见一方人。","若非沆瀣流金液，定是昆崙漱玉津。","自笑烟霞多病渴，愿分一勺洗埃尘。"]},{"t":"赠医士长律十首 其二 丹灶","f":"七言律诗","c":["海上仙人有葛洪，骑云八极杳无踪。","十年舐鼎来鸡犬，九转丹成变虎龙。","玉髓岂无金液鍊，绛泥犹有紫苔封。","只今谁得长生术，独有南州鹤发翁。"]},{"t":"赠医士长律十首 其三 杏林","f":"七言律诗","c":["匡庐西望太霞边，种杏仙翁不计年。","花坞日高闻虎啸，芝田云暖借龙眠。","活人何惜千金药，积谷全胜万顷田。","回首紫薇山下路，万株团雪照晴天。"]},{"t":"赠医士长律十首 其四 菊潭","f":"七言律诗","c":["南阳谷口菊花潭，百尺清泉一味甘。","老去最宜延上寿，晚来犹可漱馀酣。","金英汎滥和云湿，玉液泓渟与海涵。","拟约柴桑陶处士，乌巾漉酒共清谈。"]},{"t":"赠医士长律十首 其五 龙藏","f":"七言律诗","c":["昔年闻有孙思邈，曾遇神龙授异方。","一夕珠宫开海藏，千金宝诀启天章。","波涛浩荡秋无际，云汉昭回夜有光。","往往到城骑一虎，山童时复佩青囊。"]},{"t":"赠医士长律十首 其六 兔臼","f":"七言律诗","c":["羿后何年奔入月，至今捣药兔长生。","一泓铅澒丹镕就，双杵云英玉琢成。","金粟树边秋有影，素娥台畔夜无声。","玄霜肯驻人间景，我亦乘桥出太清。"]},{"t":"赠医士长律十首 其七 芝田","f":"七言律诗","c":["闻说蓬莱海上洲，石田瑶草不知秋。","安期惯采千年药，徐市曾乘万里舟。","丹凤啄时清露下，玄龙耕处翠烟浮。","何当服食寻仙侣，直碾飙轮八极游。"]},{"t":"赠医士长律十首 其八 橘井","f":"七言律诗","c":["凿井仙翁本姓苏，后皇嘉树翠纷敷。","一泓碧甃涵云母，万颗金丸铸木奴。","德洽人心终有济，泉通海眼不曾枯。","我今亦抱文园病，脩绠何由转辘轳。"]},{"t":"赠医士长律十首 其九 蛇珠","f":"七言律诗","c":["隋侯当日见蜿蜒，径寸明珠射目前。","孚及豚鱼应有自，恩沾鳞爪岂虚传。","夜光何啻千金直，罔象徒探九仞渊。","闻道鲛人曾泣泪，岂容鱼目笑真圆。"]},{"t":"赠医士长律十首 其十 雀环","f":"七言律诗","c":["雀也当年知报德，至今闻者亦惊猜。","衔将白玉连环去，化作黄衣使者来。","不是抚摩全羽翼，安能翔舞出蒿莱。","金丸年少那知此，杨宝阴功位上台。"]},{"t":"题竹西小隐","f":"七言律诗","c":["拔剑王郎歌莫哀，竹西今见画图开。","好寻东阁题诗去，更约平山载酒来。","何处玉箫遗曲谱，谁家红药有池台。","十年一觉扬州梦，头白惭无杜牧才。"]},{"t":"次韵","f":"七言律诗","c":["风生长夏不鸣条，好雨知时沃翠苗。","龙女卷云归晚洞，鲛人推月上秋潮。","灵槎正近黄姑渚，仙驭初回绛节朝。","藻翰寄来苏病骨，夜凉神思亦迢遥。"]},{"t":"舟至大胜关","f":"七言律诗","c":["大胜关前津吏迎，南风猎猎动高旌。","鱼龙水底寒无梦，鸡犬山中夜不惊。","在德岂论天堑险，开邦正喜地图平。","一钩月挂西南树，卧听篙师欸乃声。"]},{"t":"过焦矶","f":"七言律诗","c":["中流砥柱压金鳌，上有神宫结构牢。","豪杰已随三国尽，精灵犹占一山高。","鸡鸣海树朝迎日，豚挟江风夜涌涛。","沿月棹歌祠下过，采蘋无计奠春醪。"]},{"t":"番湖舟中","f":"七言律诗","c":["番君湖上雨晴天，水气冥冥生白烟。","贺老无人惟酒舫，中郎有女识琴弦。","故园桃李春如海，远道风波夜似年。","笑指洪都无百里，今宵须并木兰船。"]},{"t":"左蠡","f":"七言律诗","c":["彭蠡之湖深复深，月黑夜泊天沉沉。","波涛时时鬼神会，风雨往往蛟龙吟。","神禹疏凿自开辟，篙师往来无古今。","千金一壶何足论，险易只凭方寸心。"]},{"t":"题铁柱观","f":"七言律诗","c":["何年铁锁贯神鳌，势压西南一柱高。","星象上通吴分野，石犀长镇海波涛。","百灵呵护天枢秘，八索纲维地轴牢。","谁信旌阳千载后，玄都重见种仙桃。"]},{"t":"赠铁柱熊道纪","f":"七言律诗","c":["鹤发仙翁养大还，紫霞为佩玉为冠。","琅函有篆丹书古，铁柱无尘宝剑寒。","凤阙恩从天上赐，龙宫方向月中看。","我来欲问长生术，一曲空歌月满坛。"]},{"t":"次徐指挥韵","f":"七言律诗","c":["贤王开国树旌幢，上将西来镇大江。","天上麒麟今有几，斗间龙剑本成双。","歌回金缕风生席，读罢青编月到窗。","赖有麻姑酒价贱，兴来何惜玉为缸。"]},{"t":"松花饼","f":"七言律诗","c":["黄云扫尽挂猿梢，不待嵩阳道士教。","琥珀凿崖分石蜜，醍醐团雪出山庖。","宝方应似龙宫得，金屑何烦兔臼敲。","我亦明年寻惠远，采花同访谪仙巢。"]},{"t":"邬子茶","f":"七言律诗","c":["邬子冈头紫笋生，寄来蓓蕾见高情。","茶经漫学卢仝赋，水品长怀陆羽评。","雪乳满瓯消午梦，风涛一榻起秋声。","兴来便欲逃禅去，绣佛灯前坐到明。"]},{"t":"柬僧纲住上人 其一","f":"七言律诗","c":["绀园台殿郁重重，云去云来不离峰。","鹤影每随天外锡，潮音长和月明钟。","一诗何足酬支遁，三笑于今识远公。","昨日分茶谢相访，绝胜白绢寄斜封。"]},{"t":"柬僧纲住上人 其二","f":"七言律诗","c":["午榻春烟试石茶，老禅定起具袈裟。","花飞丈室天垂雨，日出东湖地涌沙。","香积有厨分乳酪，藏真无帖扫龙蛇。","梦中犹记相逢处，徐孺亭前一径斜。"]},{"t":"过南昌县学柬颜司训","f":"七言律诗","c":["徐孺宅前湖水东，隔溪遥见素王宫。","当阶树影风帘碧，近浦书声雨烛红。","宝剑每瞻南斗气，罗衣初试舞雩风。","多情赖有颜夫子，相见无言意已通。"]},{"t":"答颜司训见寄次韵","f":"七言律诗","c":["神仙中人不易得，高士亭前相见时。","碧色湖波春浩浩，绿阴门巷昼迟迟。","閒临醉草池皆墨，老拥皋比鬓已丝。","海内知音今有几，黄金端合铸钟期。"]},{"t":"林溪","f":"七言律诗","c":["溪上青林林下溪，南州卜隐草堂低。","水生酒舫高过屋，花落樵径净无泥。","邻翁把钓得春鲤，童子煮茶闻午鸡。","白头也欲采芝去，好在洪崖丹井西。"]},{"t":"寄杭州侯少府","f":"七言律诗","c":["小楼听雨客京华，一月春阴勒杏花。","泥没长途官马滑，风吹深巷酒旗斜。","青云北阙初承诏，白首西江正念家。","寄谢钱唐秋月色，好分光采照天涯。"]},{"t":"赠道士","f":"七言律诗","c":["道士诵彻蕊珠经，云裳月佩风泠泠。","养生自鍊千岁药，劝客每倾双玉瓶。","松间清籁作琴响，竹下嫩凉催酒醒。","知子能弹广陵散，更约月明来一听。"]},{"t":"题张文显凝清轩诗卷","f":"七言律诗","c":["凝清轩中好赋诗，尽收清气入诗脾。","千古万古不常有，一人两人今始知。","竹里煎茶风动处，琴边放鹤月来时。","更歌孺子沧浪曲，著我临流照鬓丝。"]},{"t":"新春有作","f":"七言律诗","c":["轩辕吹律凤凰台，春满乾坤绝点埃。","一夜星随天左转，八方风自日东来。","草痕向暖安排动，花信迎阳次第开。","白发野人瞻气象，却从云采望蓬莱。"]},{"t":"苍雪堆","f":"七言律诗","c":["种得琅玕三百个，当窗飞翠不曾乾。","润浮石榻常疑雨，清逼田衣故作寒。","开径何烦童子扫，敲门只许故人看。","若为消得南州热，借我吹笙坐碧坛。"]},{"t":"京中七夕","f":"七言律诗","c":["天近蓬莱暑渐凉，满城月色白于霜。","遥怜此夜双星会，只隔明河一水长。","灵鹊有桥通碧落，綵鸾无字到家乡。","定知慈母青镫下，暗卜蛛丝坐北堂。"]},{"t":"七夕书怀","f":"七言律诗","c":["月临南斗夜生凉，见月令人忆故乡。","碧海青鸾空有信，银河乌鹊竟无梁。","二千里外双星会，十二时中九曲肠。","自笑白头甘守拙，错将工巧擅文章。"]},{"t":"题金粟轩","f":"七言律诗","c":["阿翁手种黄金粟，闻说灵根出广寒。","此树想从天上得，何年移傍屋前看。","故山丘垄多乔木，若个儿孙见牡丹。","好在百年无剪伐，露花凉叶自团团。"]},{"t":"题汉水幽居","f":"七言律诗","c":["张公江海每思归，看画令人说汉溪。","清梦每经渝水北，白云多在仰山西。","脱绷稚笋年年长，返哺慈乌夜夜啼。","最忆春明花烂漫，版舆随处蹋青泥。"]},{"t":"题听雪窝","f":"七言律诗","c":["天寒虚室夜萧萧，谈坐蒲团转寂寥。","著树似兼风叶堕，窥帘应杂雨花飘。","色从白处分明见，声入空中即渐消。","明日庭前询侍者，不知若个立齐腰。"]},{"t":"月食","f":"七言律诗","c":["四月十五二更初，海上涌出白蟾蜍。","圆于止水悬金镜，阙若清冰碎玉壶。","黑处山河还复正，明边桂树不曾枯。","中庭额塌泥沙拜，虮虱微臣本姓卢。"]},{"t":"敬赐内侍竹溪道人蒋康之诗卷","f":"七言律诗","c":["昔闻蒋诩开三径，今见此君临一溪。","月色倒流天上下，秋声多在屋东西。","路从翡翠巢边过，诗向琅玕节下题。","好约仙人吹凤琯，高閒长共碧云栖。"]},{"t":"和友人纪行之作","f":"七言律诗","c":["燕山雪花大如手，飞绕天家十二阑。","白战诗成貂帽湿，黄封酒醒毳袍单。","巴人谁和阳春曲，学士应分小月团。","年少相如最能赋，梁园宴罢日三竿。"]},{"t":"送吴孝廉分题得石井","f":"七言律诗","c":["白石井头桐始花，山瓢春水当流霞。","仙人缩地今无术，孝子看云正念家。","声转辘轳肠欲断，梦回天柱路应赊。","好分一勺高堂上，驻景还同葛令砂。"]},{"t":"挽祭酒胡俨母徐恭人","f":"七言律诗","c":["萧峡何年挽鹿车，恭人懿德满京华。","泷冈表出欧阳氏，太学文传祭酒家。","夜月琴床悲别鹤，秋风宰树感慈鸦。","梁园一掬宗人泪，洒向北堂萱草花。"]},{"t":"赠庸信庵上人建卢大夫桥","f":"七言律诗","c":["大夫桥头波浪阔，行人那得渡浮杯。","骑将碧海鲸鱼去，移得青天螮蝀来。","野旷最宜呼月出，水高应不碍帆开。","岂无一片三生石，著我谈空坐碧苔。"]},{"t":"寄奉祠李光","f":"七言律诗","c":["与公契阔已多时，愧我耽诗老更痴。","失马翁归还自得，亡金郎在不须疑。","曾从塞北多奇约，重向江南话所思。","一曲阳春真寡和，琼瑶何以谢相知。"]},{"t":"早朝诗次韵","f":"七言古诗","c":["千官听彻午门钟，咫尺蓬莱有路通。","山色渐分宫树碧，日华微映御袍红。","九成乐奏龙光近，万岁声传虎拜同。","湛露润浮天上下，卿云晴绕殿西东。","舍人书诏临丹扆，内侍传宣出紫宫。","冉冉炉烟凝几席，重重花影转帘栊。","时当元首赓歌际，春在康衢化育中。","已睹文章资黼黻，更思旒纩蔽明聪。","岂无良牧如龚遂，应有儒臣得马融。","想见朝回封事少，上林吟遍百花风。"]},{"t":"送李山人还富春","f":"七言古诗","c":["北山佳气翠冥冥，南渡衣冠识地灵。","龙穴云归晴作雨，蚌潭珠出夜如星。","承闻先世传遗泽，复见诸孙守一经。","空谷白驹何皎皎，前朝宰木尚青青。","骑鲸仙去长怀李，化鹤人归或姓丁。","进履好探黄石洞，吹笙还过赤松亭。","正期岁晚寻瑶草，应许天寒寄茯苓。","他日鸣驺来入谷，待余重勒草堂铭。"]},{"t":"题李草堂墓志","f":"七言古诗","c":["螺川东去水冥冥，落日乌啼宰树青。","三径就荒陶令老，众人皆醉屈原醒。","锦袍仙去空怀李，华表归来或姓丁。","遗墨尚存封禅稿，高风谁筑聘君亭。","如公我亦悲先哲，有子天教得宁馨。","百世幽光应不泯，草堂长近少微星。"]},{"t":"送岁贡生","f":"七言古诗","c":["九重宫阙倚天开，丁卯年中贡士来。","晴雪半消鳷鹊观，春风先到凤凰台。","成都司马真能赋，太学何蕃信有才。","仙仗趋朝联鹭序，神珠照乘出蛟胎。","焰光二丈应烧杏，离思重歌当折梅。","忠孝致身须努力，泰阶平处是三台。"]},{"t":"闰月九日拟邀秫庄清友","f":"七言古诗","c":["今年九日两登高，小雨生寒著苧袍。","拟约故人将进酒，空怀吏部左持螯。","治安有策长沙贾，投老无钱处士陶。","万顷沧波鸥在渚，九天清露鹤鸣皋。","安排节物饶佳况，断送生涯藉浊醪。","心悦故交真有托，足闻空谷可能逃。","多才岂愧凌云赋，清论须焚继晷膏。","朝日团团行苜蓿，秋花采采胜绯桃。","盘餐未必兼熊掌，文采于今见凤毛。","奇绝千年金莫铸，歌长一曲茧频缫。","鹧鸪香暖炉堪爇，鹦鹉杯深手共操。","漫道太行多覆辙，从教沧海足惊涛。","萧萧短发惭乌帽，秩秩初筵叙燕毛。","学圃一经甘寂寂，词源三峡任滔滔。","可容行李催归棹，须看真珠压小槽。","古往今来同酩酊，风流端合属吾曹。"]},{"t":"送上竺隐箕山法师","f":"七言古诗","c":["五天竺国前朝寺，八十三年出世僧。","月下眼能看细字，云中手不拄枯藤。","天厨甘露朝朝饭，丈室生花夜夜镫。","鹿苑證成无上觉，牛车说破最初乘。","春深又送花间鸟，湖水都消雪后冰。","明日远山遥在望，上方台殿翠层层。"]},{"t":"送灵隐明性庵禅师","f":"七言古诗","c":["西还只履已多年，一派曹溪有正传。","涌出上方为宝所，飞来小朵落青天。","献珠龙去长听法，合掌狐来或问禅。","麈尾暂停云外锡，袈裟又上月中船。","松华饼试清明后，石鼎茶分谷雨前。","无计可留支遁马，有诗须寄薛涛笺。"]},{"t":"葛洪丹井","f":"古风","c":["吾闻句漏仙翁之丹井，乃在紫微之阳东山之顶。","仙翁丹成去不归，但见一泓寒碧涵秋影。","当年仙翁鍊丹砂，呼吸沆瀣餐朝霞。","陶镕日月精，鍊冶紫河车。","玄液化白雪，真胎结黄芽。","一朝骑龙去，翱翔太清家。","遗此百尺井，千古令人嗟。","辘轳无声石苔紫，子规啼老长松花。","我来汲井凌绝顶，夜半飞出黄金鸦。","直疑此水接东海，上通银汉之灵槎。","灵槎迢迢贯明月，汉使西回持绛节。","矫如黄鹄摩晴空，何待金丹蜕凡骨。","酌以丹井水，载歌仙人篇，永言保之合自然。","勿因离别损颜色，此水可以期长年。"]},{"t":"松云歌","f":"古风","c":["我思仙人乃在玉尘金鳌之两峰，以松为巢云作宫。","白云松下来，夭矫如飞龙。","仙人骑云与天通，朝游蓬莱暮崆峒。","东分断鳌足，西擘三芙蓉。","兴来醉泼金壶汁，元气淋漓鬼神泣。","八窗虚明白日寒，万壑㟏岈翠涛湿。","昔年曾画匡庐山，置我采药山之间。","别来仿佛三十载，杏花落尽青春閒。","昨日相逢卧云者，因之欲访长松下。","白云悠悠江海空，瑶草金芝共谁把。","山中之人招不来，琥珀夜光生紫苔。","天寒茯苓傥可寄，与子跨鹤登瑶台。"]},{"t":"送周应常归馀杭","f":"古风","c":["大涤洞与华阳通，中有许郭仙人踪。","青山九锁翠蛟舞，明月孤悬天柱峰。","雷渊子，双青瞳。","颜如丹砂发如漆，呼吸沆瀣凌空濛。","手把五色金芙蓉，翩然骑云朝九重。","天寒猿鹤久相待，诏许飞佩还山中。","太乙真人坐莲叶，银汉无声波帖帖。","滴露轩前夜气清，石函云冷青瑶笈。","还山二月春风来，玉屏洞口桃花开。","寄谢山灵傥相许，吹笙弄月登萧台。"]},{"t":"题敬赐内侍桂岩道人李吉之天香深处手卷","f":"古风","c":["吹君玉龙管，酌我金螺杯。","听我歌天香，天香何处来。","广寒宫阙高崔嵬，黄金布地琼作台。","吾不知当时老桂树，是谁亲手栽。","但见月圆则荣，月缺则摧。","九十万里顾兔东西走不息，岁岁花从天上开。","请君花下饮，一笑舒君怀，百年此兴能几回。","霓裳歌，羽衣舞，足蹋虹桥上天府。","天香吹人千万古，愿持此香苏下土。"]},{"t":"题敬赐内侍兰谷道人蒋怡之诗卷","f":"楚辞体","c":["有美人兮山之阿，牵白云兮被女萝。","抱凤凰之绿绮，濯冰弦于绛河。","倚丹崖兮饮山渌，采幽芳兮结纕服。","挹清风于九畹，弹广陵之一曲。","思美人兮不可招，何以报之瑛琼瑶。","含奇芬兮承湛露，期永好兮同逍遥。"]},{"t":"题敬赐内侍鞠大亨梅花洞天诗卷","f":"七言律诗","c":["我闻罗浮古洞天，缟衣玉骨皆神仙。","南枝北枝自冷暖，古月今月同清圆。","开元供奉酒一斗，孤山先生诗几联。","青鸟窗閒莫啼梦，且容老子弄婵娟。"]},{"t":"望庐山阴雨不果","f":"楚辞体","c":["平生爱写庐山图，今朝始识庐山面。","山灵怪我来何迟，涌出白云千万片。","千片万片云重重，咫尺隔断香炉峰。","东南五老望不见，倏忽下上随飞龙。","虎溪三笑今何在，惠远东邻渺烟霭。","临风大叫谪仙人，九叠屏前定相待。","若有人兮山之颠，手翻银河下青天。","金芝瑶草傥可采，我亦跨鹤来林泉。"]},{"t":"寄题万峰阁为越僧作","f":"楚辞体","c":["巍巍乎万峰之阁兮，乃在句践之国梵王之家。","不知何年始开辟，但见层峦叠嶂涌出无数金莲花。","想当大禹疏凿际，神输鬼运纷如麻。","衔石走精卫，补天驱女娲。","星联棋布互参错，奇形诡状何㠂岈。","踞者如虎豹，蟠者如龙蛇。","断者如截肪，峭者如削瓜。","穹然古佛顶，螺髻青鬖髿。","纷若越女鬟，一一盘宫鸦。","又如祗王园中宝树下，诸天幡盖杂遝相纷拿。","娑竭珠宫夜光白，明月照海皆金沙。","我闻胜景有如此，恨不一往乘飙车。","上人山中来，笑语生烟霞。","中藏万峰秀，文采摛天葩。","风流远接许询辈，佳句往往传中华。","昔闻支道林，好骑神骏騧。","历览山水窟，逸思令人嗟。","我诗无根蒂，政如焦谷芽。","安得从师极登眺，东游云门与若耶。","寄谢山灵勿相拒，待我一饭餐胡麻。"]},{"t":"过吕梁洪次韵","f":"古风","c":["吕梁自从开辟来，中有崩崖转石之惊雷。","不知何年鬼斧凿，一水怒触龙门开。","故人张帆涉幽险，月出船头金滟滟。","重瞳霸气已丘墟，百谷安流会江汉。","徐州城外山重重，戏马台上生悲风。","古来豪杰俱寂寞，但见水光云影涵冲融。","还酹波神一杯酒，三弄琼箫吹龙友。","秋风吹梦过江南，总是离亭折杨柳。","芦花霜白雁秪更，天鸡啼罢东方明。","棹郎捩舵唱歌去，众中谁解吴歈声。","人生壮志在万里，大鹏簸荡东溟水。","蓬莱石上有金鳌，手把丝纶共谁理。"]},{"t":"月中桂子","f":"七言古诗","c":["广寒宫殿重重开，天妃舞镜登瑶台。","婆娑飞轮上裴回，玉龙吐涎云外来。","灵鹫峰高天不老，琅玕无光琪树小。","赤城洞口如飞沙，碧桃藏春不敢花。","直疑仙人紫霞会，灵风吹堕真珠佩。","猿童蹋云扫空阶，天鸡惊起双喈喈，綵鸾珑珑呼不回。"]},{"t":"和嵩岳行","f":"古风","c":["吾闻三十六峰青嶙峋，仙翁价重连城珍。","金堂石室不可到，紫芝瑶草长清新。","自笑青春探灵秘，望断蓬莱五云气。","不是丹丘紫凤凰，按图空想千年瑞。","使君看山双眼青，题诗曾寄山之灵。","吹笙每招王子晋，采药或遇安期生。","锦袍旧是龙门客，不怕山灵夜呵责。","有时笑接浮丘公，有时吹笙坐盘石。","醉骑黄鹄登天门，濯足银河清绝群。","鸿龙玉狗森左右，大叫阊阖排青云。","紫皇授以瑶台月，照见迎风玉壶雪。","鹤梦寥寥蕙帐空，幡然又与烟霞别。","黄河一千年一清，六龙在天当圣明。","河阳种得花满树，谁能解此春风情。","明当高附垂云翼，直上榑桑望朝日。","肯信东方有小儿，三偷阿母蟠桃实。"]},{"t":"立春雨中作","f":"七言古诗","c":["春云阴阴春雨作，今日迎春出东郭。","陌上青泥一尺深，雨打牛头湿牛角。","儿童奔走看春归，拾得春牛头上泥。","阿翁大笑向儿道，正应春头种田好。","呼儿买酒祀田神，大字搏泥写作春。","田鼠不生野无雀，有租纳官心即乐。"]},{"t":"题瞻云轩","f":"五言古诗","c":["迢迢东流水，悠悠思故里。","故里日夜思，中情无已时。","中情向谁言，白云在青天。","青天高无极，相望不踰尺。","慈乌知返哺，越鸟知南巢。","异乡非吾土，瞻云徒尔劳。","客从江上来，赠以春蚕丝。","愿织春蚕丝，裁为游子衣。","驾言服春衣，婆娑舞庭闱。","上以介眉寿，下以饮春酒。"]},{"t":"紫霞瓮歌","f":"七言古诗","c":["娲娥补天抟五色，化作昆崙一拳石。","神人巧斲秋水骨，玉臼敲丹碎蟾魄。","东方涌出玻瓈盆，九气凝结回鸾文。","天吴海若不敢受，中含万斛梨花春。","琼液流波散成绮，照见落花吹不起。","醉来大笑醯鸡天，吸尽长鲸百川水。"]},{"t":"春夜听何山人弹琴制乌夜啼曲","f":"七言古诗","c":["梨花月白春冥冥，城乌夜啼当二更。","白头老翁识乌语，挥弦弹作乌啼声。","初弹翩翩飞绕树，再弹哑哑栖不住。","雌雄引子复回翔，下上呼群自来去。","高逼天门清露寒，牵牛蹋浪银河乾。","低翻塞草黄云晚，秦女思家玉关远。","联联绵绵忽作行，恍然无声风满堂。","老翁拂袖入门去，海日杲杲生东方。"]},{"t":"瓢岩歌送人之金华","f":"古风","c":["高人爱瓢得瓢趣，在山出山皆乐处。","十年不酌山中泉，濩落江湖随所寓。","既不学洗耳翁，弃之不耐聆松风。","又不学悬壶老，卖药藏身以为宝。","朝骑华亭鹤，暮蹋碧海鲸。","身披紫绮裘，手提力士铛，与瓢倾倒如弟兄。","兴来唤明月，大瓢小瓢相与倾。","大瓢一饮累千觞，小瓢百觞亦不停。","明珠走盘落咳唾，谑浪好似东方生。","兀然一醉卧花下，月落瓢空还复醒。","春江水绿花冥冥，金华芙蓉天上青。","持瓢若饮双溪水，我亦相从来濯缨。"]},{"t":"张鍊师祈雨歌以赠之","f":"七言古诗","c":["蓬莱仙人谷神子，夜扣天关与天语。","玉坛三日走风霆，呼云得云雨得雨。","问之此是何人功，不归造化归太空。","盐官令尹恤民者，方寸默与天心同。","我田有秋农有饭，但愿今年租早办。","龙瓢马上倒天河，喜雨作亭功更多。"]},{"t":"过益阳渡","f":"七言古诗","c":["别肠刺刺弓弦急，展转车轮不停息。","正尔天涯忆故乡，一行过雁烟中没。","益阳渡头白发翁，野店压酒松花浓。","上船露坐待明月，月色正与家山同。","人生进寸还退尺，塞马既亡仍复得。","洛阳年少谪长沙，白也曾为夜郎客。","徐卿徐卿吾故人，寒谷偶被阳春恩。","此时应有还家梦，稚子壶觞正候门。"]},{"t":"鹊轩行","f":"古风","c":["阿母昔年生子时，灵鹊群飞庭树枝。","自从阿母生子后，一月一年来上楼。","人言鹊声能送喜，为报君家得贤子。","十龄能读书，二十走马青云衢，三十得官东海隅。","阿母骑鸾上天去，故巢几度空山雨，鹊声犹绕庭前树。","子今远游天一方，不见白头在中堂，但闻唼唼鸣朝阳。","唼唼复唼唼，风吹庭树叶。","叶落枝头还再生，安得母来闻鹊声。"]},{"t":"碧玉连环歌","f":"古风","c":["赠君芙蓉之宝带，佩以碧玉之连环。","宝带缠绵合欢意，连环宛转双虬盘。","双虬盘，无断绝，团团比似青天月。","月在青天缺复圆，我环长圆不曾缺。","人生离别当奈何，赠尔一曲连环歌。"]},{"t":"送富阳李孝子","f":"古风","c":["秦川之水东南流，中有孝子一叶之扁舟。","借问舟行向何处，家在严陵滩畔住。","严陵滩畔栖鹤村，阿母望儿长倚门。","儿归上堂母心喜，寸草曷报春晖恩。","儿有青囊旧时术，自信他人传不得。","得钱欲买冰上鱼，卜地翻䥴墓前石。","儿今何所愿，愿老严陵滩。","不愿麒麟卧高冢，但愿瓦棺?母山之间，千古万古子母安如山。"]},{"t":"白云歌","f":"古风","c":["白云在青天，浩荡凌高风。","丈夫志四海，飘飖无定踪。","君从冠冕山中住，云亦无心随所寓。","吴山越水接荆扬，总是当年栖息处。","九重荡荡天门开，一朝乘风朝玉台。","故山猿鹤无惊猜，从龙作雨还归来。"]},{"t":"题画","f":"七言古诗","c":["大山小山芙蓉开，云气远从天目来。","山中六月不知暑，双松如龙啸如雨。","矶头水深三尺许，水中石子清可数。","石子可数易见鱼，高人把钓心焉如。","五湖风高浪如屋，何人同唱沧浪曲。","沧浪曲欸乃歌细，雨有笠斜风有蓑，吾谁与归张志和。"]},{"t":"汉武词","f":"七言古诗","c":["通天楼阁排云开，仙掌露寒金作台。","八月一日王母降，七龙九凤相裴回。","手持玉桃献天子，此桃结实三千岁。","东方小儿窗间笑，此儿三偷入瑶岛。","帝欲种核留人间，服之可使长朱颜。","茂陵秋草今何在，回首云霞渺瀛海。"]},{"t":"题望云图为越人作","f":"楚辞体","c":["湛湛越江水胡不，一洗九曲之离肠。","英英越山云胡不，化为五色之衣裳。","儿今食禄天一方，隔江望云如太行。","中流一苇信可航，父兮母兮不得将。","春风红药花正好，不如阶下宜男草。","堂中之人长寿考，此图端比陈情表。"]},{"t":"题琴月楼","f":"古风","c":["白玉可斲明月轮，黄金莫铸知音人。","子期一去不复见，惟有明月长相亲。","有时月到弹琴处，月不能言解琴趣。","琴非有意招月来，月亦无心与琴遇。","我琴寥寥太古音，月色皎皎清人心。","世上知音有如此，铸之何惜千黄金。","吾闻山东李翰林，金尊有月无鸣琴。","又闻柴桑陶靖节，素琴有酒无明月。","何如有琴有月有浊醪，神交千载李与陶，遗世独立何其高。"]},{"t":"题渔樵问话图","f":"古风","c":["江可渔，山可樵，山头白云手可招。","出门黄尘浩如海，胡不归来共逍遥。","何人写此渔樵子，咫尺江山千万里。","船系松根双石头，山人伐木来相求。","相求未已还相问，问之不答心悠悠。","子陵何为而辞汉，太公何为而归周。","买臣何为而晚遇，屈原何为而远游。","持我修月斧，操君济川舟。","天子不知名，大臣不见收。","渔翁向樵还大笑，今古同生不同调。","富贵功名何足论，与君尽醉长倾倒。"]},{"t":"题楮衾歌","f":"古风","c":["任公子，钓鳌龙伯宫。","烂烂五色云，飞出槫桑东。","海若天吴失颜色，河东美人织不得。","并刀剪断紫霞绡，八茧吴蚕空自白。","仙人王子晋，骑鹤来人间。","手卷锦鲸去，东入蓬莱山。","相逢会稽楮，共听西窗雨。","满床蝴蝶花片飞，梦中笑杀秦川女。","何人视草白玉堂，青绫夜对官烛光。","岂如蓬莱山人醉眠日丈五，独拥八天溪藤霜。"]},{"t":"筑城歌","f":"古风","c":["隋有盐官城，汉无盐官城。","唐有盐官城，宋无盐官城。","荒城芜没知何代，唯有东流水长在。","蓬莱清浅半桑田，精卫年年塞东海。","前年无城禦边烽，去年无城机杼空。","今年长城高百尺，谁其主者陈元龙。","重门铁锁黄金钥，刁斗无声夜停柝。","七星挂城明月低，万户千门惨清角。","何当四海车书同，苍生乐育康衢中。","明年开城看歌舞，城南城北春花红。"]},{"t":"题白云山舍为桑孝子作","f":"古风","c":["欲知慈母心，磊磊高山石。","欲知慈母操，青青古岩柏。","阿母生儿才十年，空山别鹤悲离弦。","儿今读书母身健，绩麻夜坐明镫前。","父昔生儿愿儿好，儿心一寸春晖草。","母在山中父在天，结庐长在白云边。"]},{"t":"桃花马","f":"七言古诗","c":["吾闻古有穆天子，八骏西行日千里。","何年下浴瑶池泉，满背落花飞不起。","月氐贡入光明宫，天闲十二皆春风。","东方小儿拍手笑，曾识昆崙千岁红。","白玉凿蹄金络脑，一点明霞落烟草。","征南将军天上来，时人称是真龙媒。","房星照地春如海，会见论功朝玉台。"]},{"t":"舟过采石拟吊谪仙风雨所阻弗遂","f":"古风","c":["炮车云兴大风作，收帆夜傍沙洲泊。","春阴遮断蛾眉亭，不见蛾眉镜中落。","欲吊开元李谪仙，锦袍一去三千年。","如何古时月，不照今人船。","自从捉月上天去，不知月落归何处。","月照人间无古今，江流不断天沈沈。","乾坤清气古亦少，大雅遗音向谁道。","白也明朝知我来，放出蛾眉翠如扫。"]},{"t":"舟中醉歌示同舟友人","f":"古风","c":["歌越调，唱吴讴，南风吹过黄芦洲。","前船后船相逐起，联联翩翩鸟衔尾。","前船相开后船喜，不用愁风更愁水。","采石有酒江有鱼，买鱼沽酒歌呜呜。","歌呜呜，击唾壶，人间此乐曾有无。"]},{"t":"题铁柱观","f":"七言古诗","c":["鬼斧凿窍开洪濛，平地涌出蛟人宫。","地脉上与星河通，一勺活水藏神龙。","想当锻鍊昆吾铁，祝融嘘烟走列缺。","穹然一柱闭灵穴，万劫天风吹不折。","旌阳上天去不还，安得化鹤来人间。","西南地折锁连环，永镇王国安如山。"]},{"t":"题松竹轩","f":"古风","c":["苍髯丈人偃蹇而，瑰奇此君高节能。","配之平生共持金，石操晚岁不改冰。","霜姿闽南刘侯好清古，天风吹入洪都府。","半空清籁奏笙竽，九夏凉阴覆窗户。","吾闻松根生茯苓，服之可以延遐龄。","又闻竹间栖綵凤，一鸣可以开太平。","刘侯刘侯世所重，大才会入明堂用。","不然截作任公之钓竿，金鳌一掣沧溟动。"]},{"t":"题徐隐君清乐堂","f":"古风","c":["泉泠泠，石凿凿，在山泉清出山浊。","人生何如在家乐，南州高士不复作。","北冈有孙甘淡薄，卜居长年老丘壑。","东家买鸡鸡被缚，安识昂昂九霄鹤。","我来南昌古城郭，几度题诗寄江阁。","麻姑酒美鱼可斫，未登公堂同一噱，先遣飞廉寄寥廓。"]},{"t":"题义鹊图","f":"古风","c":["柬海有二鹊，相逐潮头飞。","一鹊忽堕水，羽翼何纷披。","一鹊回旋抉不起，唶唶叫群惊未已。","须臾二鹊东南来，挟之同入青云里。","嗟尔禽鸟尚同心，何况朋类不如禽。"]},{"t":"送罗生之吏部","f":"古风","c":["鲁阳莫驻西飞日，精卫莫填东逝波。","沧波无情白日短，奈此西飞东逝何。","南昌城东罗孝子，捧檄还家二亲喜。","一夜江头春水高，片帆又逐南风起。","儿有宜男草，种之北堂前。","儿有昆崙桃，介寿三千年。","朝盘鲤鱼白如玉，明年儿归当食禄。","白日可驻海可填，儿心报恩同昊天。"]},{"t":"东汾书舍","f":"古风","c":["吾闻天台之山四万八千丈，连冈叠嶂如游龙。","金鳌屹立东海上，东汾更在金鳌东。","开元谪仙好孙子，宦游卜得佳山水。","读书闻有宋诸郎，遗爱尚传唐刺史。","古人不复作，悠悠令我思。","至今东汾月，挂在珊瑚枝。","我来豫章城，邂逅龙门客。","示我东汾之画图，丹霞翠雾仙凡隔。","安得与子骑鲸鱼，拾得东海明月珠。","试问蓬莱花鸟使，弱水清浅今何如。"]},{"t":"题罔极诗卷","f":"七言古诗","c":["华盖山头白云起，孝子呼天泪如水。","梦隔庭闱四十年，心怀丘陇三千里。","白日短短云无根，有身莫报罔极恩。","寒食梨花一杯酒，几家坟上见儿孙。","儿今食禄司成馆，俯视长江流不断。","长江不断深复深，何如孝子罔极心。"]},{"t":"题樵云","f":"楚辞体","c":["请樵停斧柯，听我樵云歌。","问樵住何所，乃在山之阿。","朝樵林下风，暮樵谷中雨。","林风吹我衣，谷雨沾我履。","何如白云深处栖，采樵不离云东西。","有手自操修月斧，有足能蹋登天梯。","山头肤寸崇朝起，从龙化作天瓢水。","一洗八极黄埃空，随云复归岩壑里。","若有人兮被女萝，扳崖度岭无风波。","世间万事浮云过，樵云樵云奈尔何。"]},{"t":"赠揭学士孙和仲","f":"七言律诗","c":["剑江之水绿于酒，夜夜清光射牛斗。","龙泉太阿飞上天，宝气千年应不朽。","揭阳孙子玉无瑕，云是前朝学士家。","藏器待时须努力，岂无雷焕与张华。"]},{"t":"次韵","f":"七言古诗","c":["祈连山头落日低，黄云万里天冥迷。","江南已见雁北向，塞上遥闻乌夜啼。","南北相望春梦杳，可怜日月笼中鸟。","霜高沙碛剑衣寒，月堕穹庐角声晓。","忆昨公馆春茫茫，手援绿绮弹宫商。","得句共誇何水部，知音多识蔡中郎。","神交有道不可忘，至今翰墨留馀香。","丈夫岂无一掬泪，不学儿女情徊徨。","黄河之水东入海，别意更比河流长。","河中鲤鱼有书信，时复幸寄琼瑶章。"]},{"t":"寿容斋","f":"七言古诗","c":["铅花洗空霜倒飞，金鸦浴海迎朝曦。","蓬莱宫中青鸟使，衔得玉桃天上归。","东海仙翁紫霞会，碧落回风响环佩。","伶伦玉琯吹凤皇，夜半九地回初阳。","羲和缓辔红线长，群仙年年飞羽觞。","六甲明年重建子，六六周天自今始。"]},{"t":"题馀庆堂","f":"古风","c":["请以汉溪水，注我流霞觞。","奉君以瑶池千年之桃实，赠君以玉兔万杵之玄霜。","春风花开馀庆堂，鹤发倒映青铜光。","阿翁手种两松树，黛色已见参天长。","子今宦游天一方，膝下思见斑衣裳。","岂无双鲤鱼，路远不可将。","但有一寸心，直与汉水流汤汤。","汉水东流入东海，馀庆绵绵镇长在。"]},{"t":"巫山高","f":"楚辞体","c":["巫山高，高入天，峰头一一相钩连。","上有朝云万仞之飞鸟，下有暮雨三峡之啼猿。","有美人兮山之颠，风裳月佩秋娟娟。","悬崖历涧不可见，翠雾参差出宫殿。","须臾吹起大王风，朝云飞散暮雨空，依然十二青芙蓉。"]},{"t":"寿友人","f":"古风","c":["丹丘仙人头雪白，玉宇高寒栖不得。","天目之阳多翠微，却跨黄鹤江南归。","山田有秫涧有水，鹿车同挽青山里。","庞公以安遗子孙，足迹不蹋襄阳市。","少微之星白煌煌，直与南斗相低昂。","东方小儿骨未锐，玉桃亲见三千岁。","安得左持桃，右持觞，祝公寿，登公堂。","天台山高四万八千丈，愿公与山同久长。"]},{"t":"芝原为富春冯孝子作","f":"七言古诗","c":["大树将军之子孙，何年葬父灵山根。","仙翁骑鹤去不返，但见紫芝烨烨生。","灵原丛丛一抔土，上天应念儿心苦。","千年石室发幽光，得见灵芝如见父。","人言服之可长年，安得灵魄登飞仙。","芝生在地父在天，鹤归夜夜山之颠。"]},{"t":"题桂林荣遇图","f":"七言古诗","c":["白发刘郎江右住，高堂大字书荣遇。","借问何因得此名，向人指点门前树。","年年八月金粟开，云是仙翁亲手栽。","异本定从天上得，清芬应自月中来。","只今系马长安道，梦想故园秋色好。","匡庐青压九江深，翻笑淮南小山小。","草木之生关盛衰，百年培植当清时。","寄谢子孙毋剪伐，青云留取最高枝。"]},{"t":"金谷园","f":"七言古诗","c":["金谷园中春荡荡，四十里围红步障。","万斛明珠换绿珠，纤歌半落青云上。","刀击珊瑚碎玉飞，当时豪侠世所稀。","撞钟考鼓夜复昼，二十四友相追随。","一朝喋血河阳市，繁华总逐东流去。","鹦䳇明朝错唤人，梨花满地愁如雨。"]},{"t":"王子乔二首 其一","f":"七言古诗","c":["天上迢迢白玉京，仙人吹笙学凤鸣。","七月七日缑氏山，身骑白鹤来人间，遨游青天去不还。"]},{"t":"王子乔二首 其二","f":"古风","c":["王子乔，好神仙，呼吸日月凌云烟。","吹笙学鸣凤，遨游太清天。","翩然跨鹤来缑山，七月七日游其间。","空歌一曲綵云外，长谢时人去不还。"]},{"t":"相逢狭斜行","f":"古风","c":["相逢狭斜路，借问游何处。","男儿不恋家，西上长安去。","大车辚辚朝出关，小车已没云中山。","安得两轮生四角，远游不及还家乐。"]},{"t":"送人之京","f":"五言古诗","c":["夜闻秋雨声，朝发盐官城。","大帆夹双橹，长歌溯空明。","始经语儿溪，渐次鸳鸯浦。","手折芙蓉花，含情向谁语。","吴江渺烟树，七十二峰前。","三高祠下泊，酾酒晚凉天。","望月垂虹亭，枫桥少延伫。","寒山夜钟来，乡梦初回处。","鸟啼阊门柳，鹿走姑苏台。","笑指五湖水，鸱夷安在哉。","且酌惠山泉，还过惠山曲。","煮茶问陆羽，遗经有谁续。","风波不可渡，竟舞扬子津。","回车丹阳道，白日无停轮。","长揖大茅君，丹霞满空谷。","欲采松根苓，况乃严程趣。","逶迤遵广路，浩荡观龙河。","矫首丹凤阙，青云郁嵯峨。","贤臣四方来，剧谈尧舜学。","鸿毛遇顺风，脩鳞纵巨壑。","夫子天机深，常有饥溺心。","拟献金镜录，行陈大宝箴。","拂拭镜中霜，登朝未云晚。","怀宝固有时，勿念关山远。","愿为瑚琏器，为君登庙堂。","愿为松柏姿，为君充栋梁。","西风吹苧衣，执手情何极。","有使即寄书，无使长相忆。"]},{"t":"送人赴燕山","f":"七言古诗","c":["神仙中人不易得，三花云是神仙术。","一花一叶著奇芳，说与世人俱不识。","阿翁生子子生孙，南北医传良相门。","一色杏花随地种，百年大树至今存。","忆自六飞南渡后，玉带金鱼赐高手。","虢国曾闻扁鹊来，上池何待桑公授。","盐官故家遗庆长，埙篪迭奏含宫商。","东汉中郎知郭泰，长安女子识韩康。","仲也敲门来话别，大帆直指燕山月。","星汉遥通析木津，关山正及梁园雪。","紫塞霜高雁背寒，酒酣上马驼裘单。","一七神楼须报捷，早凭南使寄书还。"]},{"t":"题金罍半峰白云图","f":"楚辞体","c":["我酤酌金罍，遥望金罍山。","半峰不可见，乃在白云间。","它山岂无白云白，何言兹山有离色。","儿在天西母在东，千里看云两相忆。","吁嗟乎，金之罍兮不可以挹酒浆。","安得持之登北堂，注以阿母流霞觞。","醉呼仙人魏伯阳，授尔宝诀长生方。","母子相看颜色好，不劳望云悲远道。"]},{"t":"题汉水幽居","f":"楚辞体","c":["有地不可缩，有山不可移。","如何孝子心，日夜思汉溪。","汉溪水深清见底，中有鲤鱼丹砂尾。","白头慈母在高堂，汲水煮鱼甘且旨。","儿心愿如溪上泉，母身愿如泉中之青天。","天苍苍兮泉涓涓，天泉相依无极年。"]},{"t":"一勺泉","f":"五言古诗","c":["我池小于盆，中有一勺泉。","泓淳若无底，湛然见青天。","白云忽飞来，下上相回旋。","引领意无限，我心与之然。","粲粲黄金鳞，如藏九重渊。","数罟不相及，纵心濯清涟。","千古濠梁趣，于以乐长年。"]},{"t":"刘氏杀虎行","f":"古风","c":["刘平妇，夫戍零阳夜逢虎。","妇操白刃向虎前，宁与夫死不与虎同天。","夫死虎口虎亦归黄泉。","呜呼刘平妇，壮气烈烈垂千年。"]},{"t":"左顾龟","f":"古风","c":["馀不侯，放龟馀不溪上头。","龟行盘跚向中流，裴回三顾谢馀不。","黄金本是无情物，鳞爪感之思报德。","孚及豚鱼天弗违，不然何得三铸左顾龟。"]},{"t":"挂剑歌","f":"七言律诗","c":["延陵季子珊瑚钩，徐君见之心欲求。","千金之重价莫酬，季子以心结绸缪。","徐君在墓剑在腰，解剑挂树风萧萧。","人生知己古亦少，吁嗟延陵安可招。"]},{"t":"题山水次韵","f":"古风","c":["我昨梦入丹霞城，山中猿鹤夜不惊。","仙翁楼观在咫尺，白玉作台云作屏。","中有一人眉宇好，翳凤骖鸾碧云杪。","临风赠我琼瑶辞，朗若华星照秋昊。","平明起向画图边，梦耶非耶心惘然。","安期先生渡瀛海，一笑邂逅东南天。","别来未觉红颜老，世间万事邯郸道。","安得同登四万八千丈之天台，历览西华超东莱。","玉桃千岁傥可食，好寄麻姑书信回。"]},{"t":"题雁图","f":"古风","c":["一雁触罗网，群鸿中夜惊。","彼物尚如此，何况弟与兄。","芦花霜白天冥冥，水寒月黑祗长更。","岂不闻玄圃昆仑有琪树，凤凰长栖最高处。"]},{"t":"题松石斋","f":"古风","c":["抚长松，坐盘石，松头白云如茧白。","丹光夜夜穿树林，松下千年生琥珀。","长镵木柄古苔青，定拟天寒斲茯苓。","一曲瑶琴分半席，月明细和风泠泠。"]},{"t":"为云谷隐题谢周小儿卷后","f":"古风","c":["登山莫采连城玉，云卿有子万事足。","入海莫探明月珠，云卿有子知读书。","五男二女古亦少，卿家得之如得宝。","大者筋力强，幼者颜色好。","问之何能得如是，周郎家有长生草。","云卿食禄今八千，探囊谢医无一钱。","此文可比柳州传，报以远大非空言。"]},{"t":"赠魏将军歌归馀杭迎母","f":"古风","c":["魏将军，乃在碧海之东隅，身长七尺颇有须。","手提昆吾铁，照耀蛟龙居。","丹心报明主，日向辕门趋。","有家天柱下，白发暮倚闾。","将军起闻城上乌，夜夜返哺鸣相呼。","木兰之舟蓝笋舆，远迎阿母同欢娱。","西海有蟠桃，东海有鲤鱼。","南海有珊瑚，北海有明珠。","桃以延母千年之遐寿，鱼以荐母百味之行廚。","珊瑚妆母之宝带，明珠系母之罗襦。","歌呜呜，击唾壶，人间母子曾有此乐无。","呜呼，人间母子曾有此乐无。"]},{"t":"望思图","f":"五言古诗","c":["望云云在眼，思云云在心。","在眼云易见，在心云更深。","云栖向何处，不离墓前树。","儿心无时穷，云聚还复去。","思亲貌兴言，见亲插与圈。","近望见白日，远望悲黄泉。","儿今在远道，梦想楼居好。","还山会有时，洒饭琦上草。"]},{"t":"送云季昭","f":"古风","c":["昔闻轩辕纪官以云名，今见钱塘云卿之弟兄。","弟留江南兄在北，两地共坐塞坛青。","先生岂是悠悠者，气高不肯居人下。","黄河倒卷上青又，开口何曾让班马。","平生交义重如山，汪意倾情不作难。","男子当图匡济事，人生岂叹别离间。","屈捐九年何草草，杏花坛上青春好。","诸生队队占笼头，多士翩翩腾鹄表。","先生与予交有道，每一相逢即倾倒。","负郭宁无二顷田，恨身不向盥官老。","云大子，听戎歌。","买臣富贵年己过，功名到手苦蹉跎。","洪濛开天圣人作，神龙出河柝出洛。","先生奇才玉在璞，愿如阳城登太学。","天江水落秋冥?，送者既醉行者醒。","请从天上看除目，白雁前头须寄声。"]},{"t":"题望思图","f":"七言古诗","c":["苍梧九炭勿言远，不隔孤儿望乡眼。","洞庭七泽勿言深，不满孝子思家心。","孝子改山何所有，垄上乌啼白杨柳。","十年归梦夜宫铨，千里它乡寒食酒。","筑得楼居近基傍，空山落日暮云黄。","岁晏天寒赋归去，雪后北堂意草长。","春晖茫茫尺地老，一望一思何日了。","桃花溪上饭胡麻，愿母长年颜色好。"]},{"t":"代道士作","f":"古风","c":["钟呜钟，考胡豉，尊前试作胎仙舞。","金鳌背上三蓬莱，碧惠九见琪花开。","醉来人叶安期老，袖中笑索如瓜枣。","折花送子青云道，别后长令颜色好。"]},{"t":"题湘妃和韵","f":"七言律诗","c":["白月无声老蟾死，九黠螺璟堕秋水。","哀弦五十绕青空，晚霞明减苗席红。","泪痕夜泣幽皇中，翠华南巡信不通。","纸钱猎猎挂霜枫，五色云间回雨龙。"]},{"t":"十四日与友人月下共酌","f":"七言律诗","c":["好天良夜不易得，今宵月圆当二七。","呼儿举梧沼月饮，月落杯中写琼液。","杯行到手君莫停，明朝未卜阴与晴。","但愿花前同见月，夜夜长圆莫教阙。"]},{"t":"听沈童子弹琴歌","f":"古风","c":["沈童子，玉雪颜，年十四，弹猗兰。","手持三尺凤凰尾，南窗一拂南风起。","明珠落落走瑛盘，碧涧泠泠写秋水。","近传一曲度关山，变徵移商顷刻间。","落尽桐花三日雨，令人侧耳竟忘还。"]},{"t":"燕中老人歌","f":"七言古诗","c":["桐花半落南窗雨，三尺枯桐瘦蛟语。","燕山老人雪满颠，尊前相见说当年。","向人解唱清平调，玉碎昆崙凤凰叫。","一声飞空过綵云，此曲不许人间闻。","尔当更为歌一阕，赠示西湖歌明月。"]},{"t":"题李生环玉轩","f":"古风","c":["李公子，来自西昆崙。","于阗河中白石子，何年移植苍山根。","碧云四合不见日，入窗空翠凉纷纷。","得非伶伦氏，采之贡轩辕。","轩辕台上调六琯，吹得凤凰五采相腾骞。","凤凰城中凤之穴，结巢下啄青琅玕。","李公子，何翩翩。","伯也如圭璋、如璠玙，何不披腹排天阍，森然玉笋联朝班。","不然借我截为任公之钓竿，一掣海水金鳌翻。","明年二月春水浑，我当挐舟扣卿门。","香风堂上振环佩，春雨阶前罗子孙。","卿当赠我青瑶琨，何以报之云锦文。","卿家令弟未相见，寄谢此君须会面。"]},{"t":"鹊巢行赠博溪姚氏","f":"七言古诗","c":["姚家溪南有高树，双鹊飞来复飞去。","年年结巢生好雏，雏大还来故巢住。","主翁朝出见鹊飞，主翁暮归见雏栖。","鹊声日报主家喜，主翁不惜高树枝。","树大枝高鹊巢在，骤雨颠风终不改。"]},{"t":"送黄千户还台州卫","f":"古风","c":["天台山，高入天，此地自古多神仙。","谷城黄公好孙子，豹略龙韬有如此。","朝餐赤城之紫霞，夕饮丹池之玉醴。","今年分守盐官城，天风袅袅吹华旌。","星河万里入东海，岛屿不闻刁斗声。","方秋复上天台去，即是桃花旧时路。","华顶峰头月正圆，依然挂在珊瑚树。","盐官父老纷如云，出城走送黄将军。","鸣笳叠鼓动离思，一路好山相送迎。","唱吴歌，劝吴酒，十里一亭，五里一堠。","天台山高入南斗，将军之名同不朽。"]},{"t":"题苏武还乡图","f":"古风","c":["北风何烈烈，孤臣持汉节。","萧萧匹马鸣，洒泪河梁别。","李陵台北望关山，十九年中一日还。","归拜茂陵松柏下，乡人惊见鬓毛斑。","汉兵万里穷沙漠，遣使和戎惭卫霍。","留得千年太史书，中郎将在麒麟阁。"]},{"t":"送百户张文胜之台州时营造城门","f":"古风","c":["张将军，乃是留侯之子孙，妙年壮气凌青云。","而翁奋迹龙虎卫，从戎万里天南去。","将军世禄袭奇勋，分镇夫差射潮处。","身骑骏马白雪毛，手提三尺昆吾刀。","天吴海若不敢动，冯夷伐鼓回秋涛。","海昌城头鸣夜柝，海阊门是将军作。","我识平生一片心，露写金盘冰出壑。","昨日城门开，将军跃马来。","今言出门去，驾言上天台。","天台山高四万八千丈，明月挂在琼台上。","回光还照海昌城，夜夜东西两相望。"]},{"t":"题沅陵朱指挥蒲萄瓜图上有天历之印","f":"古风","c":["博望昔使西南夷，蒲萄瓜实何离离。","传来中国数千载，天历画师曾写之。","沅陵将军好事者，此图本自苍梧野。","大宛分种及燉煌，何异按图求骏马。","吾闻蒲萄可酿酒，瓜瓞能延年。","方今王化被八埏，将军将军今张骞。"]},{"t":"送彭仕贞归涟川省亲 其一","f":"楚辞体","c":["岸芷兮汀兰。","风萧萧兮露漙漙。","彼美人兮于焉盘桓。","山川悠悠兮路漫漫。","嗟鸿雁兮隔云端。"]},{"t":"送彭仕贞归涟川省亲 其二","f":"楚辞体","c":["汀兰兮岸芷。","风萧萧兮露瀰瀰。","彼美人兮于焉栖止。","山川迢迢兮路千里。","嗟鸿雁兮隔云水。"]},{"t":"送张皋百户之京","f":"古风","c":["张将军，真丈夫。","矫如冲霄决云之快鹄，捷如追风掣电之神驹。","昔年倚剑医无闾，披甲上马擒单于。","论功分镇东海隅，紫气直贯蛟人居。","前年手把金仆姑，白日射杀三于菟。","去年捕贼黄道湖，绿林豪客一扫无。","张将军，才且武，奏鸣笳，喧叠鼓。","杏花团雪风雨晴，东风夹道吹高旌。","我徒我旅马前拜，共爱将军如父兄。","长安道上听马声，愿留将军再守盐官城。"]},{"t":"祷雨有感","f":"七言古诗","c":["去年六月天不雨，农家到处忧禾黍。","县公一念格天心，三尺甘霖苏下土。","今年不雨夏徂秋，县公恻怛农心忧。","西潭朝乞白龙水，东井暮檄乌龙湫。","四山云兴龙出穴，一夜滂沱洗炎热。","县公有禄民有租，喜雨亭成碑可揭。","使天雨玉复雨珠，饥不可食寒不襦。","我今歌咏丰年屡，大书特书不一书。"]},{"t":"长平箭头歌","f":"古风","c":["战长平，四十万人同日坑。","古苔蚀血铜花青，千年金簳摧白翎。","空遗黄金镞，不射秦时鹿。","西出咸阳门，哀哀鬼夜哭。"]},{"t":"题罗浮仙人便面图","f":"七言律诗","c":["我有齐纨之扇面，大如青天之玉盘。","中画罗浮古仙子，风裳月佩如飞鸾。","十月江南花信早，孔雀屏前春浩浩。","愿持此扇朝暮看，一轮宝月长团团。"]},{"t":"贝宫夫人","f":"七言律诗","c":["海宫曈曈紫贝光，瑶妃叫月归龙堂。","金虬蜿蜒翼两傍，手弄真珠白煌煌。","天寒北渚采瑶芳，窈窕宛若惊鸿翔。","湘南老竹泣娥皇，二十五弦秋夜长。"]},{"t":"秋思","f":"七言律诗","c":["西山日没东山红，白蟾夜浴天河东。","望舒逸驾碾晴空，银床风叶堕疏桐。","美人团扇辞汉宫，流萤稍稍入房栊。","空闺捣练夜未终，关山梦长啼早鸿。"]},{"t":"赠峡川僧 其一","f":"七言律诗","c":["玉堂学士文章好，夙昔与师交有道。","朝罢挥毫写赠言，师也得之如得宝。","我亦前身支许流，十年不见紫薇秋。","白头未了看山债，安得杖藜同一游。"]},{"t":"赠峡川僧 其二","f":"古风","c":["吾闻紫微山，上应紫微星。","山中有僧宝，趺坐香华亭。","臞然玉立双瞳青，阅尽西方华藏经。","潮音动地天籁作，海上鱼龙皆出听。","灵鹫西来有黄鹤，重重无尽开楼阁。","月华先照妙高台，光明云绕加沙角。"]},{"t":"题了庵道人魏","f":"古风","c":["吾闻伯阳鍊丹金罍山，丹成上天去不还。","芙蓉伏火绛泥冷，空有宝诀留人间。","神仙中人不易得，今见其孙有仙骨。","手把参同一卷书，此书云是传家物。","往年骑鹤上玄都，袖有龙虎真人之画图。","云窗雾阁在咫尺，万里何必寻方壶。","归去西湖饮山渌，一榻了然心自足。","琪花满地雨声寒，为尔高歌洞天曲。"]},{"t":"题王继贤山浦楼诗卷","f":"七言古诗","c":["丰城客子王季友，复有云仍继其后。","我来五载寓钟陵，每想凭高摘星斗。","楼居宛在城之西，中有百尺青云梯。","西山南浦望中见，飞云捲雨天暝迷。","滕王高阁今何在，唯有江山留胜槩。","昨夜神龙挟雨来，洗出波斯万螺黛。","我欲笑拍洪崖肩，飘然驾鸿凌紫烟。","俯视东溟一杯小，门外黄尘空扰扰。"]},{"t":"题王得贤槐阴堂诗卷","f":"古风","c":["三槐何郁郁，云是晋公栽。","自从栽槐后，二郎登上台。","后世佳孙子，买地亦栽槐。","我愿子孙多种德，莫负当年王相国。"]},{"t":"种葵","f":"七言古诗","c":["东园种葵葵叶长，中有寸心倾太阳。","去年采葵花萼少，今年斫葵根本伤。","但得中天太阳在，葵根纵伤心不改。"]},{"t":"采兰","f":"楚辞体","c":["陟幽涧兮掇崇兰，葛藟藟兮路巑岏。","思美人兮泪汍澜，心摇摇兮不能餐。","采芳兮寄远，望佳期兮日晚。","日云晚兮霜露多，兰兮兰兮奈若何。"]},{"t":"题马图","f":"古风","c":["玉花骢，气如云，画史只数曹将军。","将军画骨不画肉，韩干画肉神不足。","此图与曹略相似，逸气雄姿有如此。","何当掣断青丝缰，任渠蹴蹋天河水。"]},{"t":"题雪心上人画梅","f":"古风","c":["不见雪心人，铁心花更好。","雪心人写铁心花，京路缁尘向谁道。","夜深天女散花来，缟衣飞下琼瑶台。","铁心如石不可转，雪心如玉浑无埃。"]},{"t":"送人之京","f":"七言律诗","c":["乌啼山头日杲杲，丁兰井上桐英老。","徵书催起孝廉船，慈母倚门儿在道。","扬子江边多鲤鱼，一日两潮须寄书。","五月临平藕花发，临风送别意踌躇。"]},{"t":"送张税使","f":"五言古诗","c":["朝看长安花，暮折长安柳。","柳条鹅色黄，映我杯中酒。","君车上天去，我笠归山中。","今朝一分手，他日还相逢。","相逢须下车，相见须下马。","有使过长安，寄书虹桥下。"]},{"t":"小姑","f":"古风","c":["漠漠山隔雾，冥冥水涵天。","舟人起相报，行过小姑前。","推篷问姑姑不语，不省姑年今几许。","姑云独立大江滨，一生不蹋名利尘，愧尔东西南北人。"]},{"t":"送临海张司训","f":"古风","c":["天台山高四万八千丈，我昔飞梦游其间。","天鸡二唱海色动，琼台银阙高巉碞。","留侯之孙江海士，磊落襟怀有如此。","三年把钓掣金鳌，文采珊瑚湛秋水。","子居东越我句吴，一朝邂逅青云衢。","得鱼宾馆休弹铗，挟策王门且曳裾。","二月江波绿如酒，我亦张帆大江右。","洪崖山顶望春晴，一度相思一回首。"]},{"t":"赠别","f":"七言古诗","c":["正月二月春风来，桃花李花犹未开。","故人酌我一杯酒，恰似汉水蒲萄醅。","邂逅关西好孙子，磊落奇才有如此。","况有能诗何水曹，尊前谈笑清风起。","扬子江头春水生，一帆东指盐官城。","明朝我亦南昌去，长倚香炉望晚晴。"]},{"t":"落星石","f":"古风","c":["落星石，何磊磊。","既不补青天，又不填沧海，屹立中流竟何待。","银河一水夜迢迢，胡不上天横作桥。"]},{"t":"送万玉润往杭州","f":"古风","c":["朝看玄都花，暮折洪都柳。","笑拍洪崖肩，醉酌麻姑酒。","槐里堂上好弟兄，去年相别凤凰城。","却怜春草池塘梦，飞过南州孺子亭。","浩饮酣歌复相见，白头顿觉身强健。","此地岂无新相知，新知何如故交面。","伯也买牛归力田，仲也又上东吴船。","我家正在南斗下，卜筑草堂沧海边。","荷叶圆时君定到，一段离情向谁道。","稍待秋风白雁来，便中先寄乌纱帽。"]},{"t":"梅竹轩","f":"七言古诗","c":["徐卿自是麒麟驹，当轩种树玉不如。","雪后疏花映脩竹，倚竹看花仍读书。","缟衣仙人心似铁，翠袖天寒更清绝。","岁晚能全金石交，平生不改冰霜节。","迩来将跨葛陂龙，翻然直上珠崖峰。","与卿别后相思处，好在黄昏明月中。"]},{"t":"题扇赠万玉立","f":"七言律诗","c":["枇杷雨足风日清，故人别我豫章城。","相思一日复相见，使我白发生千茎。","章江碧树三十里，马蹄蹴蹋青云起。","问谁此地最知心，槐里堂中好兄弟。"]},{"t":"泮浦书堂","f":"古风","c":["上山逐翠羽，入海探明珠。","翠羽出南粤，何如阿翁筑堂儿读书。","翁昔有堂临泮浦，群山如龙青入户。","弦歌声绕五羊城，直把番禺作邹鲁。","仙梯曾蹑广寒宫，教铎来振东湖东。","昨者王门一相见，襟怀磊落生秋风。","何当借我端溪砚，醉墨淋漓写诗卷。","生男但学梁伯鸾，翠羽明珠何足羡。"]},{"t":"送钟孟振服满之京","f":"楚辞体","c":["豫章城中头白乌，结巢树头生好雏。","一朝雏飞上天去，夜夜思归故巢树。","故巢树老何所依，葬乌在山雏乃归。","雏归哑哑不见母，三年泪洒坟前土。","雏今振羽挟青云，五色凤凰同作群。","上林有枝风日好，雏兮上天当及早。"]},{"t":"赠峡川僧","f":"七言律诗","c":["山色溪声语未终，朝天又拜紫泥封。","薝卜林中洒甘露，犀牛扇低扬清风。","我亦平生爱山野，师今共结东林社。","稍待枇杷春雪晴，乘閒来借支郎马。"]},{"t":"题夏圭画","f":"七言律诗","c":["三日大醉唤不醒，梦到九叠芙蓉屏。","两崖中断写飞瀑，匹练界破青天青。","高人似是陶与陆，坐听松声饮山渌。","觉来忽向画中看，回首秋云满岩谷。"]},{"t":"送继甫之京","f":"七言古诗","c":["尔祖文章妙天下，前朝声价高班马。","黄金有像铸莫成，白雪无弦和应寡。","我识若翁东海边，与子论交三十年。","茅屋萧萧坐风雨，布衣落落栖林泉。","九重诏下徵贤士，眼中之人得吾子。","凤鸟及时当一鸣，神驹堕地须千里。","官船十月渡龙河，有信还凭白雁过。","圣德如天无远近，除书早晚定如何。"]},{"t":"和朱彦伦教谕题山水障歌","f":"七言古诗","c":["蓬莱仙人居五城，六鳌戴山波不惊。","吮豪池头阎画史，扫雾驱烟移翠屏。","城中无山爱山好，凭轩迥出秋云杪。","似有青猿隔薜萝，直疑白鹤回穹昊。","此中逸兴浩无边，流水桃花心杳然。","括苍先生偶相过，想像石门之洞天。","石门洞口松花老，中有飞泉来一道。","丹崖拔地千仞高，玉笋凌空众山抱。","轩辕骑龙登上台，下视培塿皆蒿莱。","从今慎勿念乡里，一日看画须千回。"]},{"t":"扬子江阻风戏柬同舟诸友","f":"古风","c":["金焦两山青突兀，人言下有蛟龙窟。","飓风吹浪打船头，白日低昂天倒流。","安得列禦寇，三清八极同遨游。"]},{"t":"送王河泊","f":"五言古诗","c":["楚人歌竹枝，吴人歌白苧。","寄言黄帽郎，停舟向江渚。","江渚清涟漪，江风吹客衣。","三载一朝别，宁无千里思。","子乘道上车，我戴山中笠。","它日若相逢，还当下车揖。","雩阳好山水，三江接龙门。","愿托双鲤鱼，时时寄平安。"]},{"t":"望云轩与太学生焦思齐赋","f":"古风","c":["白云何重重，乃在蜀川之西、芙蓉之峰。","太学儒生念慈母，望云千里心忡忡。","朝望云在西，夕望云在东。","白云有聚散，此心无终穷。","儿昔在家时，手种宜男草。","阿母倚堂门，看花颜色好。","儿今两年不得还，梦里犹怀蜀道难。","秋风吹梦渡江去，飞绕太白峨眉间。","意匠经营劳画史，别情深似巴江水。","丈夫当学狄司空，读书莫忘孝与忠。"]},{"t":"题文昌图","f":"楚辞体","c":["星中之君号文昌，开辟造化分玄黄。","脩髯玉立颀而长，黼黻云汉昭天章。","驾风鞭霆游八荒，下视九点烟苍苍。","我欲从之翱且翔，翩然骑云朝紫皇。","勾陈玄武森在傍，呈琅玕兮沐恩光。","是用作歌孝友张，福我寿我期无疆。"]},{"t":"一天秋月为侯少府作","f":"古风","c":["仙人高居鹊华峰，手把五色金芙蓉。","骖鸾翳凤朝九重，翩然出入蓬莱宫。","轩辕上天骑白龙，群臣泣抱乌号弓。","八年鸿胪赞翊功，帝命出佑天南东。","凤城百雉盘脩虹，海水直与银河通。","仙人披锦袍，玉立冰壶中。","笑呼东方白兔公，周览八极氛埃空。","广寒三万六千户，借问谁持修月斧。","上界清虚隔风雨，应知照见颠崖苦。","儿寒思母衣，儿饥思母哺。","莫向人间照歌舞，为天作眼万万古。"]},{"t":"题兰雪轩","f":"古风","c":["鲁连解世纷，谈笑却秦军。","功成蹈东海，千载扬清芬。","皎皎天上雪，可以比高洁。","英英谷中兰，可以喻清节。","开元供奉李谪仙，神交倜傥知仲连。","一歌清风洒兰雪，读之使我神飘然。","凤凰山前隐居者，水石轩窗亦潇洒。","何时酌我葡萄醅，大笑长歌呼白也。"]},{"t":"望三茅山","f":"七言古诗","c":["吾闻句曲三洞天，此地往往多神仙。","三茅兄弟鍊金液，何年驾鸿凌紫烟。","大峰小峰青可爱，中峰更在丹霞外。","似闻碧落度笙箫，仿佛泠风振环佩。","停车一览心神开，忽有白鹤从东来。","明当借我上天去，手把芙蓉朝玉台。"]},{"t":"鸳湖舟中玩月四月十五夜","f":"古风","c":["团团三五月，挂在鸳湖东。","方舟泛流光，坐我青天中。","低头看月月在水，倒影嫦娥呼不起。","三更露下苧袍凉，恍然濯足银河里。","城南斗酒真珠红，与月共醉蛟人宫。","醒来月落不知处，张帆且趁清明风。"]},{"t":"题梅花村民为严司征作","f":"古风","c":["我昨梦入梅华村，清晨有客来扣门。","为言渝川一佳士，貌比玉雪清而温。","平生爱种罗浮树，仿佛罗浮洞中路。","积雪拥门三尺深，渔歌樵唱无寻处。","主翁杖策何逍遥，出门一色皆琼瑶。","缟衣仙人夜相访，绿毛么凤鸣交交。","寄言渝川士，何为自慕村野人。","调羹不入商家鼎，止渴不给曹公军。","萝窗一榻延素月，醉来自卧梨花云。","我今尚被微官缚，梦中犹想村中乐。","凭谁唤起何水曹，岁晚题诗寄东阁。"]},{"t":"梅月双清歌为宪司经历赋","f":"楚辞体","c":["罗浮仙人乃在琼瑶台，炯然玉立无尘埃。","乾坤清气不常有，白月飞上青天来。","常时见花不见月，一色梨云万株雪。","只今有月复有花，幕府芙蓉共清彻。","吾闻扬州何水曹，东阁赋诗清兴高。","又闻孤山林处士，诗名清似西湖水。","吁嗟今夜月，曾照古时人。","古今同一趣，花月长相亲。","冰为神兮玉为质，铁石心肠人不识。","会当弄影舞婆娑，花前重写双清歌。"]},{"t":"寿乐堂为潘上舍题","f":"古风","c":["陈绮席，进华觞，听我长歌寿乐之高堂。","堂中老人寿而康，金兰玉树森在傍。","世人但愿生儿早，儿未成人亲已老。","惟有潘家好弟兄，亲年未老儿长成。","綵衣朝朝舞花影，红烛夜夜闻书声。","进华觞，陈绮席，五福之中寿居一。","明年儿当五鼎食，人生此乐无终极。"]},{"t":"题具庆堂为赵参议作","f":"古风","c":["日出大梁城，照见黄河清。","黄河清见底，四海歌升平。","紫垣星高黄道正，积善之家有馀庆。","平原赵公忠孝门，食君之禄承君恩。","承君恩，食君禄，白发高年膺五福。","堂前大椿八千岁，架上群书三万轴。","请以五色线，为补舜衣裳。","普令天下人，同登具庆堂。","爱日熙熙舒以长，颠崖化为仁寿域，万亿苍生赖苏息。"]},{"t":"题清致轩","f":"古风","c":["玉湖清冰清彻底，铜盘甘露甘如醴。","一洗胸中万斛尘，挥毫濯以蔷薇水。","坐中宾客且勿喧，听我长歌清致之高轩。","闻道幽居最清绝，人物似是瀛洲仙。","五峰佳气郁不散，仰见华盖当中天。","朝朝拄笏延爽气，空翠飞落轩楹前。","自从负笈登太学，借问不归今几年。","山猿野鹤岂无梦，绿萝夜月秋娟娟。","万先生，何磊落，在山泉清出山浊。","手把芙蓉朝紫皇，下上青云骑一鹤。","会当四海澄其源，白日洗天风雨作。"]},{"t":"题雷节妇","f":"楚辞体","c":["凤凰丹山穴，雌雄两相依。","凤兮一去不复返，孤凰绕树鸣声悲。","堂前有五桂，一一青琼枝。","雏今文采生光辉，飞翔阿阁登天墀。","瑶池流玉浆，玄圃产金芝。","孤凰形影自相吊，风雨故巢终不移。"]},{"t":"赠张将军","f":"古风","c":["张将军，乃是留侯之子孙，英姿卓荦超凡群。","帝令洗剑沧海水，东踰旸谷西昆崙。","捷如抟风之快鹄，矫若运海之游鹍。","我愿千万年，海水直与黄河清。","海为濠，山为城，四境不闻金革声。"]},{"t":"东旭轩","f":"七言古诗","c":["我昨梦见摩尼幢，智幢道人忽相过。","笑指东方海日红，恍如东旭轩中坐。","浮生扰扰大梦中，几度金鸡啼向东。","百年三万六千日，日出日没皆虚空。","道人还家见东旭，尔轩何异吾家屋。","当窗宝树唱天鸡，随地金沙接旸谷。","我今去蹋东华尘，曙色苍凉朝紫宸。","万井辘轳霜满袖，回头却笑轩中人。"]},{"t":"丰城宝剑歌送李判簿之京","f":"古风","c":["丰城双剑如双龙，何年沈伏泥沙中。","腾辉夜夜射牛斗，紫气化为千丈虹。","不逢张雷识奇宝，至今甘与凡铁同。","太阿龙泉雌与雄，玩之翕歘生雷风。","开元供奉佳孙子，磊落奇才有如此。","手提三尺阴山冰，鸊鹈膏凝白鹇尾。","一剑跃入延平津，一剑飞腾如有神。","双剑相离复相见，何况乡里同心人。","我歌双剑篇，酌尔一杯酒。","会行高步上星辰，有待云霄重回首。"]},{"t":"椿萱堂为宪史张彦文作","f":"古风","c":["吾闻广成子，千二百岁居空同。","又闻麻姑仙，三见清浅蓬莱东。","此皆荒唐何足道，不如灵椿与萱草。","灵椿得寿岁月长，萱草忘忧颜色好。","秀州孝子留侯孙，园有灵椿堂有萱。","岁岁花开黄鹄嘴，慈亲白发倚堂门。","儿昔在家时，读书秋树根。","上堂问甘旨，下堂候寒温。","儿今高步霜台表，回望白云心懆懆。","但令一日简书稀，归著斑衣舞晴昊。","岂不闻留侯曾进黄公履，岁晚相从赤松子。","千载云仍有祖风移，孝为忠照青史。"]},{"t":"题画","f":"七言古诗","c":["远公昔住庐山下，一十八人同结社。","到寺闻钟即皱眉，只有柴桑姓陶者。","不知何人写此图，风致还似东林无。","阿翁手持九节杖，一童抱琴不受呼。","今人古人同一调，虎溪何必传三笑。","题诗寄谢香炉峰，待我来蹑金芙蓉。"]},{"t":"听雨轩为夏节兄弟作","f":"古风","c":["朝听西窗雨，暮听西窗雨。","暮暮复朝朝，弟兄同笑语。","雨声一夜隔天涯，兄在它乡弟在家。","千里情牵湘水竹，三年梦绕锦城花。","吁嗟人事何草草，出门不如在家好。","在家听雨声在床，出门听雨声在道。","原上不须悲脊令，堂下不须栽紫荆。","愿言四海皆兄弟，来向夏家听雨声。"]},{"t":"送别峰上人之京","f":"七言古诗","c":["我闻澄江净如练，优钵昙花世稀见。","千载高安古道场，师来重把犀牛扇。","先皇在时常引见，诏许谈经明光殿。","尚方云锦赐袈裟，甘露天廚分内膳。","翩然卓锡鸡鸣峰，帝遗渡杯来向东。","神机鼓舌走飞电，玉麈到手扬宗风。","白云在天无所住，塔前双桧为龙去。","一夜呼龙入钵来，森然化作唐朝雨。","五色丝纶下九天，师今又蹋大江船。","山色溪声何限意，总归八万四千言。"]},{"t":"题云海","f":"古风","c":["兹上人，号云海，一脉曹溪镇长在。","何年杯渡东海门，拾得海底珊瑚根。","上有六鳌峰，玄灵结胚腪。","置之太华芙蓉盆，中有灵响含清温。","灵泉贮空碧，倒影莓苔痕。","上人临流筑高轩，平地幻出祇陀园。","翻经洒以甘露言，宝花乱落青瑶琨。","我亦平生好禅者，十载梦游双树下。","正思执热濯清涟，何由借我支郎马。"]},{"t":"岘山樵隐歌为二令刘克和赋","f":"古风","c":["刘侯襄阳人，自言襄阳好。","樵居卜隐岘山阳，汉水一江流浩浩。","朝汲江上水，暮樵山中云。","拂石坐垂钓，读书行负薪。","笑杀风流晋山简，习家池头意萧散。","小儿拍手唱铜鞮，马上归来不知晚。","更忆羊公堕泪碑，英雄一代令人思。","鸣笳叠鼓白日动，千载以来如见之。","汉江之水蒲萄绿，日暮行歌大堤曲。","大堤女儿花满头，把臂蹋歌歌不足。","宦辙东西十五年，前程如此隔三千。","夜来梦逐南风去，直到庞公旧宅前。","石田可耕山可屋，瑶草金芝满丹谷。","功成它日赋归来，我亦相从学樵牧。"]},{"t":"赠医士郜士清","f":"七言古诗","c":["丹井西头山泽癯，平生爱读轩辕书。","石田有芝养白鹤，琐闼无佩悬金鱼。","前年别我朝天去，药笼参苓随所寓。","归来卜筑两山间，绕屋杏花春满树。","木兰之楫沙棠舟，市上孰知韩伯休。","一水相望五十里，峡云江树思悠悠。"]},{"t":"题望云图","f":"古风","c":["我家望云二千里，君家只隔一江水。","北堂岂无萱草花，生男不得长在家。","愿儿读书忠与孝，阿母看花长寿考。","母昔在家时，佩以宜男草。","母今生子后，慈颜长不老。","树萱北堂下，叶叶书带长。","儿年日以盛，母寿日以康。","儿有昆崙桃，寿母三千岁。","儿有紫霞觞，劝母花前醉。","富春水有金鲤鱼，富春山有油壁车。","有车可乘鱼可脍，岁岁看花北堂背。"]},{"t":"送禢二令秩满之京","f":"七言古诗","c":["我闻南州古南雄，梅花庾岭当春风。","乾坤旁薄毓神秀，乃有文章禢迪功。","三载作官东海邑，顽夫能廉懦夫立。","胥曹束手戒贪婪，丑类革心俱辟易。","杏花二月春雨晴，东风袅袅吹华旌。","今年考绩之瑶京，耄倪夹道相送迎。","使君此行须奏最，复见疲氓借河内。"]},{"t":"送百户徐叔平之甘州","f":"古风","c":["徐卿有子天马驹，从戎甘州十载馀。","白云东望八千里，夜夜梦绕鸳鸯湖。","鸳鸯双飞复双宿，湖中鲤鱼白如玉。","腰下能悬宝玦还，水边不用金钱卜。","左持张掖酒，右进凉蒲萄。","上堂舞莱衣，暂脱战时袍。","别家复向甘州去，简书有程那久住。","雁落黄云塞上芦，乌啼白月庭前树。","吾闻李牧今守边，边庭四境俱晏然。","椎牛飨士开屯田，星河远近同一天。","愿卿父子长寿考，壮士不须忧远道。"]},{"t":"送人归省还京","f":"古风","c":["朝望南山云，夕望北山云。","游子在远道，时时思见亲。","忆昔别家时，父母年未老。","儿著五色衣，上堂颜色好。","东市买白苧，西市买乌纱。","白苧制宽袍，乌纱簪好花。","三年游太学，读易司成馆。","春晖一何长，草心一何短。","阳城弟子有何蕃，优诏特许儿南还。","堂前灵鹊频报喜，飞傍宜男花树间。","父母闻儿归，黄色浮双眉。","大兄闻弟归，出郭身欲飞。","小弟见兄归，持觞细割黄金鸡。","入门快意无不足，城中少年徒碌碌。","大江水落秋风生，儿留三月还复行。","九天阊阖五云近，张帆上拂牵牛星。","万方冠冕朝玉京，老眼复见黄河清。","黄河清，四海一。","愿保千金躯，比之双白璧。"]},{"t":"送黄鍊师还天台","f":"古风","c":["吾闻天台山高四万八千丈，中有玉平之洞天。","丹霞赤日照林壑，此地往往多神仙。","神仙中人不易得，黄公之孙有仙骨。","放浪江湖四十年，春风落尽柳花碧。","海边楼观临蓬莱，何年飞舄从东来。","丝纶五色诏遗逸，手把芙蓉朝玉台。","昔我题诗过方丈，令我临风倍惆怅。","不见辽东一鹤归，步虚声落青天上。","我有一掬泪，不洒三十春。","但哭市井交，何曾哭仙人。","我知仙人长不死，昼夜循环亦如此。"]},{"t":"送道澜上人还天界","f":"七言古诗","c":["道澜上人好文采，舌如波澜性如海。","犀牛扇子破多时，留得千年公案在。","别峰禅老日边来，金襕照日天花开。","皎如一片秋水镜，置在七宝青莲台。","室中弟子多闻道，见性无如道澜早。","结社曾邀陶令过，论诗每爱支郎好。","飘然飞锡向何方，第一禅林古道场。","且对黄花谈般若，更留数日过重阳。"]},{"t":"赠觯僧会","f":"七言古诗","c":["天目之山自西来，群龙回绕青莲台。","千年翠气郁不散，化成楼阁重重开。","上人自是僧中宝，黄鹤峰前坐来好。","天风吹动杂花林，山色溪声谈未了。","昨者凤凰衔紫泥，潮音却渡海门西。","海门月照白毫相，浊水倒影澄摩尼。","我亦前身许玄度，半生颇有烟霞趣。","夜来八万四千言，笑对黄花独无语。"]},{"t":"题双松图赠司虞赵子瑛","f":"古风","c":["吾闻泰华山，上有千尺之长松。","白云英英出其颠，天门日观遥相通。","三更鸡鸣海水赤，羲和揽辔骑飞龙。","松下高人坐盘石，金芝瑶草青茸茸。","三年钓鳌东海上，奏最去谒明光宫。","栋梁之材当大用，大夫不让秦时封。","赠君此图千里玩，长见青青齐鲁东。"]},{"t":"题太古子为分水县佐苏侯赋","f":"楚辞体","c":["八风不动地轴宁，六合无尘天宇清。","圣人在位罗群英，干橹化为弦诵声。","苏侯绍芳德弥馨，邂逅黉宫舒我情。","笑谈霏霏甘露洒，意气落落秋风生。","为言佐政分水城，楼船东下窥沧溟。","海门山水多奇异，西通月窟东高丽。","天鸡夜半啼一声，璧采金光绚霞气。","蓬莱更在天东隅，欲跨飙轮游八区。","麻姑别去音信断，弱流清浅今何如。","太阿跃出丰城狱，斫断三山巨鳌足。","九苞鸣凤信有神，结巢宛在珠树林。","云窗雾阁应可到，海若天吴安敢嗔。","山可登兮水可临，嗟我白发秋霜侵。","幸逢昭代宽且仁，梯航重译输南金。","自从天地一开辟，凡有血气皆尊亲。","我欲入海攀鲸鳞，手探明珠弗顾身。","安得昌山双玉琯，吹彻太古羲皇心。","羲皇之心万万古，且酌百瓮蒲萄春。"]},{"t":"题贞妇胡氏贡姑","f":"古风","c":["妾薄命，向谁道。","生不学空中花，死甘为墙下草。","墙下草生不离家，风中花泊天之涯。","爷娘早亡阿弟死，膝下呱呱遗一子。","妇守嫠居不二天，形影相依心若水。"]},{"t":"送判府万侯秩满如京","f":"古风","c":["南昌万使君，乃是东汉将军之子孙。","家有槐里堂，世称忠义门。","锐如丰城之宝剑，矫若沧海之游鹍。","一旦雄才际昌运，三年出佐东南郡。","寒谷阳春化日长，玉壶夜月清冰瑩。","雁背霜高江水清，云帆晓发凤凰城。","长安渡头喧叠鼓，共挽官船留判府。","判府今年朝玉京，心知万亿苍生苦。","建子之月梅花开，腊后春前侯复来。","天上应颁五色诰，马蹄重蹋长安道。"]},{"t":"题虞太守画","f":"古风","c":["昨夜梦入茅君山，平明飞落秋堂间。","一色芙蓉倚天碧，千岩万壑何盘盘。","蓬莱宫中青鸟使，忽寄数行云锦字。","玩之使我神飞扬，排云拟接泠风袂。","虞夫子，瀛洲仙。","自与山别来，宦游南北今几年。","金堂石室岁月久，洞花溪鸟仍依然。","采芝有田，洗术有泉。","萝月可席，松风可弦。","山中之乐不可极，青壁有路何由缘。","会当揽辔清中原，麟符虎节朝九天。","西寻赤松子，东揖鲁仲连，功成却赋归来篇。","寄谢三茅君，此时我发不再玄，安得骑鸾下上相周旋。","相周旋，鍊金液。","摩挲老眼望时青，更乞还丹生羽翼。"]},{"t":"定水歌","f":"七言古诗","c":["定水定水何曾定，活水源头本清净。","八风不动常自清，一片浑如大圆镜。","老禅默坐古盘陀，心如定水原无波。","俯视长江一杯小，朝潮夕汐相荡摩。","无始以来皆定业，扰扰劳生千万劫。","白头它日挂冠归，重见一花开五叶。"]},{"t":"题望云图为太学生史孟彬作","f":"七言古诗","c":["儿昔望云云在天，儿今望云云在泉。","云在天边见有日，云在泉下归何年。","儿心一寸春晖草，阿母倚门儿在道。","太学三年归有程，当时恨不还家早。","白杨日日多悲风，儿归却扫坟上松。","千驷万钟儿不愿，但愿名书忠孝传。"]},{"t":"篆书歌送胡士敬游同安","f":"七言古诗","c":["洪濛开天圣人作，神龙出河龟出洛。","自从造化一中分，鸟迹虫鱼混冥漠。","史籀篆刻周宣古，李斯书传和氏璞。","汉魏以来千百年，字体纷纭互参错。","我从洪都询古学，宗人邂逅滕王阁。","千金不售书满橐，燕尾蚕头古钗脚。","钩如强弩点如石，动为河流静为岳。","亲王诏见墨池头，茧纸鸾笺纵挥霍。","晴窗白昼风雨来，蛟龙盘拿虎凤跃。","吾宗意气何卓荦，翩然如跨扬州鹤。","今春别我上同安，七星已挂苍龙角。","兰舟暂向章江泊，篘酒笑倾银凿落。","人生交游无厚薄，快意相知且为乐。","吴歌一曲写予怀，目送飞鸿起寥廓。"]},{"t":"中秋","f":"七言古诗","c":["绛河帖帖星不流，玉露夜堕芙蓉洲。","仙家五城十二楼，恍然生我冰壶秋。","龙宫莲花白浮浮，须臾涌出豫章沟。","举觞唤月月少留，月不解饮令人愁。","少年绿发今白头，六十九度经中秋。"]},{"t":"望夫石","f":"古风","c":["朝望夫不归，夕望夫不归。","化为山头石，夫归定何时。","妾身化石尚可转，妾心如铁无人知。"]},{"t":"焦仲卿妇辞","f":"古风","c":["黄鹄上青天，雌雄相颉颃。","妾年十四五，学绣金鸳鸯。","父母养妾在洞房，寸步何曾出中堂。","嫁作庐江焦氏妇，低眉不离老姑傍。","春月浴吴蚕，秋风织流黄。","烹鱼朝具馔，秉烛夜缝裳。","不知姑何意，命妾别庐江。","梧桐不复生，凤凰不得双。","郎心如石不可转，妾如蒲苇不可断。","妾家有㬥兄，一旦来相迎。","玉骢金络马，轧轧车轮声。","遣妾移所天，出门无少停。","㬥兄安能知妾情，妾今无故来归宁。","女子足不践二庭，庐江之水清泠泠。","吁嗟乎，焦仲卿。"]},{"t":"从军行","f":"古风","c":["千金买紫燕，百金买龙泉。","燕紫嘶白日，龙泉倚青天。","凌晨出门去，莫忘庭前树。","树上乌生三四雏，年年结巢来哺乌。"]},{"t":"北山行送人还富春","f":"七言古诗","c":["北山山下草堂开，北山先生安在哉。","先生名与山不朽，何异鲁望尊徂徕。","子孙世居北山下，况尔更多英俊才。","弟也能通学剑术，兄复能起读书台。","邦家之基在今日，诗人所宜歌有莱。","赤松亭前采药去，黄公洞口看花来。","栖鹤寥寥海天碧，白云南望心裴回。"]},{"t":"紫薇花下","f":"古风","c":["我非紫薇郎，爱种紫薇花。","紫薇亦爱诗人家，今年试花如绛霞。","清晨看花心自喜，中夜裴回月明里。","不随红日上东廊，影过八砖犹未起。"]},{"t":"寄宋山人","f":"七言古诗","c":["青鸟飞来东海隅，衔得云中云锦书。","书中落落三百字，一字一颗鲛人珠。","三年不见兰台令，别去亳州无好信。","楚鸿日夜叹离群，越鸟天寒栖不定。","近报卜居湖上头，木兰为楫桂为舟。","明朝会买官瓶酒，醉眼看山同一游。"]},{"t":"梅窗为凯上人赋","f":"古风","c":["凯上人，南游越王之古台，飞锡近自龙溪来。","雪晴戴笠走相访，为报窗外梅花开。","大庾岭头春信早，五叶一花谈未了。","曹溪香水接龙溪，铁石心肠向谁道。","铁中有黄金，铸出瑰奇磊落之贞心。","石中有白璧，琢出崒律巉碞之老骨。","何年移种龙溪旁，影落袈裟月到窗。","维摩帐底定初起，天女散花春满堂。","凯上人，向何处，来往虚空本无住。","二千里外白头翁，三年不蹋西湖路。","山中猿鹤寄书来，我亦相期看花去。"]},{"t":"暮春病起","f":"古风","c":["春日迟迟出旸谷，桃花能红柳条绿。","柳上仓庚催梦醒，花间胡蝶劝人行。","绿窗剪刀金两股，剪吴罗，对花舞。","对花舞，为花歌，百年欢乐能几何。","但愿长绳系羲驭，把酒留春春莫去。"]},{"t":"题风木卷为丁孝子赋","f":"古风","c":["风在天，木在地，暂时会合还离异。","木在地，风在天，风声不到九重泉。","丁兰肖母曾刻木，丁令化鹤归何年。","我愿风声长在耳，世世人称丁孝子。","纵使木高千万寻，不及孤儿方寸心。"]},{"t":"题赵子昂画西马为褚奉祠作","f":"七言古诗","c":["前朝学士赵王孙，画马传得曹将军。","此图骨相何所致，万里来自西昆崙。","玄云覆身蹄削玉，雾鬣风鬃电为目。","珊瑚络脑青丝缰，远戎牵来字天育。","雄姿矫矫当赤墀，神骏不许人间骑。","玉堂挥洒岁月久，河南祠官今得之。","吾皇仁化被八极，騕袅骅骝数盈亿。","日出日没皆封疆，求骏何烦画中索。","老我衰年发已苍，惠养每思田子方。","何幸生逢太平日，归放华山春草长。","祠官藏之慎勿亵，留取郢中歌白雪。"]},{"t":"送宁上人住玉溪","f":"古风","c":["宁上人，乃是妙喜之云孙。","西江一口吸不尽，又向玉溪寻白云。","玉溪澄澄清见底，千年?接曹溪水。","松风吹作海潮音，重重楼阁凌空起。","到寺欣逢大闰年，宝花如雨散诸天。","有约中秋月明夜，待余来问木樨禅。"]},{"t":"赠庸信庵上人建卢大夫桥","f":"古风","c":["昔闻卢大夫，作桥长安市。","宛如青天虹，堕影长河水。","一朝乘风飞上天，公无渡河公莫前。","老禅白雪垂两肩，金锡掷地风泠然。","女娲鍊石不受鞭，化为飞龙卧晴川。","我来脚蹋金鳌背，啸歌声落青云外。","相如题柱最多情，好结天风紫霞佩。"]},{"t":"分题得海门洪涛送友人之闽","f":"古风","c":["朝登东海门，遥望槫桑暾。","波涛浩无际，推出黄金盆。","河流九派来昆崙，百川朝宗皆骏奔。","但见东南一花起，匹练界破青天痕。","鱼龙乘时亦变化，珠宫簸荡珊瑚根。","初如峨眉山西太古雪，惊雷碾空地欲裂。","又如蓬莱巨鳌十五头，涌起三山白银阙。","中有仙人驾飙车，遨游玄圃蹋琼琚。","长风破浪在咫尺，直跨鹏翼凌天衢。","凌天衢，渡南海。","麻姑傥有寄来书，荔子船回早相待。"]},{"t":"莫望云","f":"古风","c":["莫望云，望云云渐远。","故乡云在心，它乡云在眼。","云在它乡眼，何如故乡心。","云近尚可望，云远思转深。","人生谁无母，子心良独苦。","峨眉太白青入天，不及家山一抔土。"]},{"t":"望云亭","f":"古风","c":["朝望云在东，夕望云在西。","如何母与子，各在天一涯。","关中去家数千里，梦绕西湖一杯水。","回看天际白云飞，片片尽从东海起。","云近尚可望，云远思转深。","关山夜月三年笛，萱草春晖一寸心。","剑阁萦回接云栈，太白峨眉青在眼。","安得尔云化为五色衣，朝朝暮暮当庭闱。","朝朝暮暮当庭闱，不劳望云怀远归。"]},{"t":"乌程谣","f":"七言古诗","c":["我家昔在乌程住，三百年来不归去。","闻说乌程令尹贤，移家欲种乌程田。","明朝去买乌程酒，东白堂前种杨柳。","柳上啼乌报五更，排衙鼓动官马鸣。","裹头丁男应门户，莫待日高高丈五。"]},{"t":"阳城耕雨歌","f":"七言古诗","c":["春云阴阴酿春雨，荷锄朝出三家墅。","草满南坡犊子肥，一蓑一笠雨中归。","千顷水田飞白鸟，雨足泥深稊稗少。","大树将军好子孙，辍耕陇上如庞老。","人间别有方寸心，此地可作商家霖。","先生砚田耕未了，屋头布谷鸣春晓。"]},{"t":"题镇抚扇","f":"古风","c":["将军紫骝马，手挽青丝缰。","避暑向何处，城南风阁凉。","夜半金鸡出旸谷，东望槫桑西若木。","不须强弩射潮头，万里鲸鲵俱偃伏。","新裁白苧雪花明，手持羽扇清风生。","壮士吹笳月如昼，卧听城头报更漏。"]},{"t":"赠燕山老妓歌","f":"七言古诗","c":["燕山老妓七十馀，少小苏门城下居。","自言生长太平日，蹋遍江南西子湖。","湖水湖山近城郭，五步一楼十步阁。","春风酒舫载瑶筝，夜月歌台卷珠箔。","东家胡蝶过西家，十里湖波泛落花。","苏小门嘶五花马，段家桥碾七香车。","早年传得伊州曲，翠舞珠歌满华屋。","芍药春明和玉箫，海棠夜醉添银烛。","一曲清歌一束绫，歌声上遏流云行。","韩娥齿让瓠犀白，赵女眉妒春山青。","转首繁华何草草，不道青春暗中老。"]},{"t":"悲白头翁","f":"古风","c":["白头翁，生长太平世。","吴歌楚舞少年时，老来犹说欢娱地。","欢娱地，良可悲。","洛阳牡丹无故主，金谷海棠非昔时。","千金买花岂不好，回首池台变芳草。","秋霜昨夜镜中来，花枝照眼令人哀。"]},{"t":"题母子猫图","f":"古风","c":["大猫斑斑虎豹姿，小猫白白如狻猊。","斑者是母白者儿，石苔昼卧春迟迟。","儿能跳踉母不知，牡丹花前胡蝶飞。","薄荷叶底酣晴晖，小鬟溪头买鱼去，月下敲盆呼尔归。","岂不闻东家韩卢知报主，夜深防盗兼捕鼠。"]},{"t":"题楚江春晓图","f":"七言古诗","c":["巴水雪消流浩浩，三峡猿声啼不了。","舟人挂帆南斗低，斑竹林深鸡唱晓。","大船小船相逐来，小船先待大船开。","黄陵庙前风浪恶，小船还依大船泊。","共祷龙神抛纸钱，珓杯凶恶听巫言。","但祝远人心地好，乌纱巾上有青天。"]},{"t":"题茅山外史奔月卮歌","f":"七言古诗","c":["瑶池羿妃奔入月，窃得丹砂鍊金骨。","何年跃入龙王宫，千丈虹光射银阙。","茅山外史口悬河，长鲸吸海翻白螺。","夜半铜仙泣秋露，化为万斛黄金波。","空歌笑落琼台表，傲睨乾坤一杯小。","月中若许筑糟台，我亦骑鸾天上来。"]},{"t":"题马公肃墓池瑞莲","f":"七言古诗","c":["种花莫种忘忧草，马家池头花更好。","去年一柄生两房，儿在颍川归故乡。","儿归见花不见母，一寸心如莲菂苦。","也知天与好儿孙，戢戢青头联牖户。","么荷恰似小儿拳，迎门索枣当母前。","劝儿食莲须食蓼，辛苦读书知味少。","愿花并蒂年年开，一度看花儿一来。"]},{"t":"题梅图次胡龙臣韵","f":"七言古诗","c":["梁园宾客看花处，锦障围春花满树。","一朝池馆彩云空，可恨留春春不住。","岂若孤山雪后花，年年开向老逋家。","自信贞心同铁石，肯随凡卉混尘沙。","明月半窗閒徙倚，展画看诗思无已。","华表千年鹤不归，霜花满地天如水。"]},{"t":"挽府幕陈友宽妻","f":"七言古诗","c":["棠梨花落春沈沈，美人隔窗鸣素琴。","一弹离鸾之古调，再理别鹤之哀音。","百年夫妇愿谐老，岂信红颜不常保。","昔如南山连理枝，今作秋风断根草。","牵牛织女两相望，一旦化为参与商。","愿郎长开故箧笥，念妾莫换新衣裳。"]},{"t":"延月轩","f":"古风","c":["延月复延月，延月上青天。","月本无私照，流光入我轩。","八咏楼中好孙子，当时月照双溪水。","不知千载落谁家，只今飞入华堂里。","东家延月照绮罗，雪儿起舞雪娘歌。","西家延月照珠翠，红烛花偏锦袍醉。","何如清夜扫前除，留月照我琴与书。"]},{"t":"题子猷访戴图","f":"七言古诗","c":["燕山雪花大如掌，沙碛琼瑶深一丈。","万里寒云鸟不飞，驱车北渡河冰上。","岂识山阴有剡溪，白月堕水风吹衣。","子猷忽尔清兴发，夜半乘舟访戴逵。","此时此兴良不恶，一幅生绡亦奇作。","争似苏卿秉节旄，千年图在麒麟阁。"]},{"t":"题望峡轩","f":"古风","c":["双峡何亭亭，如弟复如兄。","紫薇刘郎去已远，山今犹有紫薇名。","太学儒生未三十，玉树英英向人立。","堂上有亲今白头，晨昏定省嗟何及。","书往书来春复秋，璧水竟作三年留。","凤凰台上一回首，千里云生东海头。","东海东头白云起，望峡之心何日已。","安得尔云化为五色衣，朝朝暮暮当庭闱。","朝朝暮暮当庭闱，不劳望云思远归。"]},{"t":"龙尾山隐者歌","f":"古风","c":["龙尾之山青蜿蟺，何年跃出东南天。","夸娥不能为之员，祖龙不能为之鞭。","雷公电母相后先，珠光璧采生重渊。","中有幽人颜色好，自采青芝拾瑶草。","大丹鍊就金芙蓉，世人得之如得宝。","我昨乘閒一访君，清昼柴扉封白云。","欲觅仙踪不知处，薜萝凉月秋纷纷。","我无隋侯珠，何以报区区。","明当南还大庾岭，青鸟来时须寄书。"]},{"t":"赠峡川医士郜员","f":"古风","c":["紫薇山前鹤发翁，古心古貌古人同。","朝漱玉于葛洪之丹井，夕栖云于顾况之青峰。","大丹鍊就金芙蓉，神方传自娑竭宫。","白石可裂，黄金可镕。","有恒之心，天地无穷。"]},{"t":"题姜润华怡老堂图","f":"古风","c":["天目山，来钱唐。","翩如丹霄五凤下，矫若碧海群龙翔。","金煇璧采照城郭，中有姜家怡老之高堂。","有卜不应非熊兆，有手不钓磻溪璜。","堂中阿翁寿而康，堂下佳儿联雁行。","盘行白玉鲙，觞进青霞浆。","松花落雪高云凉，松根茯苓如雪香。","左江右湖流汤汤，愿言寿比广成子，千二百岁同其长。"]},{"t":"题三香图二首 其一","f":"古风","c":["拾翠羽，采明珠，美人宛在沧洲居。","梅为兄，矾为弟，一笑相逢大江水。","江水澄澄罗袜寒，双井诗人谁共看。"]},{"t":"题三香图二首 其二","f":"七言律诗","c":["秋风双井芙蓉老，太史当年被花恼。","挥毫曾赋水仙诗，矾弟梅兄奇绝倒。","三香之图风骨清，信知难弟复难兄。","昨夜月明江水白，出门一笑见高情。"]},{"t":"题张文显梅月山斋诗卷","f":"古风","c":["盈盈罗浮华，皎皎罗浮月。","渺渺罗浮云，粲粲罗浮雪。","我昔梦入罗浮天，缟衣仙子神飘然。","绿毛么凤隔花语，别来仿佛三千年。","子今赠我云锦笺，何以报之琼瑶篇。","相思一夜月如练，岁寒长见春风面。"]},{"t":"题学钓轩","f":"七言古诗","c":["炎祚真人骑赤龙，故人傲睨轻王公。","身披羊裘隐泽中，手弄一丝江上风。","客星夜临紫极宫，钓台高并云台功。","复有云孙千载下，读书岂是煦煦者。","司征海上六年馀，古貌古心知者寡。","琴江东去水滔滔，石上珊瑚明月高。","拂衣别我且归去，持竿钓取黄金鳌。"]},{"t":"题杏林别墅图","f":"古风","c":["我闻于使君，种杏碧山下。","它山岂无丹杏花，不及家山种来者。","高堂中有白发亲，看花酌酒娱青春。","儿今去家二千里，作官只饮三衢水。","三衢水，清涟漪。","年年杏花开满枝，点缀五色斑斓衣。","阿翁袖有金光草，令人服之颜色好。","别墅春风日日来，花落花开长不老。"]},{"t":"秦驻山杀虎歌","f":"七言古诗","c":["秦驻山头祖龙庙，月黑天寒闻虎啸。","将军手挽乌角弓，平明入山寻虎踪。","丛篁秀木郁重重，阴壑惨淡来悲风。","山灵白昼驱虎出，壮士跳踉与之敌。","雄牙利爪善搏人，大剑长鎗俱辟易。","我今三箭信有神，勇气不让飞将军。","山中一朝除虎害，四境扫荡无妖纷。","封章奏彻彤庭上，圣主闻知颁内赏。","安得储公数十人，一时苏息东南民。"]},{"t":"重题涌金门外杀虎歌","f":"古风","c":["昔闻尧舜世，大禹平水土。","虎豹犀象驱远之，万亿苍生皆按堵。","储将军，雄且武。","一朝手挽乌号弓，射杀南山白頞虎。","白頞虎，视耽耽。","朝游城之北，暮游城之南。","不有将军一身胆，纵此飞类民何堪。","岂不闻牛哀七日化为虎，兽面不知兄与父。","缚虎易，知人难，方今圣德天地宽。","但愿将军镇藩翰，人不化虎四海皆清安。"]},{"t":"题槐阴书舍","f":"古风","c":["天有三台，地有三槐，云是晋公亲手栽。","三槐如云复如盖，果应二郎居鼎鼐。","时当景德祥符间，柱石廊庙安如山。","世泽传来三百载，复有孙子登朝班。","槐叶阴阴覆书屋，不数邺侯三万轴。","绣衣金节玉花骢，行部归看满庭绿。","春晖堂前乌夜啼，结巢多在青云枝。","青云枝上乌啼处，它年留作甘棠树。"]},{"t":"送宪司知事吴君考绩之京","f":"古风","c":["江之水，清且涟，明如镜，直如弦。","青骢系著江边树，绣衣考绩朝天去。","津人伐鼓送楼船，十丈云帆南斗边。","鲸波帖帖风不起，使君之心有如水。","激浊扬清振纲纪，万岁千秋报天子。"]},{"t":"送吴司幕秩满之京","f":"古风","c":["歌南薰，调素琴，人生会合无古今。","古人不爱暮夜金，今人岂无古人心。","河南吴公好孙子，脩髯如漆心如水。","三年赞画简书劳，芙蓉幕下清风起。","调素琴，歌南薰，南阳宗资今见君。","江花冥冥江水春，百丈牵船登要津。","凤凰池上恩波重，天官考绩承天宠。","冥鸿万里决浮云，自古有才当大用。"]},{"t":"题直翁胡重器诗卷","f":"古风","c":["直莫如虞帝之琴弦，曲莫如任公之钓钩。","直弦可弹太古调，曲钩谩掣金鳌头。","人心取舍各有道，曲钩何如直弦好。","在天勿作弯弧星，在地当为指佞草。","直翁直翁听我歌，出门纷纷岐路多。","我愿万斛舟，不涉九曲河。","我愿千里足，不驰九折坡。","翁今有子鸣朝珂，履道坦坦平不颇。","董狐之笔如操戈，千秋万古名弗磨。","翁当馀年养太和，子孙世居安乐窝。"]},{"t":"题航为俞叔铭作","f":"楚辞体","c":["野水兮幽幽，野航兮悠悠。","动吾行兮浮浮，静吾止兮休休。","逍遥兮中州，浩荡兮安流。","凭虚兮天游，沿月兮棹讴。","彼坳堂之杯兮孰若以芥而为舟。","噫！","委身大造兮任吾去留。"]},{"t":"题朱氏椿萱堂","f":"楚辞体","c":["吾闻漆园之木八千秋，又闻北堂萱草能忘忧。","朱卿夫妇俱白头，儿也贡入帝王州。","口传天语出丹阙，马蹄蹋遍闽山月。","儿心何以报春晖，回望飞云隔吴越。","左手擘荔枝，右手持槟榔。","它山岂不好，不如归故乡。","登朝见天子，沐浴承休光。","龙河雪消春水长，愿乞还家三釜养。","入门堂上见椿萱，灵柯锐叶俱无恙。","读书椿树下，进酒萱花傍。","更分白兔所捣之玄霜，父兮母兮发苍苍。","金兰玉树照庭户，直与窦家五桂同芬芳。"]},{"t":"谢南康张少府惠带","f":"七言古诗","c":["南康少府休官日，三径黄花有佳色。","寄来束带水犀文，令我腰围较宽窄。","乌纱高帽白苧衣，系来稚子道相宜。","入手御炉烟气重，知卿来自凤凰池。","我亦平生爱疏散，可恨与卿相见晚。","秋来消瘦苦耽诗，一日几回移带眼。","湖鱼白白湖蟹肥，禾黍满田黄雀飞。","秋水野航三十里，停云西望思依依。"]},{"t":"集杜少陵诗句一首奉寄云庵法师","f":"七言古诗","c":["台州地阔海溟溟，南极老人自有星。","千崖无人万壑静，老身古寺风泠泠。","有时自发钟磬响，芝草琅玕日应长。","昏黑应须到上头，安得仙人九节杖。","不见旻公三十年，清诗句句尽堪传。","陶冶性灵存底物，晴窗检点白云篇。"]},{"t":"题竹雪山房为王御史作二首 其一","f":"七言古诗","c":["绣衣柱史铁作冠，平生爱种青琅玕。","山中岁晚读书处，积雪满庭生翠寒。","常时见竹不见雪，竹雪双清更奇绝。","冰壶照彻此君心，璞玉镌成此君节。","平明四望岩壑间，矫如群龙下瑶坛。","黄陵女儿骑白凤，风裳月佩鸣珊珊。","恍然张乐洞庭野，倒卷银河向天写。","九重阊阖参差开，八极空明不知夜。","是时绣衣朝紫皇，下视九点烟茫茫。","会当裁作十二琯，坐使寒谷回春阳。"]},{"t":"题竹雪山房为王御史作二首 其二","f":"五言古诗","c":["有竹岂不佳，有雪亦自好。","金声来户外，玉气出林表。","昔闻王子猷，夜访戴安道。","当时有此君，相见必倾倒。","千载回舟兴，至今犹未了。","引领仰高风，何由写怀抱。","卓哉岁寒姿，贞白永相保。"]},{"t":"题李白观庐山瀑布图","f":"古风","c":["我思仙人，乃在南斗之下香炉之峰。","手招五老白云里，掀髯玉立凌天风。","不知何年鬼斧凿破混沌窍，绝顶直与银河通。","上有奔崖喷壑之飞流，下有横江饮涧之长虹。","白波九道走东海，流转万古无终穷。","仙人词源亦如此，天然秋水生芙蓉。","开元召入黄金屋，挥毫醉写清平曲。","鸣凤不栖阿阁巢，青蝇翻污连城玉。","金鸡放赦夜郎回，生死托交鹦鹉杯。","人间斗酒醉不得，此水可涤愁怀开。","酒星在山头，酒泉在山下。","便当酿作蒲萄醅，不费千金之裘五花马。","胡为梦落峨眉亭，千年一去不复醒。","画中仿佛见颜色，屋梁落月秋冥冥。","闻道骑鲸入瀛海，神游汗漫知何在。","大鹏借我垂天云，八极三清会相待。"]},{"t":"题王仲序墨客诗卷","f":"七言古诗","c":["王郎酒酣当墨池，五云飞落天孙机。","河东美人织不得，仿佛八茧吴蚕丝。","亲王召见蓬莱殿，天门白日飞龙见。","中官传旨赐奚囊，王郎佩服生辉光。","绛州陈玄最奇绝，落手麟胶三日香。","梁园赋客邹枚老，爱尔尊前一倾倒。","挥毫为写锦囊歌，愿尔千年赞王道。"]},{"t":"剪韭亭","f":"古风","c":["剪韭复剪韭，山园春雨肥。","昨日韭叶长，今朝韭叶稀。","但令勿伤根，日夕生华滋。","有客过茅屋，呼儿剪春绿。","一箸盘餐惟所须，何待高门行白玉。","寄言山中人，灌畦当及春。","人间此味良可珍，此味不减秋风莼。"]},{"t":"友人纸帐名卧云求题","f":"七言古诗","c":["白云劈茧春重重，仙人卧云如卧龙。","天风吹下太古雪，平地幻出琼瑶宫。","白云来来还复去，何如一榻留云住。","胡蝶庄周两不知，谁能解此云中趣。","小鬟折花香满衣，霓裳夜半行云归。","周公梦回日丈五，此乐人间今古稀。","梨花散漫春云暖，一色瑶台月华满。","醉倚仙家十二楼，夜寒不上珊瑚钩。","飞琼隔花吹小凤，缟衣惊起罗浮梦。","溪藤剪霜翻素涛，翠禽啼烟红日高。","世间万事邯郸道，人生不及卧云好。"]},{"t":"题李仕廉雪溪诗卷","f":"七言古诗","c":["五载西江想东越，兴来欲蹋山阴雪。","眼明见此雪溪图，恍若冰壶贮寒月。","山中之人不可招，千崖万壑皆琼瑶。","长空浩浩绝飞鸟，深林何处寻渔樵。","谪仙有孙有佳趣，蓬莱移得三珠树。","稍待明年春水生，借我纶竿钓鱼去。"]},{"t":"题马文学之惠安教谕","f":"古风","c":["鍧鸣钟，考朗鼓，司马先生教南土。","泉州宛在福州南，榕叶如云荔枝甘。","一路春山当马首，下马杯行椰子酒。","门生出郭候溪傍，翠盘钿合进槟榔。","蛮云瘴雨喜无恙，衿佩青青趋绛帐。"]},{"t":"送黄将军分镇台城","f":"七言古诗","c":["渥洼之驹走千里，雪花凝寒吹不起。","将军仗剑出洪都，南来手挽天河水。","天河直与东海通，槫桑虬枝挂弯弓。","旌旗倒射海底日，金鸦夜啼华顶峰。","彼州之人迎我侯，此州之人不可留。","顺风吹帆疾如马，绿水荡漾芙蓉秋。","九日黄花一尊酒，手把茱萸当杨柳。","将军自有谷城书，勋业传家垂不朽。"]},{"t":"谢何徵君惠麻鞋","f":"七言古诗","c":["仙人昔上蓬莱宫，十年蹋遍京尘红。","仙人今归东海曲，麻鞋但遗双白足。","白足麻鞋白似霜，紫苔犹带落花香。","世人不识飞凫舄，千里烦君远寄将。","昨向沧洲拾瑶草，雨过沙乾著来好。","此中不是若耶溪，布袜何愁杜陵老。","知君已谢鹓鹭班，寻真来访白云间。","旧时猿鹤应相识，好在南山与北山。"]},{"t":"题李白观泉图","f":"楚辞体","c":["我所思兮在匡庐，锦袍仙人玉不如。","香炉五老半天上，旭日照耀金芙蕖。","仙人倒披云锦袍，浩气直压秋崖高。","人间斗酒醉不得，手挽银河翻雪涛。","一朝召入金銮殿，曾与龙颜醉中见。","谁知白玉点青蝇，不顾昭阳忤飞燕。","紫皇案前五色麟，掉头蹋遍名山春。","若非九天写下千尺水，何以荡涤胸中尘。","千年风骨何人画，仿佛屋梁明月夜。","骑鲸东海若相逢，大笑长歌呼白也。"]},{"t":"题芝溪送别图","f":"七言古诗","c":["我闻袁安之子孙，何年卜隐芝溪村。","渭阳舅氏不可作，甥乃仗剑登期门。","芝溪之水清见底，中有别情千万里。","鸣笳叠鼓送行舟，东流有尽情无已。","芝溪水有双鲤鱼，芝溪水有明月珠。","明珠莫弹山头雀，双鲤须传海上书。"]},{"t":"送张河泊还乡","f":"古风","c":["清凉远在南海隅，青鸟衔寄云中书。","开缄忍见数行字，阿母手封双泪珠。","为言十载与儿别，复报若翁今永决。","五月儿从阙下还，怅望南云寸心折。","水有行舟陆有马，无复升堂拜郎罢。","七月秋风起布帆，儿归笑指青山下。","儿今无所愿，愿母寿且康。","上堂进荔枝，下堂食槟榔。","槟榔可餐荔可擘，玉立亭亭儿在侧。","更种长松当墓前，慈乌结巢年复年。"]},{"t":"题岐山图","f":"古风","c":["朝望岐山云，夕望岐山云。","岐山不可见但见，非烟非雾青氤氲。","上清真人好奇古，有山不待夸娥负。","缩地回天顷刻间，蓬莱移得金鳌股。","吾闻留侯从赤松，功成归老山之中。","千年复见好孙子，出宰况近仙人宫。","仙人啸歌碧云里，采掇金芝餐玉髓。","也知吏隐亦清流，两年只饮芗溪水。","只今见画如见山，安得置我灵台间。","日日凭高望云气，会待岐阳鸣凤还。"]},{"t":"杀虎歌赠叶将军","f":"古风","c":["朝射虎，夕射虎，吹鸣笳喧叠鼓去。","年田禾，不得收，牛羊不敢放垄头。","今年禾黍满郊野，猛虎无声山月秋。","白发老翁卧茅屋，教儿卖剑买黄犊。","到城明日谢将军，更向辕门分虎肉。"]},{"t":"渔隐","f":"古风","c":["青青蒲叶短，临平湖水满。","袅袅柳丝长，当门系野航。","野航稳于马，坐钓青山下。","鱼我两相忘，无人知钓者。","百年天地一渔蓑，流水桃花意若何。","得鱼换酒篷下醉，自诵一曲沧浪歌。","太公钓西周，严光钓东汉。","古来豪杰人，出处关治乱。"]},{"t":"题山居夏夜读书图","f":"楚辞体","c":["素月兮流天，松风兮奏弦。","澄夜气兮泠然，寓吾情兮简编。","探羲图兮画前，游吾神兮太古之先。"]},{"t":"送马贡士题春江送别图","f":"七言古诗","c":["大山小山芙蓉开，云气远从天目来。","东风吹散凤城雪，一夜江水青于苔。","借问舟行向何处，马卿明日朝天去。","杏园花满曲江春，幽谷莺迁上林树。","方今玉堂皆钜公，手把刀尺青云中。","神龙出河龟出洛，千载复见明良逢。","马卿此行当努力，射策彤庭期第一。","龙门夺得锦袍归，先遣双鱼寄消息。"]},{"t":"题春山小景图","f":"七言古诗","c":["老夫爱画入骨髓，偶向高堂见山水。","不识何人写此图，恍然坐我春云里。","大山小山青入天，岚气暝结香炉烟。","扁舟夜泊浔阳郭，似是当年孟浩然。","阿翁手持九节杖，双涧流泉玉琴响。","天风吹带碧桃花，瑶草金芝为谁长。","南郭先生吾友于，招我共读山中书。","石田可耕水可钓，安得斯人与同调。"]},{"t":"谢杜医士为叶百户赠","f":"七言古诗","c":["浣花老翁好孙子，家住盐官忠义里。","幼读神农黄帝书，青年卖药居城市。","今夏括苍叶守中，卧病兼旬不能起。","更医至再复至三，孰辨阴阳明表里。","城中杜子有家学，分得桑君上池水。","捷如壮士当敌场，百步穿杨誇一矢。","昔也父母及诸弟，仓皇惊怕走折趾。","今也怡然北堂下，笑舞莱衣具甘旨。","五月归从白玉京，琼玖安能酬木李。","触热敲门求我歌，好雨洗秋凉入髓。","勖哉杜子须努力，积土为山自今始。","而翁天外如有闻，化鹤归来心亦喜。"]},{"t":"题罗小川山水图奉和耆山真人诗韵","f":"古风","c":["平生爱画入骨髓，出门万里皆山川。","周南太史古辙迹，愧我白头非壮年。","稚川父子有家法，何异万选青铜钱。","每于江海见遗墨，一纸千金人共怜。","匡庐秀出南斗傍，赤日倒射香炉烟。","金光璧采绚林壑，使我一览神超然。","天鸡喈喈而喔喔，火龙蜿蜿而蜒蜒。","东分蓬莱五鳌股，西擘太华三峰莲。","乃知意匠夺天巧，声价肯让它人先。","瀛洲仙子何翩翩，雾阁云窗常昼眠。","直疑槫桑与若木，根盘旸谷通虞渊。","耆山真人好事者，笔势倒翻三峡泉。","安期枣如瓜，玉井藕如船。","何当为我蜕凡骨，神游八极齐乔佺。"]},{"t":"题贺节妇卷","f":"古风","c":["秦乌啼哑哑，少妇在边姑。","在家妇从万里拾，夫骨恨身不与夫。","同殁一兔百逐良可怜，形影相依今十年。","镜中宁使断绿发，头上安可无青天。","夫入九泉无复见，何日登堂见姑面。","妾无锦字织回文，妾无胡笳写哀怨。","代妾陈情范子勋，放妾还家宋将军。","妾年至死何以报，愿夫再生姑不老。"]},{"t":"题张母徐氏贞节诗","f":"七言古诗","c":["由拳城外鸳鸯湖，鸳鸯交颈依菰蒲。","雄殁雌存形影孤，矢死不学双飞凫。","良人赠妾明月珠，嫁时系在红罗襦。","夫今在地妾有雏，卖珠日给堂上姑。","打门无吏夜索租，挑镫有女寒辟纑。","女工纺绩儿读书，妾死不惭泉下夫。"]},{"t":"题剡溪书屋","f":"古风","c":["朝望青山云，夕望剡溪月。","我思剡溪人，欲载剡溪雪。","笑杀山阴王子猷，一时兴尽回扁舟。","早识山中有羊仲，放船也作东吴游。","羊家结屋溪南住，正是好山环碧处。","门前水涨柳花湾，钓船一夜高于树。","阿翁看山不下堂，两儿翩翩如凤凰。","大儿才力健，射策登朝行。","小儿天姿高，十五工文章。","至今双髻亭亭削寒玉，玉带蜿蜒走崖谷。","读书声隔碧萝间，夜夜虹光照秋屋。","翁今岁晚江上归，有约明年寻剡溪。","野航载山不载雪，系在屋东杨柳枝。"]},{"t":"题金寿堂","f":"七言古诗","c":["世间万物皆可变，唯有黄金能百鍊。","龚家慈母出邓林，贞节可比千黄金。","黄金善祝慈母寿，黄金莫铸慈母心。","孝子爱亲如爱日，百年一刻千金直。","大书金寿揭高堂，愿母与日同其长。"]},{"t":"送戴伯聚还天台","f":"古风","c":["戴先生，住在龙山之下迂江之湄。","平生读书忘渴饥，三旬九食寒无衣。","口掉三寸舌，不顾人是非。","前年别华顶，来游东海涯。","今年还天台，去采黄金芝。","秋风萧萧吹苧衣，遥望宫前浮云飞。","岂不闻苏季子六国印，百里奚五羖皮。","人生出处各有时，子当还山歌我诗。"]},{"t":"美妾换马","f":"古风","c":["妾重千金躯，君爱千里足。","共怜逸足疾如飞，谁念贞妾美如玉。","妾今出门去，无复侍华堂。","寸心何以报，愿作青丝缰。"]},{"t":"题具庆堂","f":"古风","c":["陈绮席，进华觞，听我长歌具庆之高堂。","太学儒生忠孝士，矫首南云几千里。","堂上双亲八十馀，堂下玉立三兄弟。","东家积得金满籯，何如教子传一经。","西家作官金络马，何如种萱北堂下。","陈绮席，进华觞，听我长歌具庆之高堂。","儿在远道，亲归故乡。","儿业日以广，亲年日以长。","它年紫诰鸾回纸，圣德如天无远迩。","请看进士欧阳詹，不在亲傍亲亦喜。"]},{"t":"挽道士","f":"楚辞体","c":["有羽人兮在玄都，白玉为佩青霞裾。","手掉五色金芙蕖，飘然骑云游紫虚。","呼吸元气洪濛初，阅尽三洞天皇书。","江风萧萧岁云徂，寒月堕涧冰蟾孤。","玉棺千年?龙且，嗟羽人兮不可呼。"]},{"t":"赠道士","f":"古风","c":["我思仙人，乃在三神山，何年误落尘网间。","浪游江海不归去，碧桃落尽春风閒。","春风閒，瑶草绿。","来日燕辞巢，归时莺出谷。","黄金之阙白玉城，手把芙蓉朝太清。","安得从师入山去，醉骑鸾背吹瑶笙。"]},{"t":"赠上清道士","f":"七言古诗","c":["天上仙人碧落卿，冰弦入手风泠泠。","一弹山中别鹤操，再弄谷口樵歌声。","是日同登玉虚阁，碧窗片片桃花落。","恍然坐我凤麟洲，琼珥瑶环下寥廓。","师今复上耆山颠，洗耳更听幽涧泉。","钧天别有太古调，此曲不许人间传。"]},{"t":"题桂菊双清图","f":"楚辞体","c":["白帝司秋运金气，空山草木皆凄厉。","嗟尔桂树青团团，直与佳菊凌霜寒。","贞姿孤洁同晚岁，何异幽人逸士栖岩峦。","我所思兮淮南之小山，白石凿井金为阑。","手招八公鍊神丹，骖鸾翳凤游其间。","侧身西望柴桑里，南山悠然当面起。","处士兮归来，尊有酒兮甘且旨。","石磊磊兮葛绵绵，玄豹号林兮长鲸阻川。","折遗芳兮寄远歌，招隐兮期长年。"]},{"t":"来鹤亭","f":"古风","c":["鹤不来，云悠悠，十年无书寄扬州。","仙人五城十二楼，玉箫声断琼花秋。","黄埃四塞不可以久留，安得从之上瀛洲。","鹤不来，云悠悠。"]},{"t":"东桧轩图","f":"七言古诗","c":["悟空塔前双桧树，化龙已上诸天去。","犀牛扇子破多时，欲觅牛儿无觅处。","千年公案重于山，还我牛儿竟不还。","桧树东边结庐者，亦欲置在犀牛间。","画史安能知许事，此中真有西来意。","莫论桧东与桧西，且复还我犀牛儿。"]},{"t":"题红梅","f":"七言古诗","c":["东方风来吹碧雪，群妃醉蹋瑶池月。","中有仙人萼绿华，珠佩霓裳最清绝。","别来仿佛三千年，綵云梦隔蓬莱天。","蓬莱宫中花鸟使，几见海水为桑田。","东家步障霞绡暖，不惜千金买池馆。","春归红叶玉箫閒，月冷海棠银烛短。","何如托根王君家，不学人间儿女花。","昨日刘郎笑相赠，天台有约饭胡麻。"]},{"t":"还山吟送天台王徵君","f":"楚辞体","c":["巍巍乎，天台之山四万八千丈兮，联冈叠障绵亘乎东南。","神鳌戴山俨不动，但见螺髻涌出矗矗青瑶簪。","三更鸡鸣海水赤，丹霞紫雾浮晴岚。","上方钟磬落天外，白日花飞优钵昙。","嗟哉胜境可望不可即兮，金堂石室何由探。","神仙中人王子乔，颜如丹砂发毵毵。","偶从东海一相见，调笑共作烟霞谈。","手持天孙五云锦，冰丝袅袅缫吴蚕。","飘然别我复长往，解缨去濯桃花潭。","天风吹散华顶雪，曹娥江水青于蓝。","舵楼晚饭坐天上，拂云鸟翼张高帆。"]},{"t":"梦天","f":"七言律诗","c":["夜飞八翼登天门，濯发明河披素云。","玉琯双回白鸾背，珠露泠然湿秋佩。","泰阶煌煌明六符，东方白榆长不枯。","拾得天孙机下石，何劳问卜过成都。"]},{"t":"题竹雪山房","f":"古风","c":["吾闻王内史，种竹在山阴。","人见此君节，不知此君心。","昔年读书脩竹林，积雪拥门三尺深。","一庭夜月琼瑶色，万壑天风环佩音。","我知此君最清绝，岁晚相看面如铁。","正色比公头上冠，爽气随公手中节。","青骢蹋遍江南霜，请持玉节朝紫皇。","裁为凤凰十二琯，坐使寒谷回春阳。"]},{"t":"题望云图","f":"古风","c":["叶先生住在四万八千丈之天台，霞气直接东蓬莱。","天鸡三鸣海水赤，春风几度桃花开。","胡为家山看不足，剪得匡庐云一幅。","春晖在青天，寸草在黄土。","中有一寸心，何以报慈母。","关西余氏母在堂，堂下宜男春日长。","九华西浙宦游处，白玉种此双儿郎。","儿今长大过三十，寸草春晖报何及。","岂无鲁阳戈为驻西飞乌，岂无万丈绳为挽羲和车。","春晖在天草在地，母子同跻太平世。","更愿传家好子孙，大书特书忠孝门。"]},{"t":"神石","f":"楚辞体","c":["有石有石在空坑，宋朝文相避元兵。","单骑脱急无留行，石堕空坑如陨星。","追兵不及相乃生，人言此石山之灵。","天佑信国全忠贞，重为告曰石兮石。","兮尔之生也甚奇，怪胡不锻鍊五色。","上补青天青呜呼，共工一触天柱折。","孟姜一哭长城崩，谁谓土石终无情。","至今乡人号神石，奸雄过之当屏迹。"]},{"t":"义虎","f":"楚辞体","c":["有虎有虎在空山，孝子夏贵庐其间。","呼天长号病不起，虎衔野鹿活孝子。","虎也日与孝子亲，相随出入三十春。","孝子起为宋大将，专城总督淮西军。","将军一朝思纳土，虎亦咆哮触其怒。","虎死在地魂上天，将军掉尾求生全。","重为告曰：虎兮虎兮，尔之生也甚雄伟。","杀身成仁有如此，胡不化为忠义士。","董狐之笔良可纪，万古千秋照青史。"]},{"t":"题画","f":"七言律诗","c":["露华凝寒玉蟾泣，张生手泼金壶汁。","神鳌戴山海水立，白龙嘘云元气湿。","毫端妙夺造化功，傍人云是米南宫。","赠尔波斯螺万斛，写我匡庐看飞瀑。"]},{"t":"题恬淡轩为储都司作","f":"古风","c":["淮之水，出自桐柏山，千盘万折流入江河间。","将军好文兼好武，清似流泉出山下。","手提长剑镇雄藩，马前奔走皆貔虎。","龙骧万斛出海洋，西略月窟东槫桑。","天弧夜半射天狼，鲸波帖帖青镜光。","归看山中恬淡水，方寸澄清亦如此。","方寸澄清亦如此，万岁千秋报天子。"]},{"t":"长安道","f":"七言古诗","c":["长安道上花纷纷，红雾涨天飞作尘。","东里雕甍耀白日，西街骏马嘶青云。","长安少年不知老，凤管龙笙春亦好。","昨日牡丹何处花，今朝鹦䳇谁家鸟。","韶华过眼易消磨，杨柳纤腰愁思多。","不见古来歌舞地，夜深风雨泣铜驼。"]},{"t":"题来鹤轩为张佥宪作","f":"七言古诗","c":["张君持节洪之都，左招洪崖右麻姑。","仙人骐骥不可驭，何以得此当庭除。","雪作衣裳丹作顶，戛然长鸣延素颈。","夜榻时闻竹下声，午阶每弄花间影。","九重荡荡天门开，曾侍玉皇香案来。","乃知君身有仙骨，地位清寒霜满台。","只今笼之往何处，为言携向英山去。","我亦东归寻故丘，结巢愿托三珠树。"]},{"t":"寿友人","f":"古风","c":["寄我以中山玄兔之秋颖，寄君以东海麻姑之锦书。","仙翁一尺苍虬须，昨来海上骑鲸鱼。","翱翔白龙宫，簸弄明月珠。","我欲酌以迎风含露之玉壶，仙翁飘然夜回车。","别来可望不可即，绿水荡漾秋芙蕖。","绛河彤云流碧虚，仰见南极当天衢。","星宫之君曳霞裾，挥手招我来斯须。","东方小儿学仙术，年年梦想蟠桃实。","棹歌声落藕花洲，今岁玉桃偷不得。","诸郎一一青琼枝，谢家兄弟田家儿。","门前紫荆花满树，数月不见长相思。","阿翁白头种丹杏，卖杏积谷防年饥。","诸郎称觞杏阴里，芙蓉出鼎丹光起。","岂不闻古来九世张公艺，我愿仙翁传百世。"]},{"t":"题礼部郎中安公山行诗卷","f":"古风","c":["安使君，来自蓬莱东，手持绛节凌天风。","水晶宫中好山色，七十二弁青芙蓉。","树阴暂繫青骢马，行部咨询到山野。","倾筐紫蕨小儿拳，出网白鱼鲜可鲊。","浮玉山前一叶舟，黄帽隔溪歌棹讴。","天上神仙思下土，行当献纳凤池头。"]},{"t":"题天台山人山水图","f":"古风","c":["天台之山四万八千丈，我昔飞梦登其颠。","三更鸡鸣海水赤，白云万顷皆琼田。","长松如龙倚绝壁，飞瀑悬崖练花白。","仙人邀我饭胡麻，洞府高寒留不得。","却从天姥蹋虹霓，独抱明河秋月归。","别来此境不复到，空谷夜夜青猿啼。","丹丘有客持束绢，使我玩之神不倦。","林峦暝色隔烟萝，仿佛当年梦中见。","故山桃花今有无，刘郎何不归仙都。","刘郎何不归仙都，莫向人间寻画图。"]},{"t":"题二乔玩月图","f":"古风","c":["皎皎天上月，照见大江流。","江流去无已，月色满高楼。","乔家二女在舒州，凭高望月楼上头。","金波滟滟绮疏夕，玉露盈盈罗袜秋。","自从嫁得英雄婿，不知月落谁家去。","千古山河影在天，江水东流年复年。"]},{"t":"题七马图为张将军作","f":"古风","c":["七马来自流沙西，二十有八玉凿蹄。","时平四海罢征战，华山之阳春草肥。","一匹龁草，两匹洗刷临清溪。","中有两匹络青丝，奚官傍立不敢骑。","明当进入天门下，一一金鞍盖黄帕。","汉家不用千里才，只许将军看图画。"]},{"t":"送禢二令弟秉德还南雄迎父","f":"古风","c":["买船何之之南雄，洞庭木落生秋风。","大帆中流夹双橹，南望庾岭青丛丛。","禢郎去家五千里，白云日日山头起。","浩荡春晖一寸心，深恩较比三湘水。","湘水有时尽，此恩何时忘。","上堂进甘旨，下堂食槟榔。","槟榔可食鱼可脍，白发明年过吴会。","长安桥边杨柳青，马上看花同一醉。"]},{"t":"题望峡轩","f":"楚辞体","c":["巍巍乎紫薇之山兮，双峰并峙乎西东。","上干织女之银浦，下瞰蛟人之贝宫。","天鸡三唱海日红，云窗雾阁风玲珑。","俞家兄弟构华屋，空翠飞落轩楹中。","堂上有亲颜色好，长年服食金光草。","笑倾阿母九霞觞，啖以安期玉文枣。","三年仲子在成均，回望天南多白云。","每凭海鹤附书至，遥见两峰如见亲。","俞生俞生忠孝者，行看赤车驰驷马。","前度刘郎未足誇，重来还对紫薇花。"]},{"t":"赠太医院使戴元礼","f":"古风","c":["戴先生，好神仙。","朝侍玉皇之香案，暮游金华之洞天，采药不上蓬莱船。","餐青霞，鍊丹砂，骑云翱翔太清家。","九重日月生光华，千秋万年乐无涯。"]},{"t":"祷雨歌赠杨鍊师","f":"古风","c":["杨鍊师，爱神仙，乃在碧海之东偏。","仙人魏伯阳，丹成上青天。","灵符玉文洞玄玄，鍊师得之宝其传，凝神专气合自然。","前年在袁州，夏秋大旱不得雨，山泽草木生炎烟。","去年海若犯河伯，秋潮涨沙龟坼田。","今年魃也，肆恶如火烧平原。","万口嗷嗷不自活，命如一发千钧悬。","鍊师不笑亦不言，仗剑一呼龙出渊。","手挽天河注长川，雷公电母相后先。","己巳及辛未，一岁祷一雨，遂令老稚饱饭歌丰年。","杨鍊师，通神明，长身玉立方瞳青。","公田及私秋有成，功不自受归冥冥。","灵风吹旗海气鯹，醉骑黄鹤吹瑶笙。","请以海门山前龙眼千尺浪，和我一曲空歌声。"]},{"t":"代王奉祠赠别友人之京","f":"七言古诗","c":["春风吹江春雪晴，茶官放船明日行。","奉祠过我索长句，把酒出饯钟陵城。","沈郎有母华亭住，三载思家不归去。","侧身东望白云飞，长绕九龙峰顶树。","今年报政上京华，还种北堂萱草花。","不学江州白司马，直将哀怨寄琵琶。","愧我梁园老宾客，与尔从来未相识。","稍待金芽入贡馀，纱帽笼头共煎吃。"]},{"t":"送知县陈仲信之建昌","f":"五言古诗","c":["朝游甘棠堤，夕游甘棠堤。","堤上夜来雨，秋风闻马嘶。","借问向何处，驾言南康去。","香炉生紫烟，五老欠延伫。","山中瀑布水，散为九江流。","江流二千里，还归东海头。","海中有鲤鱼，好寄平安字。","手把钓鳌竿，时时候书至。"]},{"t":"铁箭辩","f":"七言古诗","c":["凤凰山下通江门，钱王铁箭今尚存。","世传当时有三箭，两箭沈沙俱不见。","唯留一箭在江头，此箭不随江水流。","壮士摩挲撼其镞，根株下贯金鳌足。","出地曾无一尺高，定知作则捍波涛。","始丰先生真好辩，直指是幢非是箭。","雨淋日炙四百年，孤星煌煌长在天。"]},{"t":"题东山清隐图","f":"古风","c":["南山莫采菊，北山莫移文。","西山食薇终不饱，听我且歌东山之白云。","白云宛在山之下，卜得陂坑葬郎罢。","三年返哺学慈乌，千里按图求骏马。","关山漫漫霜露多，谷口秋风吹女萝。","侧身南望不归去，白发倚门愁奈何。","东山之图不盈尺，时见山头白云白。","山有荔枝江有鱼，儿在天涯重相忆。","只今冠佩登鹓行，谁种忘忧当此堂。","安得仙人缩地诀，日日称觞慈母傍。"]},{"t":"寒食行二首 其一","f":"七言古诗","c":["江南三月梨花雨，寒食邻家哭儿女。","阿爷战死长兄存，二十年来别乡土。","存无信息死无归，胡蝶春风泪满衣。","纸钱空挂枯杨树，存者不知埋骨处。","一百五日年年来，天外游魂何不回。"]},{"t":"寒食行二首 其二","f":"七言古诗","c":["北邙山头生白云，北邙山下多古坟。","借问谁家埋白骨，此中半是洛阳人。","陌头夜夜铜驼哭，冢上萧萧悲宰木。","家贫无地葬遗骸，忍见乌鸢啄人肉。","白日短短云无根，翁仲百年当墓门。","花落春风一杯酒，几家寒食见儿孙。"]},{"t":"送丘朝宗还黄岩","f":"七言古诗","c":["百年三万六千日，先生行年今半百。","文章自守一毡寒，勋业频看二毛白。","我持我酒为君歌，四十九年东逝波。","只今富贵须自致，锦衣行昼毋蹉跎。","我生亦是东方朔，往往尊前恣欢谑。","得钱痛饮即忘形，抵掌论交宛如昨。","呼儿手折蔷薇花，山瓶潋滟送流霞。","处士星当霄汉上，异乡吾土挹光华。"]},{"t":"题雪雀图","f":"古风","c":["老竹生棘间，冻禽来上栖，山空雪深相因依。","相因依，岁将暮。","朝阳别有凤凰雏，长在高冈碧梧树。"]},{"t":"题三桂堂","f":"古风","c":["吾闻戴家三儿翩翩如雁行，家有三桂之高堂。","堂中八月风露凉，三儿读书三桂傍。","黄金月中树，白玉天上郎，人言教子有义方。","东家牡丹好池馆，何如三树岁岁凌秋霜。"]},{"t":"题琴轩","f":"古风","c":["山高高，水深深，中有太古之徽音。","姚君手抱绿绮琴，挥我弹彻天地心。","弦中一曲南风调，千载无人识其妙。","水深深，山高高，此乐只许柴桑陶。"]},{"t":"题古木图","f":"七言律诗","c":["萧萧疏疏木叶下，历历落落霜树高。","丹崖寒深老石裂，山风吹月清猿号。","当年画史笔最好，写得乾坤秋气老。","图中转手夺天工，始信黄金未为宝。"]},{"t":"题冰溪送别","f":"古风","c":["冰为溪，玉为山，芙蓉幕府山水间。","夫君三载主画诺，云是能诗谢康乐。","雅怀英英玉在璞，清姿皎皎冰出壑。","玉以比君德，冰以清我心。","笑呼麻姑酒，载歌长短吟。","春雷送雨章，江浔一夜水高三尺深。","君今报政朝天阙，十幅蒲帆挂明月。","冰溪迢迢东入浙，白头病起难为别。","因风寄谢鲍参军，冰玉相期保明哲。"]},{"t":"题李将军九虎图","f":"古风","c":["李将军，家有先世所藏之画图。","图中大小九于菟，一豹驯狎与之俱。","丹崖翠谷行㩻䧢，朝游长林夕负嵎，冯妇见之应下车。","将军佩以黄金符，爪牙捍禦洪崖都。","愿为麒麟与驺虞，此图传家真不虚。"]},{"t":"赠人入浙","f":"七言古诗","c":["老夫暮倚襟江楼，青山西来当屋头。","白云洗空凉雨过，明月不随银汉流。","槐里弟兄交有道，季方更比元方好。","敲门蹋月夜相过，玉树清风满怀抱。","笑呼麻姑青玉浆，仰天邀月月在觞。","须臾各饮数十月，月复挂在天中央。","伯也尊前重告别，明日放舟东入浙。","我身愿为帆上云，我心愿作杯中月。","云随帆去不相离，月落杯中时见之。","画舫西湖载歌舞，荷花杨柳总相思。","老我不归今四夏，近闻湖上多清暇。","竹雪能临内史书，武唐解写王维画。","故人东老最工诗，兴绕南枝与北枝。","若见诸贤烦问讯，梁园词客待多时。"]},{"t":"次凯南清见寄诗韵","f":"七言古诗","c":["白云出山无定姿，白云还山无定期。","乾坤清气不常用，海内复见汤休诗。","昨夜大江深几许，弹舌沙中作龙语。","碧桃红杏满湖开，仿佛云间散花女。","上人正自曹溪归，星斗错落环璿玑。","挥毫烂写怀素草，霹雳应手蛟龙飞。","我今已遂三生梦，石上因缘何足论。","明当载汲洪崖泉，煮茶谈空共栖遁。"]},{"t":"奉张公子歌","f":"古风","c":["戚里张公子，古貌又古心。","面若一尺玉，心如百鍊金。","碧树阴阴绕茅屋，不惜黄金买书读。","有时梦到羲皇前，河洛图书看不足。","白昼呼童扫落花，高閒真似野人家。","堂上灵椿八千岁，綵服裁为五色霞。","白头邂逅洪都市，令我见之心即喜。","今人容貌古人心，一曲长歌吾老矣。"]},{"t":"余辞老还家作中秋见月歌一章留别张公子","f":"古风","c":["我行钟陵道，五见中秋月。","明月流中天，既圆还复缺。","月圆月缺可奈何，今年照见病维摩。","举头见月发，大笑白发较比来时多。","来时黑发今尽白，玉兔有丹医不得。","百年三万六千朝，愿照年年好颜色。","张公子，留侯孙，临风共尔倾一樽。","今古乾坤有清气，此趣勿与它人论。","明当载月东吴去，挂在海门山顶树。","唯有相思一寸心，夜夜莫忘看月处。"]},{"t":"题时习斋","f":"七言古诗","c":["天行九十有万里，日月循环若流水。","人之为学亦犹尔，夜以继日恒不已。","譬诸行远必自迩，跬步千里自兹始。","为以九仞一篑止，半途而废良可耻。","文江有士复质氏，人言是父生是子。","古来圣贤疾没齿，我其铭之吁老矣。"]},{"t":"简员外张士谔","f":"七言绝句","c":["画省题诗白昼閒，春寒系马百花间。","船头载得官瓶酒，来看江南雪后山。"]},{"t":"题扬州玩月图","f":"七言绝句","c":["好月多情不待招，满江风露夜迢迢。","分明记得扬州见，只欠琼花与凤箫。"]},{"t":"蔡河闻雁","f":"七言绝句","c":["白雁南来第一声，蔡州城畔最多情。","闺中此夜应闻得，不道郎行到汴京。"]},{"t":"题钩勒竹","f":"七言绝句","c":["谁写南唐金错刀，秋风叶叶动林皋。","湘灵昨夜云中过，吹落丹山白凤毛。"]},{"t":"题双蟹图","f":"七言绝句","c":["公子无肠玉作膏，毕生偏称左持螯。","画中偶见十六跪，正及黄花秋兴高。"]},{"t":"题红梅","f":"七言绝句","c":["葛洪井畔是仙家，鍊得芙蓉伏火砂。","玉骨年来都蜕尽，不须更服海东霞。"]},{"t":"题钓鱼图","f":"七言绝句","c":["万里清波一镜开，白鸥分占石矶苔。","客星只在桐江上，若个閒人钓得来。"]},{"t":"题桃花流水图为刘山人作","f":"七言绝句","c":["一片飞花水上头，九盘十折涧中流。","胡麻饭熟千年后，却笑诗人也姓刘。"]},{"t":"挽员外张士谔 其二","f":"七言绝句","c":["西子湖头碧草春，天留山水葬诗人。","老逋泉下应相见，为说梅花写得真。"]},{"t":"题雪峰 其一","f":"七言绝句","c":["湘妃庙前江水深，鹧鸪夜啼斑竹林。","峰头积雪高千丈，不隔思家一寸心。"]},{"t":"题雪峰 其二","f":"七言绝句","c":["郎家住在雪峰前，湘水湘云若个边。","一片布帆侬会使，浪平风静早回船。"]},{"t":"避暑图","f":"七言绝句","c":["五月芙蓉水殿凉，红绡新制舞衣裳。","班姬不用题纨扇，咫尺阶前玉树霜。"]},{"t":"题鸡冠","f":"七言绝句","c":["昂然绛帻倚东阑，绝胜丹山五色翰。","想得飞鸣天上去，玉皇分赐紫霞冠。"]},{"t":"闰三月清明","f":"七言绝句","c":["今年又改清明火，此地重看一月花。","多费酒钱三十日，尽留春色在诗家。"]},{"t":"题高士听琴图","f":"七言绝句","c":["一弹太古无弦调，只有柴桑处士知。","回首苍梧叫虞舜，南风何日到朱丝。"]},{"t":"东园晚兴","f":"七言绝句","c":["雨晴阶下看宜男，自汲清泉漱晚酣。","队队云收天一半，纤纤月在屋西南。"]},{"t":"题武夷图","f":"七言绝句","c":["武夷何处觅仙踪，一一林峦紫翠重。","世祀乾鱼真可笑，最高应是大王峰。"]},{"t":"题黄鹤山人画竹","f":"七言绝句","c":["黄鹤仙人去不返，可恨此君相见晚。","高堂六月生秋风，见画令人意萧散。"]},{"t":"渔舟夜月","f":"七言绝句","c":["水底青天洗玉盘，一蓑风露夜生寒。","鸥波不动明如镜，此处停舟最好看。"]},{"t":"闻樵笛","f":"七言绝句","c":["看罢仙人一局棋，自将短笛晚来吹。","白云遮断无寻处，正是东山月上时。"]},{"t":"题系马图","f":"七言绝句","c":["日日黄尘淹马足，谁能占得午阴凉。","天闲刍豆无多恋，好解青丝八尺缰。"]},{"t":"题蕨","f":"七言绝句","c":["一拳打得地皮穿，握住东风不放拳。","直待杜鹃啼血后，展开凤尾始朝天。"]},{"t":"题银杏双鸠图","f":"七言绝句","c":["鸭脚叶青银杏肥，双鸠和梦立多时。","日长庭院无人到，呼雨呼晴总不知。"]},{"t":"题枇杷山鹊图","f":"七言绝句","c":["翠衿丹嘴雪为衣，立在卢家雨后枝。","不是少年金弹子，一双来往莫相疑。"]},{"t":"题梅花白头公图","f":"七言绝句","c":["谁写罗浮梦里云，飞来山鸟意相亲。","傍人莫笑头如雪，占得江南第一春。"]},{"t":"题桃花山鸟图","f":"七言绝句","c":["楚楚山禽好羽衣，小桃枝上立多时。","树头树底无金弹，且向东风自在啼。"]},{"t":"夏日偶成","f":"七言绝句","c":["云气晚从帘外过，雨声凉傍竹边来。","鱼波小簟清如水，北牖南窗面面开。"]},{"t":"题红梨花","f":"七言绝句","c":["玉容寂寞倚东阑，偷得瑶池换骨丹。","昨夜酒酣银烛短，绛绡和月护春寒。"]},{"t":"题红梅为枢上人","f":"七言绝句","c":["散花天女玉娟娟，飞落维摩丈室前。","可是嫣然通一笑，自缘醉里学逃禅。"]},{"t":"题云山图 其一","f":"七言绝句","c":["雨洗千峰栝树青，飞泉落涧晚泠泠。","仙家只在云深处，长伴天边处士星。"]},{"t":"题云山图 其二","f":"七言绝句","c":["若说扬州吴分野，好山只数越中多。","括苍洞口分明见，染出波斯万斛蠃。"]},{"t":"秋夜","f":"七言绝句","c":["高柳疏疏集晚鸦，柴门浑似野人家。","月明露重空阶静，时见芙蓉落一花。"]},{"t":"过陆龟蒙书院","f":"七言绝句","c":["太湖水落秋冥冥，七十二峰相送迎。","扁舟远访天随子，日落荒祠枫叶青。"]},{"t":"题太真教鹦䳇念心经","f":"七言绝句","c":["春寒卯酒睡初醒，笑倚东窗小玉屏。","早悟眼前空是色，错教鹦䳇念心经。"]},{"t":"题白鹇图","f":"七言绝句","c":["我家白鹇白如雪，朝步落花心自閒。","价重连城双白璧，当时笼寄谪仙还。"]},{"t":"促织","f":"七言绝句","c":["月下如抛白玉梭，千丝万缕奈愁何。","佳人夜半停机杼，九曲回肠头绪多。"]},{"t":"题吕仙摘耳图","f":"七言绝句","c":["蓬莱清浅又生尘，消息传来总不真。","料得耳中无一物，先生真是避喧人。"]},{"t":"题红梅为紫微山人作","f":"七言绝句","c":["玉颜老去怕风沙，学得仙人服片霞。","丹井西头曾一见，缟衣都染葛洪砂。"]},{"t":"题墨梅 其一","f":"七言绝句","c":["一夜春寒雪作花，绿毛么凤隔窗纱。","朝来唤醒诗人梦，拣墨留题瘦影斜。"]},{"t":"题墨梅 其二","f":"七言绝句","c":["玉堂仙人冰雪姿，几度月明劳梦思。","画中相见好颜色，只有铁心如旧时。"]},{"t":"题墨梅 其三","f":"七言绝句","c":["疏花倒影净无尘，占得江南第一春。","玉骨近来何太瘦，应知饭颗是前身。"]},{"t":"谢杏林送酒","f":"七言绝句","c":["山瓶春日送流霞，不用青钱付酒家。","草阁暮寒成独酌，醉邀明月上梨花。"]},{"t":"题渔舟图","f":"七言绝句","c":["山下渔舟逐浪开，江平风静好归来。","吴中尽有银丝鲙，莫过瞿塘滟滪堆。"]},{"t":"题竹","f":"七言绝句","c":["昨夜美人骖彩鸾，玉笙吹彻露华寒。","定应斫却月中桂，特地植此青琅玕。"]},{"t":"题天台李氏竹石图 其一","f":"七言绝句","c":["秋风昨夜起林皋，拾得丹山翠凤毛。","拟约仙人吹玉琯，九天环佩碧云高。"]},{"t":"题天台李氏竹石图 其二","f":"七言绝句","c":["天台四万八千丈，中有琅玕石上生。","禹穴南来寻李白，丹霞翠雨满秋城。"]},{"t":"题竹石图","f":"七言绝句","c":["蓬莱石上珊瑚树，精卫衔将出海涛。","昨夜秋风动凉影，叶叶南唐金错刀。"]},{"t":"题红梅","f":"七言绝句","c":["西子湖头快雪消，当时曾见董娇娆。","只今画里浑相似，犹记春风第一桥。"]},{"t":"题马图 其一","f":"七言绝句","c":["五花云散玉连钱，记得回朝下九天。","不用盖鞍黄帕子，绛袍人立御门前。"]},{"t":"题马图 其二","f":"七言绝句","c":["金河春水濯龙媒，应是天门立仗回。","五朵花寒云气湿，紫衣太仆自骑来。"]},{"t":"题玉花骢画","f":"七言绝句","c":["谁写开元玉雪骢，黄门待驾立春风。","南薰殿上承恩日，只说将军画最工。"]},{"t":"题鞋山 其一","f":"七言绝句","c":["一钩凉影度行云，彷佛湖波隔翠裙。","弓样任教江月妒，足音那许世人闻。"]},{"t":"题鞋山 其二","f":"七言绝句","c":["小姑曾此脱金莲，蹴踏风波不计年。","夜半星辰都在水，直疑平步上青天。"]},{"t":"题鞋山 其三","f":"七言绝句","c":["只履何年踏巨鳌，生来浑不怕风涛。","问渠那得根株稳，只为从前著脚牢。"]},{"t":"秋江濯足图","f":"七言绝句","c":["雨馀秋水涨沧浪，孺子能来就晚凉。","寄语东华尘土客，马蹄终日为谁忙。"]},{"t":"江上避暑图","f":"七言绝句","c":["梅花道人厌烦热，自写竹林河朔图。","恰似峰头玉井水，晚凉贮在清冰壶。"]},{"t":"秋思","f":"七言绝句","c":["金井乌啼一叶秋，半规纤月挂银钩。","不知天上双星会，今夜穿针懒下楼。"]},{"t":"出江 其一","f":"七言绝句","c":["扬子江头春雾消，南风吹上午时潮。","白头思家正无赖，隔水桃花人面娇。"]},{"t":"出江 其二","f":"七言绝句","c":["黄帽阿郎歌棹讴，手牵百丈上山头。","上山艰难下山易，送得几多名利舟。"]},{"t":"见新月思家有作 其一","f":"七言绝句","c":["初三初四月如钩，照见江水向东流。","家人今夜应望月，不知郎在大江头。"]},{"t":"见新月思家有作 其二","f":"七言绝句","c":["初三初四月钩弯，郎在船头望远山。","月似蛾眉山似黛，如何不念镜中鬟。"]}]};